module ComfyUI.Assets.ApiCwoz8OZJsMap

let file = """{"version":3,"file":"api-Cwoz8_OZ.js","names":[],"sources":["../../src/config/clientFeatureFlags.json","../../src/platform/auth/apiAuthProvider.ts","../../src/platform/auth/authCredential.ts","../../src/platform/auth/session/sessionMediaUrl.ts","../../packages/account-core/src/core/ssoRequired.ts","../../packages/account-core/src/core/exchange.ts","../../packages/account-core/src/core/credentialCache.ts","../../packages/account-core/src/core/requestTimeout.ts","../../packages/account-core/src/core/sessionTokenMint.ts","../../packages/account-core/src/core/webSession.ts","../../src/platform/auth/session/webSessionFetch.ts","../../src/scripts/apiTimeouts.ts","../../packages/account-core/src/core/identity.ts","../../packages/account-core/src/firebaseAuthError.ts","../../packages/account-core/src/firebase/popupWatch.ts","../../packages/account-core/src/firebase/index.ts","../../src/config/firebase.ts","../../src/platform/auth/firebaseIdentity.ts","../../src/platform/auth/session/webSessionUser.ts","../../src/utils/sessionFeatureFlagOverride.ts","../../src/lib/litegraph/src/types/widgets.ts","../../src/types/linkId.ts","../../src/types/rerouteId.ts","../../src/platform/workflow/validation/schemas/workflowSchema.ts","../../src/schemas/resultItemTypeSchema.ts","../../src/platform/remote/comfyui/execution/types.ts","../../src/platform/remote/comfyui/jobs/jobTypes.ts","../../src/platform/remote/comfyui/jobs/fetchJobs.ts","../../src/scripts/api.ts"],"sourcesContent":["{\n  \"supports_preview_metadata\": true,\n  \"supports_manager_v4_ui\": true,\n  \"supports_progress_text_metadata\": true\n}\n","import type { AuthHeader } from '@/types/authTypes'\n\nexport interface RetrySignalLifecycle {\n  clearInitialTimeout: () => void\n  createSignal: () => AbortSignal | undefined\n}\n\n/**\n * Credentials and retry policy the API client applies to every request.\n * The client itself knows nothing about Firebase or workspace sessions;\n * the composition root installs a provider for the current distribution.\n */\nexport interface ApiAuthProvider {\n  waitForInitialization(): Promise<void>\n  getAuthHeader(): Promise<AuthHeader | null>\n  getAuthToken(): Promise<string | undefined>\n  shouldRetryOn401(): Promise<boolean>\n  fetch(\n    input: RequestInfo | URL,\n    init: RequestInit,\n    retryOn401: boolean,\n    retrySignalLifecycle?: RetrySignalLifecycle\n  ): Promise<Response>\n}\n\nexport const anonymousApiAuthProvider: ApiAuthProvider = {\n  waitForInitialization: async () => {},\n  getAuthHeader: async () => null,\n  getAuthToken: async () => undefined,\n  shouldRetryOn401: async () => false,\n  fetch: (input, init) => fetch(input, init)\n}\n","import type {\n  ApiKeyAuthHeader,\n  AuthCredential,\n  AuthHeader,\n  LoggedInAuthHeader\n} from '@/types/authTypes'\n\nconst HEADER_CREDENTIAL = {\n  Authorization: 'bearer',\n  'X-API-KEY': 'api-key'\n} as const satisfies Record<\n  keyof LoggedInAuthHeader | keyof ApiKeyAuthHeader,\n  AuthCredential\n>\n\n/** The credential kind an auth header carries; `none` when it carries neither. */\nexport function authCredentialOf(header: AuthHeader | null): AuthCredential {\n  if (header === null) return 'none'\n  const headerKey = Object.keys(HEADER_CREDENTIAL).find((key) => key in header)\n  return headerKey === undefined\n    ? 'none'\n    : HEADER_CREDENTIAL[headerKey as keyof typeof HEADER_CREDENTIAL]\n}\n\n/**\n * Delivers a credential kind to a diagnostics callback without letting the\n * callback affect the request: telemetry must fail open.\n */\nexport function notifyAuthCredential(\n  callback: ((credential: AuthCredential) => void) | undefined,\n  credential: AuthCredential\n): void {\n  try {\n    callback?.(credential)\n  } catch (error) {\n    console.warn('onAuthCredential callback failed:', error)\n  }\n}\n","const MEDIA_ROUTE =\n  /^(?:\\/api)?\\/(?:view|viewvideo|vhs\\/viewvideo|vhs\\/viewaudio|assets\\/[^/?#]+\\/content)(?:\\?|$)/\n\n/**\n * Names the workspace on a media route, which an image or video tag loads\n * without headers; absent means the personal workspace.\n */\nexport function scopeMediaRoute(\n  route: string,\n  workspaceId: string | undefined\n): string {\n  if (!workspaceId || !MEDIA_ROUTE.test(route)) return route\n  if (/[?&]workspace_id=/.test(route)) return route\n  const separator = route.includes('?') ? '&' : '?'\n  return `${route}${separator}workspace_id=${encodeURIComponent(workspaceId)}`\n}\n","import { zErrorResponse } from '@comfyorg/ingest-types/zod'\n\n/**\n * ingest's 403 `code` for an account or workspace an SSO organization holds,\n * reached with a credential that is not an SSO sign-in. Every route answers\n * it, anonymous ones included.\n */\nexport const SSO_REQUIRED_SERVER_CODE = 'sso_required'\n\nexport function isSsoRequiredRefusal(status: number, body: unknown): boolean {\n  return (\n    status === 403 &&\n    zErrorResponse.safeParse(body).data?.code === SSO_REQUIRED_SERVER_CODE\n  )\n}\n\n/**\n * The organization whose SSO the refusal asks for, when ingest names one. A\n * workspace accepts only its own organization's sign-in, so this outranks the\n * organization the email's domain would discover.\n */\nexport function ssoRequiredOrganizationId(body: unknown): string | undefined {\n  return zErrorResponse.safeParse(body).data?.organization_id || undefined\n}\n\n/**\n * ingest's 403 `code` for an account off the verified domains of the SSO\n * organization that holds the workspace: no sign-in admits it there.\n */\nconst ACCOUNT_OUTSIDE_ORGANIZATION_SERVER_CODE = 'account_outside_organization'\n\nexport function isAccountOutsideOrganizationRefusal(\n  status: number,\n  body: unknown\n): boolean {\n  return (\n    status === 403 &&\n    zErrorResponse.safeParse(body).data?.code ===\n      ACCOUNT_OUTSIDE_ORGANIZATION_SERVER_CODE\n  )\n}\n","/**\n * The pure token exchange: POST the signed-in identity's Firebase token to\n * the workspace JWT endpoint, parse the generated contract, and return a\n * usable credential or a coded failure. No state, no storage, no identity\n * ownership — the caller owns all of that and passes the request body (an\n * empty body resolves the personal workspace; `{ workspace_id }` targets\n * one). Cancelable by the caller's signal and bounded by a timeout, which\n * the production store's timer-scheduled callers did not need.\n */\nimport { zExchangeTokenResponse } from '@comfyorg/ingest-types/zod'\n\nimport {\n  isSsoRequiredRefusal,\n  ssoRequiredOrganizationId\n} from './ssoRequired.js'\nimport type {\n  AccountCredential,\n  AccountUser,\n  SessionErrorCode,\n  SessionFailure,\n  SessionResult\n} from './sessionContracts.js'\n\nexport const CredentialResponseSchema = zExchangeTokenResponse\n\n/** 401/403/404 carry their own codes; everything else is one failure bucket. */\nfunction codeForResponse(status: number): SessionErrorCode {\n  if (status === 401) return 'INVALID_FIREBASE_TOKEN'\n  if (status === 403) return 'ACCESS_DENIED'\n  if (status === 404) return 'WORKSPACE_NOT_FOUND'\n  return 'TOKEN_EXCHANGE_FAILED'\n}\n\ntype Refusal = Pick<SessionFailure, 'code' | 'organizationId'>\n\n/** Only a 403's body is read: it tells an SSO refusal from any other. */\nasync function refusalFor(\n  response: Response,\n  signal: AbortSignal\n): Promise<Refusal> {\n  const code = codeForResponse(response.status)\n  if (code !== 'ACCESS_DENIED') return { code }\n  let body: unknown\n  try {\n    body = await abortable(response.json(), signal)\n  } catch {\n    return { code }\n  }\n  if (!isSsoRequiredRefusal(response.status, body)) return { code }\n  const organizationId = ssoRequiredOrganizationId(body)\n  return organizationId === undefined\n    ? { code: 'SSO_REQUIRED' }\n    : { code: 'SSO_REQUIRED', organizationId }\n}\n\nexport function abortable<T>(\n  promise: Promise<T>,\n  signal: AbortSignal\n): Promise<T> {\n  if (signal.aborted) {\n    return Promise.reject(new DOMException('Aborted', 'AbortError'))\n  }\n  return new Promise<T>((resolve, reject) => {\n    const onAbort = () => reject(new DOMException('Aborted', 'AbortError'))\n    signal.addEventListener('abort', onAbort, { once: true })\n    promise.then(\n      (value) => {\n        signal.removeEventListener('abort', onAbort)\n        resolve(value)\n      },\n      (error: unknown) => {\n        signal.removeEventListener('abort', onAbort)\n        reject(error)\n      }\n    )\n  })\n}\n\nexport interface ExchangeRequest {\n  readonly exchangeUrl: string\n  readonly body: Record<string, unknown>\n  readonly fetchImpl: typeof fetch\n  readonly signal: AbortSignal | undefined\n  readonly timeoutMs: number\n  readonly now: () => number\n}\n\nexport async function exchangeToken(\n  user: AccountUser,\n  request: ExchangeRequest\n): Promise<SessionResult> {\n  const { exchangeUrl, body, fetchImpl, signal, timeoutMs, now } = request\n  if (signal?.aborted) {\n    return { status: 'error', code: 'TOKEN_EXCHANGE_FAILED' }\n  }\n\n  const controller = new AbortController()\n  const abort = () => controller.abort()\n  signal?.addEventListener('abort', abort, { once: true })\n  const timeout = setTimeout(() => controller.abort(), timeoutMs)\n\n  try {\n    let idToken: string\n    try {\n      idToken = await abortable(user.getIdToken(), controller.signal)\n    } catch (error) {\n      // A missing identity token is NOT_AUTHENTICATED; an identity failure\n      // carrying that code keeps it, anything else (including our own abort)\n      // stays in the transient bucket.\n      const coded =\n        !controller.signal.aborted &&\n        typeof error === 'object' &&\n        error !== null &&\n        'code' in error &&\n        error.code === 'NOT_AUTHENTICATED'\n      return {\n        status: 'error',\n        code: coded ? 'NOT_AUTHENTICATED' : 'TOKEN_EXCHANGE_FAILED'\n      }\n    }\n\n    let response: Response\n    try {\n      response = await fetchImpl(exchangeUrl, {\n        method: 'POST',\n        headers: {\n          Authorization: `Bearer ${idToken}`,\n          'Content-Type': 'application/json'\n        },\n        body: JSON.stringify(body),\n        signal: controller.signal\n      })\n    } catch {\n      return { status: 'error', code: 'TOKEN_EXCHANGE_FAILED' }\n    }\n\n    if (!response.ok) {\n      return {\n        status: 'error',\n        ...(await refusalFor(response, controller.signal)),\n        httpStatus: response.status\n      }\n    }\n\n    let rawBody: unknown\n    try {\n      // The timeout stays armed through the body read: headers arriving does\n      // not bound the body, and a stalled body must abort like a stalled connect.\n      rawBody = await abortable(response.json(), controller.signal)\n    } catch {\n      return {\n        status: 'error',\n        code: 'TOKEN_EXCHANGE_FAILED',\n        httpStatus: response.status\n      }\n    }\n\n    const parsed = CredentialResponseSchema.safeParse(rawBody)\n    if (!parsed.success) {\n      return {\n        status: 'error',\n        code: 'TOKEN_EXCHANGE_FAILED',\n        httpStatus: response.status\n      }\n    }\n    // Date.parse can yield NaN on a schema-valid string, so the expiry is\n    // checked after the schema. A token dead on arrival can never authorize\n    // anything; a short-but-future one is left to the valid-on-read path; an\n    // empty token is never a session.\n    const expiresAt = Date.parse(parsed.data.expires_at)\n    if (\n      Number.isNaN(expiresAt) ||\n      parsed.data.token === '' ||\n      expiresAt <= now()\n    ) {\n      return {\n        status: 'error',\n        code: 'TOKEN_EXCHANGE_FAILED',\n        httpStatus: response.status\n      }\n    }\n    const session: AccountCredential = {\n      token: parsed.data.token,\n      expiresAt,\n      uid: user.uid,\n      workspace: parsed.data.workspace,\n      role: parsed.data.role,\n      permissions: parsed.data.permissions\n    }\n    return { status: 'ok', session }\n  } finally {\n    clearTimeout(timeout)\n    signal?.removeEventListener('abort', abort)\n  }\n}\n","import { z } from 'zod'\n\nimport { CredentialResponseSchema } from './exchange.js'\nimport type { AccountCredential } from './sessionContracts.js'\n\n/**\n * Raw string storage for the credential cache. Hosts wrap their medium —\n * per-tab browser storage today, a cookie-backed session tomorrow. Each client\n * instance sees only its own storage: signing out in one tab leaves another\n * tab's session live until the server revokes it and the next remint 401s.\n */\nexport interface CredentialStorage {\n  read: () => string | null\n  write: (value: string) => void\n  clear: () => void\n}\n\n/** The generated contract for POST /api/auth/token, never a local copy of it. */\nconst CachedCredentialSchema = CredentialResponseSchema.omit({\n  expires_at: true\n}).extend({\n  // Storage and broadcast are untrusted boundaries: an empty token can never\n  // authorize and a non-finite expiry can never lapse, so neither is a session.\n  token: z.string().min(1),\n  expiresAt: z.number().finite(),\n  uid: z.string(),\n  /** The workspace target the credential was minted for; absent = personal. */\n  target: z.string().optional()\n})\n\ninterface CachedCredential {\n  readonly credential: AccountCredential\n  readonly target: string | undefined\n}\n\nfunction toCredential(\n  data: z.infer<typeof CachedCredentialSchema>\n): AccountCredential {\n  return {\n    token: data.token,\n    expiresAt: data.expiresAt,\n    uid: data.uid,\n    workspace: data.workspace,\n    role: data.role,\n    permissions: data.permissions\n  }\n}\n\nexport function encodeCached(\n  session: AccountCredential,\n  target: string | undefined\n): string {\n  return JSON.stringify({ ...session, target })\n}\n\nexport function decodeCached(\n  raw: string,\n  uid: string\n): CachedCredential | undefined {\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(raw)\n  } catch {\n    return undefined\n  }\n  const result = CachedCredentialSchema.safeParse(parsed)\n  if (!result.success || result.data.uid !== uid) return undefined\n  return { credential: toCredential(result.data), target: result.data.target }\n}\n\nexport function decodeAdopted(message: unknown): AccountCredential | undefined {\n  const parsed = CachedCredentialSchema.safeParse(message)\n  return parsed.success ? toCredential(parsed.data) : undefined\n}\n\ninterface CredentialCache {\n  read: (uid: string) => CachedCredential | undefined\n  write: (session: AccountCredential, target: string | undefined) => void\n  clear: () => void\n}\n\nexport const DEFAULT_FRESH_MARGIN_MS = 5 * 60 * 1000\n\nexport function isCredentialFresh(\n  session: AccountCredential,\n  now: number,\n  freshMarginMs: number = DEFAULT_FRESH_MARGIN_MS\n): boolean {\n  return session.expiresAt - now > freshMarginMs\n}\n\ninterface CredentialCandidate {\n  readonly credential: AccountCredential | undefined\n  readonly target: string | undefined\n}\n\n/**\n * The live credential is authoritative; storage is recovery state, not a\n * competing source. Candidates are consulted in the order given (memory\n * first, then storage) for this exact uid and target, and the first fresh one\n * wins — expiry must not override this (a rejected token can outlive its\n * shorter-lived replacement), and a target-less read must never adopt a team\n * session.\n */\nexport function selectFreshCredential(\n  candidates: readonly (() => CredentialCandidate | undefined)[],\n  uid: string,\n  target: string | undefined,\n  now: number,\n  freshMarginMs: number\n): AccountCredential | undefined {\n  for (const supply of candidates) {\n    const candidate = supply()\n    if (\n      candidate?.credential?.uid === uid &&\n      candidate.target === target &&\n      isCredentialFresh(candidate.credential, now, freshMarginMs)\n    ) {\n      return candidate.credential\n    }\n  }\n  return undefined\n}\n\nexport function createCredentialCache(\n  storage: CredentialStorage\n): CredentialCache {\n  return {\n    read(uid) {\n      let raw: string | null\n      try {\n        raw = storage.read()\n      } catch {\n        return undefined\n      }\n      return raw === null ? undefined : decodeCached(raw, uid)\n    },\n    write(session, target) {\n      try {\n        storage.write(encodeCached(session, target))\n      } catch {\n        void 0\n      }\n    },\n    clear() {\n      try {\n        storage.clear()\n      } catch {\n        void 0\n      }\n    }\n  }\n}\n","export interface TimedSignal {\n  readonly signal: AbortSignal | undefined\n  /** Disarms the timer; call once the response body has been read. */\n  readonly release: () => void\n}\n\n/** Joins the caller's signal with an abort after `timeoutMs`, if one is set. */\nexport function timedSignal(\n  signal: AbortSignal | undefined,\n  timeoutMs: number | undefined\n): TimedSignal {\n  if (timeoutMs === undefined) return { signal, release: () => undefined }\n  const controller = new AbortController()\n  const timer = setTimeout(() => controller.abort(), timeoutMs)\n  return {\n    signal: signal\n      ? AbortSignal.any([signal, controller.signal])\n      : controller.signal,\n    release: () => clearTimeout(timer)\n  }\n}\n","/**\n * Workspace tokens for services that cannot read the session cookie. The\n * session mints one at `POST /auth/token` on first use, and each token is\n * reused per (session user, workspace) until it nears expiry. Failures come\n * back as web-session codes; nothing here retries or signs out.\n */\nimport {\n  zErrorResponse,\n  zExchangeTokenResponse\n} from '@comfyorg/ingest-types/zod'\n\nimport { isCredentialFresh } from './credentialCache.js'\nimport { COMFY_CLIENT } from './requestAuth.js'\nimport { timedSignal } from './requestTimeout.js'\nimport { SSO_REQUIRED_SERVER_CODE } from './ssoRequired.js'\nimport type {\n  AccountCredential,\n  WebSession,\n  WebSessionErrorCode,\n  WebSessionFailure\n} from './sessionContracts.js'\n\nexport interface SessionTokenMintOptions {\n  /** Ingest API root, e.g. `https://cloud.comfy.org/api`. */\n  readonly apiBaseUrl: string\n  readonly fetchImpl: typeof fetch\n  /** The live web session, or undefined when signed out. */\n  readonly getSession: () => WebSession | undefined\n  readonly now?: () => number\n  /** Re-mint once a cached token has this long left. Default 60s. */\n  readonly refreshBufferMs?: number\n  /** Caps each mint, body included; a timeout is `SESSION_UNAVAILABLE`. Default: none. */\n  readonly timeoutMs?: number\n}\n\nexport interface SessionTokenFailure extends WebSessionFailure {\n  /** From a 429's `Retry-After`; no request is sent until it passes. */\n  readonly retryAfterMs?: number\n}\n\nexport type SessionTokenResult =\n  | { readonly status: 'ok'; readonly credential: AccountCredential }\n  | SessionTokenFailure\n\nexport class SessionTokenError extends Error {\n  constructor(readonly failure: SessionTokenFailure) {\n    super(`Workspace token mint failed: ${failure.code}`)\n    this.name = 'SessionTokenError'\n  }\n}\n\nexport interface SessionTokenMint {\n  /** Never throws: every outcome is a result. */\n  readonly mint: (workspaceId?: string) => Promise<SessionTokenResult>\n  /** Like `mint`, but never serves the cached token; for the one 401 retry. */\n  readonly remint: (workspaceId?: string) => Promise<SessionTokenResult>\n  /** For `createRequestAuthorizer`; rejects with a `SessionTokenError`. */\n  readonly getWorkspaceToken: (workspaceId?: string) => Promise<string>\n}\n\nexport const DEFAULT_REFRESH_BUFFER_MS = 60_000\nconst MAX_RETRY_AFTER_MS = 10 * 60 * 1000\n\ninterface StatusRule {\n  readonly byServerCode: Partial<Record<string, WebSessionErrorCode>>\n  readonly fallback: WebSessionErrorCode\n}\n\nconst STATUS_RULES: Partial<Record<number, StatusRule>> = {\n  401: {\n    byServerCode: {\n      session_expired: 'SESSION_EXPIRED',\n      session_revoked: 'SESSION_REVOKED',\n      TOKEN_REVOKED: 'SESSION_REVOKED'\n    },\n    fallback: 'NO_SESSION'\n  },\n  403: {\n    byServerCode: {\n      csrf_invalid: 'CSRF_STALE',\n      workspace_access_denied: 'WORKSPACE_ACCESS_DENIED',\n      [SSO_REQUIRED_SERVER_CODE]: 'SSO_REQUIRED'\n    },\n    fallback: 'SESSION_REQUEST_REFUSED'\n  },\n  /** The workspace is unknown, deleted, or not the user's: one remedy. */\n  404: {\n    byServerCode: { NOT_FOUND: 'WORKSPACE_ACCESS_DENIED' },\n    fallback: 'SESSION_REQUEST_REFUSED'\n  }\n}\n\nconst zServerCode = zErrorResponse.pick({ code: true })\n\nfunction failure(\n  code: WebSessionErrorCode,\n  httpStatus?: number,\n  serverCode?: string\n): SessionTokenFailure {\n  return {\n    status: 'error',\n    code,\n    retryable: code === 'SESSION_UNAVAILABLE',\n    ...(httpStatus === undefined ? {} : { httpStatus }),\n    ...(serverCode === undefined ? {} : { serverCode })\n  }\n}\n\nasync function readJson(response: Response): Promise<unknown> {\n  try {\n    return await response.json()\n  } catch {\n    return undefined\n  }\n}\n\n/** Retry-After is delay-seconds or an HTTP-date; either is capped. */\nfunction retryAfterMs(value: string | null, nowMs: number): number | undefined {\n  if (value === null) return undefined\n  const seconds = Number(value)\n  const delayMs = Number.isFinite(seconds)\n    ? seconds * 1000\n    : Date.parse(value) - nowMs\n  return delayMs > 0 ? Math.min(delayMs, MAX_RETRY_AFTER_MS) : undefined\n}\n\nfunction rateLimited(response: Response, nowMs: number): SessionTokenFailure {\n  const limited = failure('SESSION_UNAVAILABLE', response.status)\n  const waitMs = retryAfterMs(response.headers.get('Retry-After'), nowMs)\n  return waitMs === undefined ? limited : { ...limited, retryAfterMs: waitMs }\n}\n\nfunction codeFor(status: number, serverCode: string | undefined) {\n  const rule = STATUS_RULES[status]\n  if (rule === undefined) return 'SESSION_REQUEST_REFUSED'\n  return rule.byServerCode[serverCode ?? ''] ?? rule.fallback\n}\n\nfunction classifyFailure(\n  response: Response,\n  body: unknown,\n  nowMs: number\n): SessionTokenFailure {\n  const { status } = response\n  if (status === 429) return rateLimited(response, nowMs)\n  if (status >= 500) return failure('SESSION_UNAVAILABLE', status)\n  const parsed = zServerCode.safeParse(body)\n  const serverCode = parsed.success ? parsed.data.code : undefined\n  return failure(codeFor(status, serverCode), status, serverCode)\n}\n\nexport function createSessionTokenMint({\n  apiBaseUrl,\n  fetchImpl,\n  getSession,\n  now = Date.now,\n  refreshBufferMs = DEFAULT_REFRESH_BUFFER_MS,\n  timeoutMs\n}: SessionTokenMintOptions): SessionTokenMint {\n  const tokenUrl = `${apiBaseUrl.replace(/\\/+$/, '')}/auth/token`\n  /** Keyed by workspace; every entry belongs to `cacheOwner`. */\n  const cache = new Map<string | undefined, AccountCredential>()\n  const inFlight = new Map<string | undefined, Promise<SessionTokenResult>>()\n  let cacheOwner: string | undefined\n  /** Bumped on every owner change, so an older owner's answer never lands. */\n  let ownerGeneration = 0\n  let rateLimit: { until: number; failure: SessionTokenFailure } | undefined\n\n  function adoptOwner(userId: string | undefined): void {\n    if (cacheOwner === userId) return\n    cacheOwner = userId\n    ownerGeneration += 1\n    cache.clear()\n    inFlight.clear()\n    rateLimit = undefined\n  }\n\n  async function request(\n    session: WebSession,\n    workspaceId: string | undefined\n  ): Promise<SessionTokenResult> {\n    const { signal, release } = timedSignal(undefined, timeoutMs)\n    try {\n      const response = await fetchImpl(tokenUrl, {\n        method: 'POST',\n        credentials: 'include',\n        headers: {\n          'Content-Type': 'application/json',\n          'X-Comfy-Client': COMFY_CLIENT,\n          'X-CSRF-Token': session.csrfToken,\n          ...(workspaceId === undefined\n            ? {}\n            : { 'X-Comfy-Workspace-ID': workspaceId })\n        },\n        body: JSON.stringify(\n          workspaceId === undefined ? {} : { workspace_id: workspaceId }\n        ),\n        signal\n      })\n      const body = await readJson(response)\n      if (signal?.aborted) return failure('SESSION_UNAVAILABLE')\n      return response.ok\n        ? credentialFrom(session, response.status, body)\n        : classifyFailure(response, body, now())\n    } catch {\n      return failure('SESSION_UNAVAILABLE')\n    } finally {\n      release()\n    }\n  }\n\n  function credentialFrom(\n    session: WebSession,\n    status: number,\n    body: unknown\n  ): SessionTokenResult {\n    const parsed = zExchangeTokenResponse.safeParse(body)\n    const expiresAt = parsed.success\n      ? Date.parse(parsed.data.expires_at)\n      : Number.NaN\n    if (!parsed.success || parsed.data.token === '' || !(expiresAt > now())) {\n      return failure('SESSION_UNAVAILABLE', status)\n    }\n    return {\n      status: 'ok',\n      credential: {\n        token: parsed.data.token,\n        expiresAt: Math.min(expiresAt, session.expiresAt),\n        uid: session.user.id,\n        workspace: parsed.data.workspace,\n        role: parsed.data.role,\n        permissions: parsed.data.permissions\n      }\n    }\n  }\n\n  function commit(\n    workspaceId: string | undefined,\n    generation: number,\n    result: SessionTokenResult\n  ): void {\n    if (generation !== ownerGeneration) return\n    if (result.status === 'ok') {\n      cache.set(workspaceId, result.credential)\n      return\n    }\n    if (result.httpStatus === 401) cache.clear()\n    if (result.retryAfterMs !== undefined) {\n      rateLimit = { until: now() + result.retryAfterMs, failure: result }\n    }\n  }\n\n  async function mint(workspaceId?: string): Promise<SessionTokenResult> {\n    const session = getSession()\n    adoptOwner(session?.user.id)\n    if (session === undefined) return failure('NO_SESSION')\n    const userId = session.user.id\n\n    // The cache is checked before the backoff on purpose: a caller already\n    // holding a fresh token is still served while new mints wait.\n    const cached = cache.get(workspaceId)\n    if (cached && isCredentialFresh(cached, now(), refreshBufferMs)) {\n      return { status: 'ok', credential: cached }\n    }\n    if (rateLimit && now() < rateLimit.until) {\n      return rateLimit.failure\n    }\n\n    const joined = inFlight.get(workspaceId)\n    if (joined) return joined\n    const generation = ownerGeneration\n    const running = request(session, workspaceId).then((result) => {\n      if (inFlight.get(workspaceId) === running) inFlight.delete(workspaceId)\n      const current = getSession()\n      if (current === undefined) return failure('NO_SESSION')\n      if (current.user.id !== userId) return failure('IDENTITY_CHANGED')\n      commit(workspaceId, generation, result)\n      return result\n    })\n    inFlight.set(workspaceId, running)\n    return running\n  }\n\n  function remint(workspaceId?: string): Promise<SessionTokenResult> {\n    if (!inFlight.has(workspaceId)) cache.delete(workspaceId)\n    return mint(workspaceId)\n  }\n\n  return {\n    mint,\n    remint,\n    async getWorkspaceToken(workspaceId) {\n      const result = await mint(workspaceId)\n      if (result.status === 'ok') return result.credential.token\n      throw new SessionTokenError(result)\n    }\n  }\n}\n","/**\n * Client for the shared web session on ingest (`/api/auth/session*`). It only\n * sends and classifies: retries, boot rules, and sign-out belong to callers.\n * Identity proof is an opaque string from the caller, so no provider leaks in.\n */\nimport {\n  zCreateSessionResponse,\n  zDeleteSessionResponse,\n  zErrorResponse,\n  zGetSessionResponse,\n  zRevokeAllSessionsResponse,\n  zWebSessionUser\n} from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nimport { COMFY_CLIENT } from './requestAuth.js'\nimport { timedSignal } from './requestTimeout.js'\nimport {\n  SSO_REQUIRED_SERVER_CODE,\n  ssoRequiredOrganizationId\n} from './ssoRequired.js'\nimport type {\n  WebSessionCommandResult,\n  WebSessionErrorCode,\n  WebSessionFailure,\n  WebSessionResult\n} from './sessionContracts.js'\n\nexport type {\n  WebSession,\n  WebSessionCommandResult,\n  WebSessionErrorCode,\n  WebSessionFailure,\n  WebSessionResult,\n  WebSessionUser\n} from './sessionContracts.js'\n\nexport interface WebSessionOptions {\n  /** Ingest API root, e.g. `https://cloud.comfy.org/api`. */\n  readonly apiBaseUrl: string\n  readonly fetchImpl: typeof fetch\n  readonly signal?: AbortSignal\n  /** Caps each request, body included; a timeout is `SESSION_UNAVAILABLE`. Default: none. */\n  readonly timeoutMs?: number\n}\n\nconst UNAUTHORIZED_CODES: Readonly<Record<string, WebSessionErrorCode>> = {\n  no_session: 'NO_SESSION',\n  session_expired: 'SESSION_EXPIRED',\n  session_revoked: 'SESSION_REVOKED',\n  TOKEN_REVOKED: 'SESSION_REVOKED'\n}\n\nconst FORBIDDEN_CODES: Readonly<Record<string, WebSessionErrorCode>> = {\n  csrf_invalid: 'CSRF_STALE',\n  workspace_access_denied: 'WORKSPACE_ACCESS_DENIED',\n  [SSO_REQUIRED_SERVER_CODE]: 'SSO_REQUIRED'\n}\n\nfunction failure(\n  code: WebSessionErrorCode,\n  httpStatus?: number,\n  serverCode?: string\n): WebSessionFailure {\n  return {\n    status: 'error',\n    code,\n    retryable: code === 'SESSION_UNAVAILABLE',\n    ...(httpStatus === undefined ? {} : { httpStatus }),\n    ...(serverCode === undefined ? {} : { serverCode })\n  }\n}\n\n/** Adds `has_personal_workspace` until ingest-types carries it. */\nconst zSessionResponse = zGetSessionResponse.extend({\n  user: zWebSessionUser.extend({\n    has_personal_workspace: z.boolean().optional()\n  })\n})\n\nasync function readJson(response: Response): Promise<unknown> {\n  try {\n    return await response.json()\n  } catch {\n    return undefined\n  }\n}\n\n/** Classifies an ingest refusal the way every session call does. */\nexport function classifyWebSessionFailure(\n  status: number,\n  body: unknown\n): WebSessionFailure {\n  if (status === 429 || status >= 500) {\n    return failure('SESSION_UNAVAILABLE', status)\n  }\n  const parsed = zErrorResponse.safeParse(body)\n  if (!parsed.success) return failure('SESSION_REQUEST_REFUSED', status)\n  const serverCode = parsed.data.code\n  const byServerCode =\n    status === 401\n      ? (UNAUTHORIZED_CODES[serverCode] ?? 'NO_SESSION')\n      : status === 403\n        ? (FORBIDDEN_CODES[serverCode] ?? 'SESSION_REQUEST_REFUSED')\n        : 'SESSION_REQUEST_REFUSED'\n  const refusal = failure(byServerCode, status, serverCode)\n  const organizationId =\n    byServerCode === 'SSO_REQUIRED'\n      ? ssoRequiredOrganizationId(body)\n      : undefined\n  return organizationId === undefined ? refusal : { ...refusal, organizationId }\n}\n\ninterface Answered {\n  readonly status: number\n  readonly body: unknown\n}\n\nasync function send(\n  options: WebSessionOptions,\n  path: string,\n  init: RequestInit\n): Promise<Answered | WebSessionFailure> {\n  const { signal, release } = timedSignal(options.signal, options.timeoutMs)\n  try {\n    const response = await options.fetchImpl(\n      `${options.apiBaseUrl.replace(/\\/+$/, '')}${path}`,\n      { ...init, credentials: 'include', signal }\n    )\n    const body = await readJson(response)\n    if (signal?.aborted) return failure('SESSION_UNAVAILABLE')\n    const { status } = response\n    return response.ok\n      ? { status, body }\n      : classifyWebSessionFailure(status, body)\n  } catch {\n    return failure('SESSION_UNAVAILABLE')\n  } finally {\n    release()\n  }\n}\n\nexport async function readWebSession(\n  options: WebSessionOptions,\n  { expectedUserId }: { readonly expectedUserId?: string } = {}\n): Promise<WebSessionResult> {\n  const sent = await send(options, '/auth/session', {\n    method: 'GET',\n    cache: 'no-store'\n  })\n  if ('code' in sent) return sent\n\n  const { status } = sent\n  const parsed = zSessionResponse.safeParse(sent.body)\n  if (!parsed.success) return failure('SESSION_UNAVAILABLE', status)\n  const { user, csrf_token, expires_at, absolute_expires_at } = parsed.data\n  if (expectedUserId !== undefined && user.id !== expectedUserId) {\n    return failure('IDENTITY_CHANGED', status)\n  }\n  return {\n    status: 'ok',\n    session: {\n      user: {\n        id: user.id,\n        email: user.email,\n        name: user.name,\n        emailVerified: user.email_verified,\n        signInProvider: user.sign_in_provider,\n        hasPersonalWorkspace: user.has_personal_workspace\n      },\n      csrfToken: csrf_token,\n      expiresAt: Date.parse(expires_at),\n      absoluteExpiresAt: Date.parse(absolute_expires_at)\n    }\n  }\n}\n\n/**\n * Creates the session, then reads it back for the user and CSRF token. A\n * failure to produce the proof is the provider's error and propagates.\n */\nexport async function createWebSession(\n  options: WebSessionOptions,\n  getIdentityProof: () => Promise<string>,\n  { expectedUserId }: { readonly expectedUserId?: string } = {}\n): Promise<WebSessionResult> {\n  const proof = await getIdentityProof()\n  const sent = await send(options, '/auth/session', {\n    method: 'POST',\n    headers: { Authorization: `Bearer ${proof}` }\n  })\n  if ('code' in sent) return sent\n\n  const parsed = zCreateSessionResponse.safeParse(sent.body)\n  if (!parsed.success || !parsed.data.success) {\n    return failure('SESSION_UNAVAILABLE', sent.status)\n  }\n  return readWebSession(options, { expectedUserId })\n}\n\n/** Sends no CSRF token: sign-out must work against a dead session. */\nexport async function deleteWebSession(\n  options: WebSessionOptions\n): Promise<WebSessionCommandResult> {\n  const sent = await send(options, '/auth/session', { method: 'DELETE' })\n  if ('code' in sent) return sent\n\n  const parsed = zDeleteSessionResponse.safeParse(sent.body)\n  if (!parsed.success || !parsed.data.success) {\n    return failure('SESSION_UNAVAILABLE', sent.status)\n  }\n  return { status: 'ok' }\n}\n\n/**\n * Signs the user out of every device with the session cookie alone. Only a\n * body the contract recognises is ok: the caller tells the user every device\n * is signed out on that answer.\n */\nexport async function revokeAllWebSessions(\n  options: WebSessionOptions,\n  csrfToken: string\n): Promise<WebSessionCommandResult> {\n  const sent = await send(options, '/auth/sessions/revoke-all', {\n    method: 'POST',\n    headers: { 'X-Comfy-Client': COMFY_CLIENT, 'X-CSRF-Token': csrfToken }\n  })\n  if ('code' in sent) return sent\n\n  const parsed = zRevokeAllSessionsResponse.safeParse(sent.body)\n  if (!parsed.success) {\n    return failure('SESSION_UNAVAILABLE', sent.status)\n  }\n  return { status: 'ok' }\n}\n","import type { RequestAuthorizer } from '@comfyorg/account-core/requestAuth'\nimport type { SessionTokenResult } from '@comfyorg/account-core/sessionTokenMint'\nimport { SessionTokenError } from '@comfyorg/account-core/sessionTokenMint'\nimport type {\n  WebSession,\n  WebSessionErrorCode\n} from '@comfyorg/account-core/webSession'\nimport { classifyWebSessionFailure } from '@comfyorg/account-core/webSession'\n\n/** A workspace-token mint failure whose message is localized user-facing copy. */\nexport class WebSessionTokenError extends SessionTokenError {\n  override readonly cause: SessionTokenError\n\n  constructor(original: SessionTokenError, message: string) {\n    super(original.failure)\n    this.message = message\n    this.name = 'WebSessionTokenError'\n    this.cause = original\n  }\n}\n\n/** The user, session epoch and workspace one request was started for. */\nexport interface WebSessionRequestScope {\n  readonly session: WebSession\n  readonly epoch: number\n  /** Absent means the personal workspace. */\n  readonly workspaceId?: string\n}\n\nexport interface WebSessionFetchPorts {\n  /** A fresh session for the same user and epoch, or undefined to abandon. */\n  readonly refresh: (\n    scope: WebSessionRequestScope\n  ) => Promise<WebSessionRequestScope | undefined>\n  readonly workspaceDenied: (workspaceId: string) => void\n  readonly ssoRequired: (scope: WebSessionRequestScope) => void\n  readonly authorize: RequestAuthorizer\n}\n\nasync function refusalCode(\n  response: Response\n): Promise<WebSessionErrorCode | undefined> {\n  if (response.status !== 403) return undefined\n  const body: unknown = await response\n    .clone()\n    .json()\n    .catch(() => undefined)\n  return classifyWebSessionFailure(response.status, body).code\n}\n\n/**\n * Sends one ingest request on the session cookie. `csrf_invalid` is the one\n * refusal a fresh token can fix, so it is retried once for the same user and\n * workspace; `workspace_access_denied` drops that workspace and is returned\n * as is, never replayed elsewhere; `sso_required` is reported and returned.\n */\nexport async function fetchOnWebSession(\n  url: string,\n  init: RequestInit,\n  scope: WebSessionRequestScope,\n  ports: WebSessionFetchPorts\n): Promise<Response> {\n  const send = async (current: WebSessionRequestScope) => {\n    const { headers, credentials } = await ports.authorize(\n      { kind: 'session', session: current.session },\n      {\n        target: 'ingest',\n        method: init.method ?? 'GET',\n        workspaceId: current.workspaceId\n      }\n    )\n    const merged = new Headers(init.headers)\n    for (const [name, value] of Object.entries(headers)) merged.set(name, value)\n    return fetch(url, {\n      ...init,\n      headers: merged,\n      credentials:\n        new URL(url, location.href).origin === location.origin\n          ? 'same-origin'\n          : credentials\n    })\n  }\n\n  const response = await send(scope)\n  const code = await refusalCode(response)\n  if (code === 'WORKSPACE_ACCESS_DENIED' && scope.workspaceId !== undefined) {\n    ports.workspaceDenied(scope.workspaceId)\n  }\n  if (code === 'SSO_REQUIRED') ports.ssoRequired(scope)\n  if (code !== 'CSRF_STALE' || init.body instanceof ReadableStream) {\n    return response\n  }\n  const fresh = await ports.refresh(scope)\n  return fresh ? send(fresh) : response\n}\n\n/** What a signed-in tab's requests need from the web session. */\nexport interface WebSessionRequests {\n  /** Undefined unless this tab is signed in on the session. */\n  readonly scope: () => Promise<WebSessionRequestScope | undefined>\n  /** The signed-in session's team workspace, for URLs that carry no header. */\n  readonly workspaceId: () => string | undefined\n  readonly send: (\n    url: string,\n    init: RequestInit,\n    scope: WebSessionRequestScope\n  ) => Promise<Response>\n  /** The web session's token for this scope's workspace; never rejects. */\n  readonly workspaceToken: (\n    scope: WebSessionRequestScope\n  ) => Promise<SessionTokenResult>\n  /** Mints past the cached token, for a token the server just refused; never rejects. */\n  readonly remintWorkspaceToken: (\n    scope: WebSessionRequestScope\n  ) => Promise<SessionTokenResult>\n  /** Bearer headers for a service other than ingest; mints on first use. Rejects with WebSessionTokenError. */\n  readonly authorizeResource: (\n    scope: WebSessionRequestScope\n  ) => Promise<Readonly<Record<string, string>>>\n}\n\nlet provided: WebSessionRequests | undefined\n\n/** Set while the web session is on for this page load; returns its release. */\nexport function provideWebSessionRequests(\n  requests: WebSessionRequests\n): () => void {\n  provided = requests\n  return () => {\n    if (provided === requests) provided = undefined\n  }\n}\n\nexport function webSessionRequests(): WebSessionRequests | undefined {\n  return provided\n}\n\n/** True when the session is on and this tab is signed in on it. */\nexport async function signedInOnWebSession(): Promise<boolean> {\n  return (await provided?.scope()) !== undefined\n}\n\nexport type WebSessionSend = (\n  url: string,\n  init: RequestInit\n) => Promise<Response>\n\n/** Sends on the signed-in session, or undefined when this tab is not on it. */\nexport async function webSessionSend(): Promise<WebSessionSend | undefined> {\n  const requests = webSessionRequests()\n  if (!requests) return undefined\n  const scope = await requests.scope()\n  return scope && ((url, init) => requests.send(url, init, scope))\n}\n\n/** Undefined unless the session is on and this tab is signed in on it. */\nexport async function webSessionResourceHeader(): Promise<\n  Readonly<Record<string, string>> | undefined\n> {\n  const requests = provided\n  if (!requests) return undefined\n  const scope = await requests.scope()\n  return scope && requests.authorizeResource(scope)\n}\n","/**\n * The request bounds `api.fetchApi` enforces, in their own leaf module so that\n * a caller which must OUTLAST a request can derive its bound from the same\n * numbers instead of restating them.\n *\n * Deliberately not exported from `api.ts`: `src/scripts/__mocks__/api.ts` is\n * the manual mock every `vi.mock('@/scripts/api')` resolves to, and it exports\n * only `api` — so a constant read through that path arrives `undefined` and any\n * arithmetic on it silently becomes `NaN`. A `setTimeout` armed with `NaN`\n * fires immediately, which is exactly the failure a derived timeout must not\n * have. Importing from here keeps the real values under a mocked `api`.\n */\n\n/** Ceiling on `ComfyApi.waitForAuthInitialization`, spent before the response timer below is armed. */\nexport const AUTH_INIT_TIMEOUT_MS = 10_000\n\n/**\n * Response-HEADERS timeout for one `fetchApi` attempt — not the body. A 401\n * remint clears this timer and arms a fresh one for the retry, so a single\n * cloud request can spend it twice (`fetchWithUnifiedRemint`).\n */\nexport const FETCH_RESPONSE_HEADERS_TIMEOUT_MS = 60_000\n","import type { AccountUser } from './sessionContracts.js'\n\n/**\n * The identity boundary. An internal port, not a host adapter: real hosts\n * get their implementation from `@comfyorg/account-core/firebase`; tests brand a\n * fake through `@comfyorg/account-core/testing`. `createSessionClient` accepts\n * only the branded form.\n */\nexport interface IdentityPort<TUser extends AccountUser = AccountUser> {\n  onUserChanged: (callback: (user: TUser | null) => void) => () => void\n}\n\n/**\n * The brand is a compile-time gate only: `createSessionClient` rejects an\n * unbranded port in the type system, and no runtime check remains. The\n * package's own identity entries mint it, and `./testing` deliberately\n * re-exports the minter as `createTestIdentity` so a suite can brand a fake.\n */\nexport const identityBrand: unique symbol = Symbol(\n  '@comfyorg/account-core identity'\n)\n\nexport interface AccountIdentity<\n  TUser extends AccountUser = AccountUser\n> extends IdentityPort<TUser> {\n  readonly [identityBrand]: true\n}\n\nexport function brandIdentity<TUser extends AccountUser>(\n  port: IdentityPort<TUser>\n): AccountIdentity<TUser> {\n  return { ...port, [identityBrand]: true }\n}\n","/**\n * Classification of Firebase Auth failures, shared so both hosts branch on\n * the same buckets. Typed structurally rather than via `instanceof\n * FirebaseError` so this package needs no firebase dependency — a host passes\n * whatever it caught and unknown shapes land in 'unknown'.\n */\n\nexport interface FirebaseAuthErrorLike {\n  code: string\n  message: string\n}\n\n/**\n * The user or their browser dismissed/blocked the popup — an outcome to warn\n * about and retry on a fresh gesture, never an app fault.\n */\nconst POPUP_DISMISSED_CODES: readonly string[] = [\n  'auth/popup-closed-by-user',\n  'auth/cancelled-popup-request',\n  'auth/popup-blocked'\n]\n\n/**\n * The origin is not on the Firebase authorized-domains list (or a continue\n * URI is unauthorized): auth cannot work here at all until configuration\n * changes, so the host should say so rather than offer a retry.\n */\nconst UNAUTHORIZED_DOMAIN_CODES: readonly string[] = [\n  'auth/unauthorized-domain',\n  'auth/invalid-dynamic-link-domain',\n  'auth/unauthorized-continue-uri'\n]\n\nexport type AuthErrorClassification =\n  | { kind: 'unauthorized-domain'; code: string }\n  | { kind: 'signup-blocked'; code: string }\n  | { kind: 'popup-dismissed'; code: string }\n  | { kind: 'auth'; code: string }\n  | { kind: 'unknown' }\n\nexport function isFirebaseAuthErrorLike(\n  error: unknown\n): error is FirebaseAuthErrorLike {\n  return (\n    typeof error === 'object' &&\n    error !== null &&\n    'code' in error &&\n    typeof error.code === 'string' &&\n    error.code.startsWith('auth/') &&\n    'message' in error &&\n    typeof error.message === 'string'\n  )\n}\n\nexport function classifyAuthError(error: unknown): AuthErrorClassification {\n  if (!isFirebaseAuthErrorLike(error)) return { kind: 'unknown' }\n  if (UNAUTHORIZED_DOMAIN_CODES.includes(error.code)) {\n    return { kind: 'unauthorized-domain', code: error.code }\n  }\n  // Match on `error.message`, not `error.code`: Firebase `beforeUserCreated`\n  // rejections collapse the thrown code into a generic `auth/internal-error`,\n  // so the message is the only reliable channel. `signup_blocked` is a\n  // cross-repo contract token; matched case-insensitively.\n  if (error.message.toLowerCase().includes('signup_blocked')) {\n    return { kind: 'signup-blocked', code: error.code }\n  }\n  if (POPUP_DISMISSED_CODES.includes(error.code)) {\n    return { kind: 'popup-dismissed', code: error.code }\n  }\n  return { kind: 'auth', code: error.code }\n}\n\nexport type AuthToastSeverity = 'error' | 'warning'\n\n/**\n * The cloud app's toast-severity policy for classified auth failures: a\n * dismissed popup is the user changing their mind, not an application\n * error; everything else alarms.\n */\nexport function severityForAuthError(\n  classification: AuthErrorClassification\n): AuthToastSeverity {\n  return classification.kind === 'popup-dismissed' ? 'warning' : 'error'\n}\n\n/**\n * A host's auth error table: Firebase codes mapped to that host's copy, plus\n * the two fallbacks every table must carry. Hosts build this from their own\n * i18n; the package ships no strings of its own.\n */\nexport type AuthErrorCopy = Readonly<Record<string, string>> & {\n  readonly generic: string\n  readonly signupBlocked: string\n}\n\n/** Resolved to the invalid-credential line whatever table is in play. */\nconst ENUMERATION_NEUTRAL_CODES: ReadonlySet<string> = new Set([\n  'auth/user-not-found',\n  'auth/wrong-password'\n])\n\n/**\n * The detail copy for a classified failure, resolved against the host copy:\n * a code the table knows gets its own line, anything else the generic line, a\n * blocked sign-up its named copy. The user-not-found / wrong-password pair\n * collapses to the invalid-credential line so a sign-in attempt can never\n * reveal whether an email has an account. Unauthorized domains need the\n * host's domain and support address, which the host interpolates itself.\n */\nexport function authErrorMessage(\n  classification: AuthErrorClassification,\n  copy: AuthErrorCopy\n): string {\n  switch (classification.kind) {\n    case 'signup-blocked':\n      return copy.signupBlocked\n    case 'popup-dismissed':\n    case 'auth':\n      if (ENUMERATION_NEUTRAL_CODES.has(classification.code)) {\n        return copy['auth/invalid-credential'] ?? copy.generic\n      }\n      return copy[classification.code] ?? copy.generic\n    case 'unauthorized-domain':\n    case 'unknown':\n      return copy.generic\n  }\n}\n","/**\n * Tells, from facts rather than a timer, whether a popup sign-in was\n * abandoned. Firebase itself cannot: after the window closes it waits a\n * hardcoded 8s (on a 2s poll) before rejecting with `popup-closed-by-user`,\n * because a closed window alone does not say whether the sign-in result had\n * already been handed over.\n *\n * The result is handed over through the resolver's event manager, and\n * Firebase's hosted handler page waits for the page to acknowledge it before\n * closing the popup. So \"window closed and no result for this operation\" means\n * the visitor gave up, and \"result received\" means the sign-in is completing,\n * however long the token exchange then takes.\n *\n * This subclasses the SDK's public `browserPopupRedirectResolver` and reads two\n * of its internals: the event manager `_initialize` resolves to, and the\n * provider, event id and window `_openPopup` works with\n * (popupWatchSdkContract.test.ts pins them). When they are not what this\n * expects, nothing is watched and sign-in keeps Firebase's own timing.\n */\nimport type { PopupRedirectResolver } from 'firebase/auth'\nimport { browserPopupRedirectResolver } from 'firebase/auth'\n\nexport interface PopupWatchCallbacks {\n  /** The popup closed before any sign-in result reached the page: the visitor gave up. */\n  readonly onAbandoned?: () => void\n  /** A result arrived after `onAbandoned` and was kept: the sign-in completes after all. */\n  readonly onResumed?: () => void\n  /**\n   * Asked when a result arrives after `onAbandoned`. True discards it before\n   * Firebase exchanges it, so no account is signed in or created.\n   */\n  readonly discardLateResult?: () => boolean\n}\n\n/** Frequent enough to feel immediate; one `closed` read per tick. */\nconst CLOSED_POLL_MS = 100\n\ninterface AuthEventLike {\n  readonly type?: unknown\n  readonly eventId?: unknown\n  readonly error?: unknown\n}\n\ninterface AuthEventManagerLike {\n  onEvent: (event: AuthEventLike) => boolean\n}\n\ninterface ResolverInternals {\n  _initialize(auth: unknown): Promise<unknown>\n  _openPopup(\n    auth: unknown,\n    provider: unknown,\n    authType: unknown,\n    eventId?: string\n  ): Promise<unknown>\n}\n\ntype ResolverClass = new () => ResolverInternals\n\ninterface WatchedAttempt {\n  readonly callbacks: PopupWatchCallbacks\n  abandoned: boolean\n  eventId?: string\n  poll?: ReturnType<typeof setInterval>\n}\n\n// Keyed by the provider object each sign-in hands to `signInWithPopup`, which\n// Firebase passes on to `_openPopup`, so a popup Firebase still opens for an\n// operation it already cancelled is never taken for a newer one.\nconst attemptsByProvider = new WeakMap<object, WatchedAttempt>()\nconst attemptsByEventId = new Map<string, WatchedAttempt>()\nconst wrappedManagers = new WeakSet<object>()\n// Only an Auth whose event manager is wrapped has results this can see.\nconst observedAuths = new WeakSet<object>()\n\nfunction isObject(value: unknown): value is object {\n  return typeof value === 'object' && value !== null\n}\n\nfunction isResolverClass(value: unknown): value is ResolverClass {\n  if (typeof value !== 'function') return false\n  const prototype: unknown = value.prototype\n  return (\n    typeof prototype === 'object' &&\n    prototype !== null &&\n    '_initialize' in prototype &&\n    '_openPopup' in prototype\n  )\n}\n\nfunction isEventManager(value: unknown): value is AuthEventManagerLike {\n  return (\n    typeof value === 'object' &&\n    value !== null &&\n    'onEvent' in value &&\n    typeof value.onEvent === 'function'\n  )\n}\n\ninterface PopupWindowLike {\n  readonly closed: unknown\n}\n\nfunction popupWindowOf(popup: unknown): PopupWindowLike | undefined {\n  if (typeof popup !== 'object' || popup === null || !('window' in popup))\n    return undefined\n  const { window } = popup\n  return typeof window === 'object' && window !== null && 'closed' in window\n    ? window\n    : undefined\n}\n\nfunction stopPolling(attempt: WatchedAttempt): void {\n  clearInterval(attempt.poll)\n  attempt.poll = undefined\n}\n\nfunction deliver(\n  original: AuthEventManagerLike['onEvent'],\n  event: AuthEventLike\n): boolean {\n  const attempt =\n    event.type === 'signInViaPopup' && typeof event.eventId === 'string'\n      ? attemptsByEventId.get(event.eventId)\n      : undefined\n  if (!attempt) return original(event)\n  stopPolling(attempt)\n  // A late failure is Firebase's to report; the host already heard the close.\n  if (!attempt.abandoned || event.error) return original(event)\n  // Acknowledged so the handler page stops, never handed to Firebase.\n  if (shouldDiscard(attempt)) return true\n  attempt.abandoned = false\n  try {\n    attempt.callbacks.onResumed?.()\n  } catch {\n    // The result is kept either way; a host bug must not stall Firebase.\n  }\n  return original(event)\n}\n\nfunction shouldDiscard(attempt: WatchedAttempt): boolean {\n  try {\n    return attempt.callbacks.discardLateResult?.() ?? false\n  } catch {\n    return true\n  }\n}\n\n/** Ties the attempt to its latest popup, dropping any earlier one's watch. */\nfunction watchWindow(\n  attempt: WatchedAttempt,\n  eventId: string,\n  popup: PopupWindowLike\n): void {\n  stopPolling(attempt)\n  if (attempt.eventId) attemptsByEventId.delete(attempt.eventId)\n  attempt.eventId = eventId\n  attemptsByEventId.set(eventId, attempt)\n  attempt.poll = setInterval(() => {\n    if (popup.closed !== true) return\n    stopPolling(attempt)\n    attempt.abandoned = true\n    attempt.callbacks.onAbandoned?.()\n  }, CLOSED_POLL_MS)\n}\n\nfunction watchingResolver(Base: ResolverClass): ResolverClass {\n  return class WatchingPopupRedirectResolver extends Base {\n    override async _initialize(auth: unknown): Promise<unknown> {\n      const manager = await super._initialize(auth)\n      if (!isEventManager(manager)) return manager\n      if (!wrappedManagers.has(manager)) {\n        const original = manager.onEvent.bind(manager)\n        manager.onEvent = (event) => deliver(original, event)\n        wrappedManagers.add(manager)\n      }\n      if (isObject(auth)) observedAuths.add(auth)\n      return manager\n    }\n\n    override async _openPopup(\n      auth: unknown,\n      provider: unknown,\n      authType: unknown,\n      eventId?: string\n    ): Promise<unknown> {\n      const popup = await super._openPopup(auth, provider, authType, eventId)\n      const attempt = isObject(provider)\n        ? attemptsByProvider.get(provider)\n        : undefined\n      const popupWindow = popupWindowOf(popup)\n      // Without results to compare against, a closed window proves nothing.\n      const observed = isObject(auth) && observedAuths.has(auth)\n      if (attempt && observed && eventId && popupWindow)\n        watchWindow(attempt, eventId, popupWindow)\n      return popup\n    }\n  }\n}\n\n/**\n * The resolver a watched identity's Auth is created with. One for the whole\n * page, so Auth created again for the same app is handed the same resolver.\n * Firebase's own when its resolver cannot be extended.\n */\nexport const watchedPopupRedirectResolver: PopupRedirectResolver =\n  isResolverClass(browserPopupRedirectResolver)\n    ? watchingResolver(browserPopupRedirectResolver)\n    : browserPopupRedirectResolver\n\n/**\n * Runs one popup sign-in for `provider`, the object passed to\n * `signInWithPopup`, reporting through `callbacks` while it is pending.\n */\nexport async function runWatchedPopup<T>(\n  provider: object,\n  signIn: () => Promise<T>,\n  callbacks: PopupWatchCallbacks\n): Promise<T> {\n  const attempt: WatchedAttempt = { callbacks, abandoned: false }\n  attemptsByProvider.set(provider, attempt)\n  try {\n    return await signIn()\n  } finally {\n    stopPolling(attempt)\n    attemptsByProvider.delete(provider)\n    if (attempt.eventId) attemptsByEventId.delete(attempt.eventId)\n  }\n}\n","/**\n * The package-owned identity entry. Hosts either pass Firebase configuration\n * — including the persistence choice — for an app the package initializes,\n * or hand over the `Auth` they already hold, and get back the identity\n * surface the session core binds to plus the sign-in actions.\n *\n * Popup, never `signInWithRedirect`: the redirect flow is broken under\n * Safari's ITP for cross-origin helper domains, which is why the cloud app\n * is popup-only too. Provider scopes and the `select_account` prompt are the\n * cloud app's.\n *\n * This entry is the one place the package touches the Firebase SDK;\n * importGuard.test.ts holds `./core` to that boundary.\n */\nimport type { FirebaseApp, FirebaseOptions } from 'firebase/app'\nimport { FirebaseError, getApps, initializeApp } from 'firebase/app'\nimport type { Auth, Dependencies, User, UserCredential } from 'firebase/auth'\nimport {\n  GithubAuthProvider,\n  GoogleAuthProvider,\n  browserLocalPersistence,\n  browserPopupRedirectResolver,\n  browserSessionPersistence,\n  createUserWithEmailAndPassword,\n  getAuth,\n  indexedDBLocalPersistence,\n  initializeAuth,\n  onAuthStateChanged,\n  onIdTokenChanged,\n  sendPasswordResetEmail,\n  signInWithEmailAndPassword,\n  signInWithPopup,\n  signOut,\n  updatePassword\n} from 'firebase/auth'\n\nimport type { AccountIdentity } from '../core/identity.js'\nimport { brandIdentity } from '../core/identity.js'\nimport { isFirebaseAuthErrorLike } from '../firebaseAuthError.js'\nimport type { CloudFeatures } from './configSource.js'\nimport { fetchCloudFeatures } from './configSource.js'\nimport { runWatchedPopup, watchedPopupRedirectResolver } from './popupWatch.js'\n\nexport { watchedPopupRedirectResolver } from './popupWatch.js'\n\nexport interface FirebaseIdentityAppConfig {\n  readonly options: FirebaseOptions | (() => FirebaseOptions)\n  /** Named app: never contend with a default app another script creates. */\n  readonly appName?: string\n  /** One persistence or an ordered hierarchy, handed to `initializeAuth` as is; Firebase's default when omitted. */\n  readonly persistence?: Dependencies['persistence']\n  /**\n   * Report a closed popup at once instead of after Firebase's 8-10s wait (see\n   * `PopupSignInOptions`). Auth is then created with the dependencies `getAuth`\n   * would pick, plus `watchedPopupRedirectResolver`.\n   */\n  readonly watchPopupSignIn?: boolean\n  /** A host-owned `Auth` and package-owned app options are exclusive. */\n  readonly auth?: never\n}\n\n/**\n * A host that already holds an `Auth` binds the entry to it: no second app,\n * no second persistence store.\n */\nexport interface FirebaseIdentityAuthConfig {\n  readonly auth: Auth\n  /** Only when the host created `auth` with `watchedPopupRedirectResolver`. */\n  readonly watchPopupSignIn?: boolean\n  readonly options?: never\n  readonly appName?: never\n  readonly persistence?: never\n}\n\nexport type FirebaseIdentityConfig =\n  | FirebaseIdentityAppConfig\n  | FirebaseIdentityAuthConfig\n\n/**\n * On a watched identity a popup the visitor closes rejects at once with\n * `auth/popup-closed-by-user`, the same error Firebase raises 8-10s later, so\n * a host's usual handling applies. Rarely the sign-in result still arrives\n * after that; these decide whether it is finished or discarded unused.\n */\nexport interface PopupSignInOptions {\n  /**\n   * Finishes a result that arrived after the popup was reported closed, given\n   * the credential still being exchanged. Without it such a result is\n   * discarded. It is also discarded when another sign-in started since or\n   * someone else is now signed in.\n   */\n  readonly onResumed?: (credential: Promise<UserCredential>) => void\n  /** Asked before a late result is kept; false discards it. */\n  readonly keepLateResult?: () => boolean\n}\n\nexport interface FirebaseIdentity extends AccountIdentity<User> {\n  /**\n   * Fires with the restored user (or null) once Firebase settles, then on\n   * every change. This is the identity the session core binds to.\n   */\n  onUserChanged: (callback: (user: User | null) => void) => () => void\n  /** Fires on every ID token change, refreshes included. */\n  onTokenChanged: (callback: (user: User | null) => void) => () => void\n  /** Resolves the app and `Auth` now; a no-op once resolved. */\n  initialize: () => void\n  /** Null until `initialize()` or a subscribing/sign-in call has resolved `Auth`. */\n  currentUser: () => User | null\n  signInWithGoogle: (options?: PopupSignInOptions) => Promise<UserCredential>\n  signInWithGitHub: (options?: PopupSignInOptions) => Promise<UserCredential>\n  signInWithEmail: (email: string, password: string) => Promise<UserCredential>\n  createUserWithEmail: (\n    email: string,\n    password: string\n  ) => Promise<UserCredential>\n  sendPasswordReset: (email: string) => Promise<void>\n  /** For the signed-in user; rejects when nobody is signed in. */\n  updatePassword: (newPassword: string) => Promise<void>\n  signOut: () => Promise<void>\n}\n\nfunction googleProvider(): GoogleAuthProvider {\n  const provider = new GoogleAuthProvider()\n  provider.addScope('email')\n  provider.setCustomParameters({ prompt: 'select_account' })\n  return provider\n}\n\nfunction githubProvider(): GithubAuthProvider {\n  const provider = new GithubAuthProvider()\n  provider.addScope('user:email')\n  provider.setCustomParameters({ prompt: 'select_account' })\n  return provider\n}\n\n/**\n * An unknown email must look exactly like a sent reset, which is how Firebase\n * itself answers with email enumeration protection on; a distinct failure\n * here would be an account enumeration oracle.\n */\nfunction resolveUnknownEmailAsSent(error: unknown): void {\n  if (isFirebaseAuthErrorLike(error) && error.code === 'auth/user-not-found') {\n    return\n  }\n  throw error\n}\n\ninterface AuthResolver {\n  resolve: () => Auth\n  peek: () => Auth | undefined\n}\n\n/** What `getAuth` hands `initializeAuth` in a browser; read only when needed. */\nfunction getAuthPersistence(): Dependencies['persistence'] {\n  return [\n    indexedDBLocalPersistence,\n    browserLocalPersistence,\n    browserSessionPersistence\n  ]\n}\n\n/**\n * A pre-existing app under this name must be the same Firebase project, or\n * `Auth` binds to another project's session. Deliberately a \"same project\"\n * check on the fields that pick a session, not the SDK's byte-identical\n * compare: `appId` is Installations/Analytics, so omitting it from a partial\n * same-project config still binds rather than failing boot.\n */\nfunction assertSameProject(\n  existing: FirebaseOptions,\n  requested: FirebaseOptions,\n  appName: string\n): void {\n  const mismatch = (['projectId', 'apiKey', 'authDomain'] as const)\n    .filter((key) => existing[key] !== requested[key])\n    .join(', ')\n  if (mismatch) {\n    throw new Error(\n      `Firebase app \"${appName}\" already exists for a different project (${mismatch})`\n    )\n  }\n}\n\n/** What `initializeAuth` needs beyond `getAuth`'s defaults; none means `getAuth`. */\nfunction authDependencies(\n  persistence: Dependencies['persistence'],\n  watchPopupSignIn: boolean | undefined\n): Dependencies | undefined {\n  if (!persistence && !watchPopupSignIn) return undefined\n  return {\n    persistence: persistence ?? getAuthPersistence(),\n    popupRedirectResolver: watchPopupSignIn\n      ? watchedPopupRedirectResolver\n      : browserPopupRedirectResolver\n  }\n}\n\n/**\n * When only the popup watch asked for `initializeAuth`, an Auth that already\n * exists for the app is reused as `getAuth` would, unwatched, rather than\n * failing sign-in.\n */\nfunction initializeOrReuse(\n  app: FirebaseApp,\n  dependencies: Dependencies,\n  mayReuse: boolean\n): Auth {\n  try {\n    return initializeAuth(app, dependencies)\n  } catch (error) {\n    if (\n      mayReuse &&\n      isFirebaseAuthErrorLike(error) &&\n      error.code === 'auth/already-initialized'\n    ) {\n      return getAuth(app)\n    }\n    throw error\n  }\n}\n\n/**\n * Host persistence goes through `initializeAuth`, whether this entry creates\n * the named app or another script already did: Firebase allows one Auth per\n * app, so an Auth another module initialized with different dependencies\n * fails with `auth/already-initialized` instead of silently winning. Unlike\n * `getAuth`, `initializeAuth` wires no popup resolver of its own, and popup\n * sign-in throws `auth/argument-error` without one.\n */\nfunction authResolver(config: FirebaseIdentityConfig): AuthResolver {\n  if (config.auth) {\n    const { auth } = config\n    return { resolve: () => auth, peek: () => auth }\n  }\n  const appName = config.appName ?? 'comfy-account'\n  let resolved: Auth | undefined\n  const resolve = (): Auth => {\n    if (resolved) return resolved\n    // Resolve options before the lookup so the host's config thunk (its\n    // unloaded-remote-config guard) always runs, even when reusing an app.\n    const options =\n      typeof config.options === 'function' ? config.options() : config.options\n    const existing = getApps().find((app) => app.name === appName)\n    if (existing) assertSameProject(existing.options, options, appName)\n    const app = existing ?? initializeApp(options, appName)\n    const dependencies = authDependencies(\n      config.persistence,\n      config.watchPopupSignIn\n    )\n    resolved = dependencies\n      ? initializeOrReuse(app, dependencies, !config.persistence)\n      : getAuth(app)\n    return resolved\n  }\n  return { resolve, peek: () => resolved }\n}\n\nexport function createFirebaseIdentity(\n  config: FirebaseIdentityConfig\n): FirebaseIdentity {\n  const { resolve: auth, peek } = authResolver(config)\n  let signInsStarted = 0\n\n  function popupSignIn(\n    createProvider: () => GoogleAuthProvider | GithubAuthProvider,\n    options: PopupSignInOptions | undefined\n  ): Promise<UserCredential> {\n    const started = ++signInsStarted\n    const provider = createProvider()\n    const signIn = () => signInWithPopup(auth(), provider)\n    if (!config.watchPopupSignIn) return signIn()\n    // Read once the session has restored, so a restore landing after the\n    // popup opened is not taken for someone else signing in.\n    let userAtStart: string | null | undefined = null\n    // Never on the sign-in path: if the restore cannot be read, late results\n    // stay discarded.\n    void Promise.resolve()\n      .then(() => auth().authStateReady())\n      .then(() => {\n        userAtStart = auth().currentUser?.uid\n      })\n      .catch(() => {})\n    return new Promise((resolve, reject) => {\n      const firebaseCall = runWatchedPopup(provider, signIn, {\n        onAbandoned: () =>\n          reject(\n            new FirebaseError(\n              'auth/popup-closed-by-user',\n              'The popup has been closed by the user before finalizing the operation.'\n            )\n          ),\n        discardLateResult: () =>\n          !options?.onResumed ||\n          signInsStarted !== started ||\n          auth().currentUser?.uid !== userAtStart ||\n          options.keepLateResult?.() === false,\n        onResumed: () => options?.onResumed?.(firebaseCall)\n      })\n      firebaseCall.then(resolve, reject)\n    })\n  }\n\n  return {\n    ...brandIdentity<User>({\n      onUserChanged: (callback) => onAuthStateChanged(auth(), callback)\n    }),\n    onTokenChanged: (callback) => onIdTokenChanged(auth(), callback),\n    initialize: () => {\n      auth()\n    },\n    currentUser: () => peek()?.currentUser ?? null,\n    signInWithGoogle: (options) => popupSignIn(googleProvider, options),\n    signInWithGitHub: (options) => popupSignIn(githubProvider, options),\n    signInWithEmail: (email, password) => {\n      signInsStarted += 1\n      return signInWithEmailAndPassword(auth(), email, password)\n    },\n    createUserWithEmail: (email, password) => {\n      signInsStarted += 1\n      return createUserWithEmailAndPassword(auth(), email, password)\n    },\n    sendPasswordReset: (email) =>\n      sendPasswordResetEmail(auth(), email).catch(resolveUnknownEmailAsSent),\n    updatePassword: (newPassword) => {\n      const user = auth().currentUser\n      return user\n        ? updatePassword(user, newPassword)\n        : Promise.reject(\n            new Error('No signed-in user to update the password for')\n          )\n    },\n    signOut: () => signOut(auth())\n  }\n}\n\nexport interface ResolveFirebaseIdentityOptions {\n  /** The Cloud origin whose `/api/features` names this app's Firebase project. */\n  readonly cloudBaseUrl: string\n  /** Named app: never contend with a default app another script creates. */\n  readonly appName: string\n  readonly persistence?: Dependencies['persistence']\n  readonly timeoutMs?: number\n}\n\n/**\n * One `/api/features` fetch per `cloudBaseUrl`/`timeoutMs` pair, shared by\n * every reader of the document: `resolveFirebaseIdentity` and\n * `resolveStripePublishableKey` on the same pair read the same fetch instead\n * of each starting their own. Never rejects, a failed fetch settles `{}`,\n * which each field reader treats as absent.\n *\n * Memoized while a fetch is in flight or has produced a document with either\n * field present. A document with neither field is treated the same as a\n * failed fetch and evicts, matching `identityResolutions` below: this cache\n * cannot tell a transient failure (network error, timeout, malformed body)\n * from a Cloud origin that genuinely has neither Firebase nor Stripe\n * configured, and caching that ambiguity would silently defeat\n * `identityResolutions`'s own eviction once a caller retries through it.\n */\nconst featureResolutions = new Map<string, Promise<CloudFeatures>>()\n\nfunction resolveCloudFeatures(\n  cloudBaseUrl: string,\n  timeoutMs: number | undefined\n): Promise<CloudFeatures> {\n  const key = `${cloudBaseUrl} ${timeoutMs ?? ''}`\n  let resolution = featureResolutions.get(key)\n  if (!resolution) {\n    resolution = fetchCloudFeatures(cloudBaseUrl, { timeoutMs })\n    // Evict on an unsuccessful settle so a transient failure does not wedge\n    // every reader of this pair for the module's lifetime. Callers already\n    // hold this promise directly, not a map lookup, so deleting it here\n    // never orphans one.\n    void resolution.then((features) => {\n      if (\n        !features.firebaseConfig &&\n        !features.stripePublishableKey &&\n        featureResolutions.get(key) === resolution\n      ) {\n        featureResolutions.delete(key)\n      }\n    })\n    featureResolutions.set(key, resolution)\n  }\n  return resolution\n}\n\n/**\n * The single entry a host needs to go from a Cloud origin to a ready\n * identity: fetch `/api/features`, construct the app, and force `Auth` to\n * resolve now rather than on whichever caller first touches the identity, so\n * a config that fails the SDK's own checks (a bad key, a project mismatch on\n * `appName`) surfaces here instead of downstream. Settles `undefined` on any\n * failure along the way and never rejects, so a caller always gets either a\n * ready identity or a definite absence.\n *\n * Memoized per `appName`/`cloudBaseUrl` pair while a fetch is in flight or\n * has produced a ready identity, so every caller with the same pair shares\n * one fetch and one identity, and two pairs (two hosts, or two Cloud origins\n * in one process, as this package's own tests run) never share a result. An\n * unsuccessful settle evicts its entry, so a later call re-fetches rather\n * than replaying the same absence for the module's lifetime.\n */\nconst identityResolutions = new Map<\n  string,\n  Promise<FirebaseIdentity | undefined>\n>()\n\nexport function resolveFirebaseIdentity(\n  options: ResolveFirebaseIdentityOptions\n): Promise<FirebaseIdentity | undefined> {\n  const { cloudBaseUrl, appName, persistence, timeoutMs } = options\n  const key = `${appName} ${cloudBaseUrl}`\n  let resolution = identityResolutions.get(key)\n  if (!resolution) {\n    resolution = resolveCloudFeatures(cloudBaseUrl, timeoutMs).then(\n      ({ firebaseConfig }) => {\n        if (!firebaseConfig) return undefined\n        try {\n          const identity = createFirebaseIdentity({\n            options: firebaseConfig,\n            appName,\n            persistence\n          })\n          identity.initialize()\n          return identity\n        } catch {\n          return undefined\n        }\n      }\n    )\n    // Evict on an unsuccessful settle so a transient failure does not wedge\n    // sign-in for the module's lifetime. Callers already hold this promise\n    // directly, not a map lookup, so deleting it here never orphans one.\n    void resolution.then((identity) => {\n      if (!identity && identityResolutions.get(key) === resolution) {\n        identityResolutions.delete(key)\n      }\n    })\n    identityResolutions.set(key, resolution)\n  }\n  return resolution\n}\n\nexport interface ResolveStripePublishableKeyOptions {\n  /** The Cloud origin whose `/api/features` names this app's Stripe key. */\n  readonly cloudBaseUrl: string\n  readonly timeoutMs?: number\n}\n\n/**\n * The Stripe publishable key from the same `/api/features` document\n * `resolveFirebaseIdentity` reads. A host that calls both with the same\n * `cloudBaseUrl`/`timeoutMs` pays for one fetch, not two, `resolveCloudFeatures`\n * dedupes by that pair regardless of which field a caller asked for first.\n * Settles `undefined` on any failure and never rejects.\n */\nexport function resolveStripePublishableKey(\n  options: ResolveStripePublishableKeyOptions\n): Promise<string | undefined> {\n  return resolveCloudFeatures(options.cloudBaseUrl, options.timeoutMs).then(\n    ({ stripePublishableKey }) => stripePublishableKey\n  )\n}\n\nexport type CloudTelemetryConfig = Pick<\n  CloudFeatures,\n  'posthogProjectToken' | 'posthogApiHost' | 'telemetryDisabledEvents'\n>\n\n/** The Cloud app's PostHog settings from the same shared `/api/features` document. */\nexport function resolveCloudTelemetryConfig(\n  options: Pick<ResolveFirebaseIdentityOptions, 'cloudBaseUrl' | 'timeoutMs'>\n): Promise<CloudTelemetryConfig> {\n  return resolveCloudFeatures(options.cloudBaseUrl, options.timeoutMs).then(\n    ({ posthogProjectToken, posthogApiHost, telemetryDisabledEvents }) => ({\n      posthogProjectToken,\n      posthogApiHost,\n      telemetryDisabledEvents\n    })\n  )\n}\n\n/**\n * `web_session_probe` from the same shared `/api/features` document, so a\n * host that already reads it for Firebase or Stripe pays no extra request.\n */\nexport function resolveWebSessionProbe(\n  options: Pick<ResolveFirebaseIdentityOptions, 'cloudBaseUrl' | 'timeoutMs'>\n): Promise<boolean> {\n  return resolveCloudFeatures(options.cloudBaseUrl, options.timeoutMs).then(\n    ({ webSessionProbe }) => webSessionProbe === true\n  )\n}\n\n/**\n * `sso_enabled` from the same shared `/api/features` document, so a host that\n * already reads it for Firebase pays no extra request.\n */\nexport function resolveSsoEnabled(\n  options: Pick<ResolveFirebaseIdentityOptions, 'cloudBaseUrl' | 'timeoutMs'>\n): Promise<boolean> {\n  return resolveCloudFeatures(options.cloudBaseUrl, options.timeoutMs).then(\n    ({ ssoEnabled }) => ssoEnabled === true\n  )\n}\n","import type { FirebaseOptions } from 'firebase/app'\n\nimport { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\n\nconst DEV_CONFIG: FirebaseOptions = {\n  apiKey: 'AIzaSyDa_YMeyzV0SkVe92vBZ1tVikWBmOU5KVE',\n  authDomain: 'dreamboothy-dev.firebaseapp.com',\n  databaseURL: 'https://dreamboothy-dev-default-rtdb.firebaseio.com',\n  projectId: 'dreamboothy-dev',\n  storageBucket: 'dreamboothy-dev.appspot.com',\n  messagingSenderId: '313257147182',\n  appId: '1:313257147182:web:be38f6ebf74345fc7618bf',\n  measurementId: 'G-YEVSMYXSPY'\n}\n\nconst PROD_CONFIG: FirebaseOptions = {\n  apiKey: 'AIzaSyC2-fomLqgCjb7ELwta1I9cEarPK8ziTGs',\n  authDomain: 'dreamboothy.firebaseapp.com',\n  databaseURL: 'https://dreamboothy-default-rtdb.firebaseio.com',\n  projectId: 'dreamboothy',\n  storageBucket: 'dreamboothy.appspot.com',\n  messagingSenderId: '357148958219',\n  appId: '1:357148958219:web:f5917f72e5f36a2015310e',\n  measurementId: 'G-3ZBD3MBTG4'\n}\n\nconst BUILD_TIME_CONFIG = __USE_PROD_CONFIG__ ? PROD_CONFIG : DEV_CONFIG\n\n/**\n * Firebase config for the current backend: the server's firebase_config (cloud builds),\n * else the bundled DEV_CONFIG when the server reports a dev-tier backend, else the build-time default.\n */\nexport function getFirebaseConfig(): FirebaseOptions {\n  const runtimeConfig = remoteConfig.value.firebase_config\n  if (runtimeConfig) return runtimeConfig\n  if (remoteConfig.value.firebase_env === 'dev') return DEV_CONFIG\n  return BUILD_TIME_CONFIG\n}\n","import {\n  browserLocalPersistence,\n  browserSessionPersistence,\n  indexedDBLocalPersistence\n} from 'firebase/auth'\n\nimport { createFirebaseIdentity } from '@comfyorg/account-core/firebase'\n\nimport { getFirebaseConfig } from '@/config/firebase'\nimport { remoteConfigState } from '@/platform/remoteConfig/remoteConfig'\n\nclass FirebaseBeforeRemoteConfigError extends Error {\n  constructor() {\n    super(\n      'Firebase resolved before remote config loaded: initialize() belongs after the startup/remote-config phase'\n    )\n    this.name = 'FirebaseBeforeRemoteConfigError'\n  }\n}\n\nfunction loadedFirebaseConfig() {\n  if (remoteConfigState.value === 'unloaded') {\n    throw new FirebaseBeforeRemoteConfigError()\n  }\n  return getFirebaseConfig()\n}\n\n/**\n * `[DEFAULT]` keeps the session key persisted sign-ins and the e2e seed are\n * stored under. Firebase reads an existing user from every listed persistence\n * in order and migrates it into the first available one, so a session that\n * vuefire's IndexedDB default persisted (the e2e seed too) is restored and\n * settles in localStorage, where `setPersistence(auth, browserLocalPersistence)`\n * used to move it.\n */\nexport const firebaseIdentity = createFirebaseIdentity({\n  options: loadedFirebaseConfig,\n  appName: '[DEFAULT]',\n  persistence: [\n    browserLocalPersistence,\n    indexedDBLocalPersistence,\n    browserSessionPersistence\n  ],\n  watchPopupSignIn: true\n})\n","import { shallowRef } from 'vue'\n\nimport type { WebSessionUser } from '@comfyorg/account-core/webSession'\n\nexport const webSessionUser = shallowRef<WebSessionUser>()\n","import { firebaseIdentity } from '@/platform/auth/firebaseIdentity'\nimport { webSessionUser } from '@/platform/auth/session/webSessionUser'\nimport { isCloud } from '@/platform/distribution/types'\n\nconst STORAGE_KEY = 'Comfy.FeatureFlagOverride'\nconst QUERY_PARAM = 'ff'\nconst EMPLOYEE_EMAIL_DOMAIN = '@comfy.org'\n\ntype OverrideMap = Record<string, unknown>\n\n/**\n * Overrides apply only to a signed-in Comfy employee, so a link handed to a\n * customer stays inert on their machine. With every flag overridable, this is\n * the only thing standing between a `?ff=` link and the app's behaviour, so it\n * fails closed.\n *\n * Reads the identity modules rather than `authStore`, which imports\n * `useFeatureFlags` and would drag the whole app module graph into every\n * feature flag read. A web session sign-in has no Firebase user, so its\n * server-verified user counts too.\n */\nfunction isComfyEmployee(): boolean {\n  return [firebaseUser(), webSessionUser.value].some(\n    (user) =>\n      user?.emailVerified === true &&\n      (user.email?.toLowerCase().endsWith(EMPLOYEE_EMAIL_DOMAIN) ?? false)\n  )\n}\n\nfunction firebaseUser() {\n  try {\n    return firebaseIdentity.currentUser()\n  } catch {\n    return null\n  }\n}\n\n/**\n * Reads the value with the same JSON semantics as the `ff:` localStorage\n * override, so `:false` is the boolean and `:12` the number rather than a\n * truthy string. Anything JSON rejects is taken as a plain string, which is\n * what makes `:enforce` work; quote it (`:\"12\"`) to force a numeric-looking\n * value to stay a string. A bare `?ff=name` means \"turn this on\".\n */\nfunction parseOverrideValue(rawValue: string | undefined): unknown {\n  if (rawValue === undefined) return true\n\n  try {\n    return JSON.parse(rawValue)\n  } catch {\n    return rawValue\n  }\n}\n\n/**\n * The captured overrides plus the query string they came from. Remembering the\n * source makes capture idempotent: re-reading the same URL does not rewrite\n * storage, so a flag can be read as often as a render needs.\n */\ntype StoredState = { search: string; overrides: OverrideMap }\n\nfunction emptyState(): StoredState {\n  return { search: '', overrides: {} }\n}\n\nfunction coerceStoredOverrides(value: unknown): OverrideMap {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) {\n    return {}\n  }\n  return { ...value }\n}\n\nfunction readStoredState(): StoredState {\n  let raw: string | null\n  try {\n    raw = sessionStorage.getItem(STORAGE_KEY)\n  } catch {\n    return emptyState()\n  }\n  if (!raw) return emptyState()\n\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(raw)\n  } catch {\n    return emptyState()\n  }\n  if (typeof parsed !== 'object' || parsed === null) return emptyState()\n\n  const search = 'search' in parsed ? parsed.search : undefined\n  const overrides = 'overrides' in parsed ? parsed.overrides : undefined\n  return {\n    search: typeof search === 'string' ? search : '',\n    overrides: coerceStoredOverrides(overrides)\n  }\n}\n\nfunction writeStoredState(state: StoredState): void {\n  try {\n    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(state))\n  } catch {\n    console.warn('[ff] Failed to persist session feature flag overrides')\n  }\n}\n\nfunction splitRequest(request: string): [name: string, value?: string] {\n  const separator = request.indexOf(':')\n  if (separator === -1) return [request]\n  return [request.slice(0, separator), request.slice(separator + 1)]\n}\n\nfunction readOverrideRequests(search: string): string[] {\n  return new URLSearchParams(search).getAll(QUERY_PARAM)\n}\n\n/**\n * Merges `?ff=` requests from the current URL into the overrides already held\n * for this tab. An `?ff=` with no name clears every override in the session.\n */\nfunction captureRequests(\n  requests: string[],\n  stored: OverrideMap,\n  search: string\n): OverrideMap {\n  if (requests.includes('')) {\n    writeStoredState({ search, overrides: {} })\n    return {}\n  }\n\n  const overrides: OverrideMap = { ...stored }\n  for (const request of requests) {\n    const [name, rawValue] = splitRequest(request)\n    overrides[name] = parseOverrideValue(rawValue)\n  }\n\n  writeStoredState({ search, overrides })\n  return overrides\n}\n\nfunction loadSessionOverrides(): OverrideMap {\n  const stored = readStoredState()\n  const search = window.location.search\n  if (search === stored.search) return stored.overrides\n\n  const requests = readOverrideRequests(search)\n  if (requests.length === 0) return stored.overrides\n\n  return captureRequests(requests, stored.overrides, search)\n}\n\n/**\n * Gets a session override for any feature flag, requested via `?ff=name` to\n * turn it on or `?ff=name:value` for a specific value, repeatable to override\n * several flags at once. A nameless `?ff=` clears the session.\n *\n * The request is captured into `sessionStorage` on the first read, so it\n * survives reloads and in-app navigation but dies when the tab closes. Capture\n * happens before authentication resolves; the employee check is re-evaluated\n * on every read instead, against the SDK's current user. That read carries no\n * reactive dependency of its own, so a flag flips on the next read after the\n * user is known, not the moment it is.\n *\n * Returns undefined (not null) as the \"no override\" sentinel, matching\n * `getDevOverride`.\n */\nexport function getSessionOverride<T>(\n  flagKey: string & { readonly valueType?: T }\n): T | undefined {\n  if (!isCloud) return undefined\n\n  const overrides = loadSessionOverrides()\n  if (!Object.hasOwn(overrides, flagKey)) return undefined\n  if (!isComfyEmployee()) return undefined\n\n  return overrides[flagKey] as T\n}\n","import type { Bounds } from '@/renderer/core/layout/types'\nimport type { CompositorWidgetValue } from '@/renderer/extensions/compositor/components/types'\nimport type { CurveData } from '@/components/curve/types'\nimport type { BoundingBox } from '@/types/boundingBoxes'\nimport type { LightInfoEntry } from '@/types/lightInfo'\nimport type { NodeId } from '@/types/nodeId'\nimport type { WidgetValue } from '@/types/simplifiedWidget'\nimport type { WidgetId } from '@/types/widgetId'\nimport type {\n  WidgetSurfaces,\n  WidgetVisibilityComponent\n} from '@/types/widgetVisibility'\nimport type { ColorFormat } from '@/utils/colorUtil'\n\nimport type {\n  CanvasColour,\n  ColorStop,\n  Point,\n  RequiredProps,\n  Size\n} from '../interfaces'\nimport type { CanvasPointer, LGraphCanvas, LGraphNode } from '../litegraph'\nimport type { CanvasPointerEvent } from './events'\n\nexport interface NodeBindable {\n  setNodeId(nodeId: NodeId): void\n}\n\nexport interface IWidgetOptions<TValues = unknown> {\n  on?: string\n  off?: string\n  max?: number\n  min?: number\n  slider_color?: CanvasColour\n  marker_color?: CanvasColour\n  precision?: number\n  read_only?: boolean\n  /**\n   * @deprecated Use {@link IWidgetOptions.step2} instead.\n   * The legacy step is scaled up by 10x in the legacy frontend logic.\n   */\n  step?: number\n  /** The step value for numeric widgets. */\n  step2?: number\n\n  y?: number\n  multiline?: boolean\n  // TODO: Confirm this\n  property?: string\n  /** If `true`, an input socket will not be created for this widget. */\n  socketless?: boolean\n  surfaces?: WidgetSurfaces\n  /** @deprecated This key stays supported for third-party widgets. */\n  canvasOnly?: boolean\n  /**\n   * If `true`, the widget still renders on the node but is omitted from the\n   * right side panel. Unlike {@link IWidgetOptions.canvasOnly}, the node body\n   * keeps rendering it via the Vue renderer. Used for widgets that hold\n   * non-syncable state (e.g. a Three.js viewport) where a second instance in\n   * the panel would diverge from the one on the node.\n   */\n  hideInPanel?: boolean\n  /** Used as a temporary override for determining the asset type in vue mode*/\n  nodeType?: string\n\n  /**\n   * Whether the widget value should be included in the API prompt sent to\n   * the backend for execution. Checked by {@link executionUtil} when\n   * building the prompt payload.\n   *\n   * This is distinct from {@link IBaseWidget.serialize}, which controls\n   * whether the value is persisted in the workflow JSON file.\n   *\n   * @default true\n   * @see IBaseWidget.serialize — workflow persistence\n   */\n  serialize?: boolean\n\n  values?: TValues\n  /** Optional function to format values for display (e.g., hash → human-readable name) */\n  getOptionLabel?: (value?: string | null) => string\n  callback?: IWidget['callback']\n  iconClass?: string\n\n  // Vue widget options\n  disabled?: boolean\n  useGrouping?: boolean\n  placeholder?: string\n  hidden?: boolean\n}\n\ninterface IWidgetSliderOptions extends IWidgetOptions<number[]> {\n  min: number\n  max: number\n  step2: number\n  slider_color?: CanvasColour\n  marker_color?: CanvasColour\n}\n\nexport interface IWidgetGradientSliderOptions extends IWidgetOptions<number[]> {\n  min: number\n  max: number\n  step2: number\n  gradient_stops?: ColorStop[]\n}\n\ninterface IWidgetKnobOptions extends IWidgetOptions<number[]> {\n  min: number\n  max: number\n  step2: number\n  slider_color?: CanvasColour // TODO: Replace with knob color\n  marker_color?: CanvasColour\n  gradient_stops?: string\n}\n\nexport interface IWidgetAssetOptions extends IWidgetOptions {\n  openModal: (widget: IBaseWidget) => void\n}\n\n/**\n * A widget for a node.\n * All types are based on IBaseWidget - additions can be made there or directly on individual types.\n *\n * Implemented as a discriminative union of widget types, so this type itself cannot be extended.\n * Recommend declaration merging any properties that use IWidget (e.g. {@link LGraphNode.widgets}) with a new type alias.\n * @see ICustomWidget\n */\nexport type IWidget =\n  | IBooleanWidget\n  | INumericWidget\n  | IStringWidget\n  | IComboWidget\n  | IStringComboWidget\n  | ICustomWidget\n  | ISliderWidget\n  | IGradientSliderWidget\n  | IButtonWidget\n  | IKnobWidget\n  | IFileUploadWidget\n  | IColorWidget\n  | IMarkdownWidget\n  | IImageWidget\n  | ITreeSelectWidget\n  | IMultiSelectWidget\n  | IChartWidget\n  | IGalleriaWidget\n  | IImageCompareWidget\n  | ISelectButtonWidget\n  | ITextareaWidget\n  | IAssetWidget\n  | IImageCropWidget\n  | IBoundingBoxWidget\n  | ICurveWidget\n  | IPainterWidget\n  | ICompositorWidget\n  | IRangeWidget\n  | IVideoEditWidget\n  | IResolutionPreviewWidget\n  | IBoundingBoxesWidget\n  | ILightInfoWidget\n  | IColorsWidget\n\nexport interface IBooleanWidget extends IBaseWidget<boolean, 'toggle'> {\n  type: 'toggle'\n  value: boolean\n}\n\n/** Any widget that uses a numeric backing */\nexport interface INumericWidget extends IBaseWidget<number, 'number'> {\n  type: 'number'\n  value: number\n}\n\nexport interface ISliderWidget extends IBaseWidget<\n  number,\n  'slider',\n  IWidgetSliderOptions\n> {\n  type: 'slider'\n  value: number\n  marker?: number\n}\n\nexport interface IGradientSliderWidget extends IBaseWidget<\n  number,\n  'gradientslider',\n  IWidgetGradientSliderOptions\n> {\n  type: 'gradientslider'\n  value: number\n}\n\nexport interface IKnobWidget extends IBaseWidget<\n  number,\n  'knob',\n  IWidgetKnobOptions\n> {\n  type: 'knob'\n  value: number\n  options: IWidgetKnobOptions\n}\n\n/** Avoids the type issues with the legacy IComboWidget type */\nexport interface IStringComboWidget extends IBaseWidget<\n  string,\n  'combo',\n  RequiredProps<IWidgetOptions<string[]>, 'values'>\n> {\n  type: 'combo'\n  value: string\n}\n\nexport type ComboWidgetValues =\n  | (string | number)[]\n  | Record<string, string>\n  | ((widget?: IComboWidget, node?: LGraphNode) => (string | number)[])\n\n/** A combo-box widget (dropdown, select, etc) */\nexport interface IComboWidget extends IBaseWidget<\n  string | number,\n  'combo',\n  RequiredProps<IWidgetOptions<ComboWidgetValues>, 'values'>\n> {\n  type: 'combo'\n  value: string | number\n}\n\n/** A widget with a string value */\nexport interface IStringWidget extends IBaseWidget<\n  string,\n  'string' | 'text',\n  IWidgetOptions<string[]>\n> {\n  type: 'string' | 'text'\n  value: string\n}\n\nexport interface IButtonWidget extends IBaseWidget<\n  string | undefined,\n  'button'\n> {\n  type: 'button'\n  value: string | undefined\n  clicked: boolean\n}\n\n/** A custom widget - accepts any value and has no built-in special handling */\ninterface ICustomWidget extends IBaseWidget<string | object, 'custom'> {\n  type: 'custom'\n  value: string | object\n}\n\n/** File upload widget for selecting and uploading files */\nexport interface IFileUploadWidget extends IBaseWidget<string, 'fileupload'> {\n  type: 'fileupload'\n  value: string\n  label?: string\n}\n\n/** Color picker widget for selecting colors */\nexport interface IColorWidgetOptions extends IWidgetOptions {\n  format?: ColorFormat | 'int'\n}\n\nexport interface IColorWidget extends IBaseWidget<\n  string | number,\n  'color',\n  IColorWidgetOptions\n> {\n  type: 'color'\n  value: string | number\n}\n\n/** Markdown widget for displaying formatted text */\nexport interface IMarkdownWidget extends IBaseWidget<string, 'markdown'> {\n  type: 'markdown'\n  value: string\n}\n\n/** Image display widget */\ninterface IImageWidget extends IBaseWidget<string, 'image'> {\n  type: 'image'\n  value: string\n}\n\n/** Tree select widget for hierarchical selection */\nexport interface ITreeSelectWidget extends IBaseWidget<\n  string | string[],\n  'treeselect'\n> {\n  type: 'treeselect'\n  value: string | string[]\n}\n\n/** Multi-select widget for selecting multiple options */\nexport interface IMultiSelectWidget extends IBaseWidget<\n  string[],\n  'multiselect'\n> {\n  type: 'multiselect'\n  value: string[]\n}\n\n/** Chart widget for displaying data visualizations */\nexport interface IChartWidget extends IBaseWidget<object, 'chart'> {\n  type: 'chart'\n  value: object\n}\n\n/** Gallery widget for displaying multiple images */\nexport interface IGalleriaWidget extends IBaseWidget<string[], 'galleria'> {\n  type: 'galleria'\n  value: string[]\n}\n\n/** Image comparison widget for comparing two images side by side */\nexport interface IImageCompareWidget extends IBaseWidget<\n  string[],\n  'imagecompare'\n> {\n  type: 'imagecompare'\n  value: string[]\n}\n\n/** Select button widget for selecting from a group of buttons */\nexport interface ISelectButtonWidget extends IBaseWidget<\n  string,\n  'selectbutton',\n  RequiredProps<IWidgetOptions<string[]>, 'values'>\n> {\n  type: 'selectbutton'\n  value: string\n}\n\n/** Textarea widget for multi-line text input */\nexport interface ITextareaWidget extends IBaseWidget<string, 'textarea'> {\n  type: 'textarea'\n  value: string\n}\n\nexport interface IAssetWidget extends IBaseWidget<\n  string,\n  'asset',\n  IWidgetAssetOptions\n> {\n  type: 'asset'\n  value: string\n}\n\n/** Image crop widget for cropping image */\nexport interface IImageCropWidget extends IBaseWidget<Bounds, 'imagecrop'> {\n  type: 'imagecrop'\n  value: Bounds\n}\n\n/** Bounding box widget for defining regions with numeric inputs */\nexport interface IBoundingBoxWidget extends IBaseWidget<Bounds, 'boundingbox'> {\n  type: 'boundingbox'\n  value: Bounds\n}\n\nexport interface ICurveWidget extends IBaseWidget<CurveData, 'curve'> {\n  type: 'curve'\n  value: CurveData\n}\n\nexport interface IPainterWidget extends IBaseWidget<string, 'painter'> {\n  type: 'painter'\n  value: string\n}\n\nexport interface ICompositorWidget extends IBaseWidget<\n  CompositorWidgetValue,\n  'compositor'\n> {\n  type: 'compositor'\n  value: CompositorWidgetValue\n}\n\nexport interface IBoundingBoxesWidget extends IBaseWidget<\n  BoundingBox[],\n  'boundingboxes'\n> {\n  type: 'boundingboxes'\n  value: BoundingBox[]\n}\n\nexport interface ILightInfoWidget extends IBaseWidget<\n  LightInfoEntry[],\n  'lightinfo'\n> {\n  type: 'lightinfo'\n  value: LightInfoEntry[]\n}\n\nexport interface IColorsWidget extends IBaseWidget<string[], 'colors'> {\n  type: 'colors'\n  value: string[]\n}\n\nexport interface RangeValue {\n  min: number\n  max: number\n  midpoint?: number\n}\n\nexport interface IWidgetRangeOptions extends IWidgetOptions {\n  display?: 'plain' | 'gradient' | 'histogram'\n  gradient_stops?: ColorStop[]\n  show_midpoint?: boolean\n  midpoint_scale?: 'linear' | 'gamma'\n  value_min?: number\n  value_max?: number\n}\n\nexport interface IRangeWidget extends IBaseWidget<\n  RangeValue,\n  'range',\n  IWidgetRangeOptions\n> {\n  type: 'range'\n  value: RangeValue\n}\n\nexport interface VideoEditTrim {\n  start_time: number\n  duration: number\n}\n\nexport interface VideoEditValue {\n  trim?: VideoEditTrim\n  crop?: Bounds\n}\n\nexport type VideoEditFeature = 'trim' | 'crop'\n\nexport interface IWidgetVideoEditOptions extends IWidgetOptions {\n  features?: VideoEditFeature[]\n}\n\nexport interface IVideoEditWidget extends IBaseWidget<\n  VideoEditValue,\n  'videoedit',\n  IWidgetVideoEditOptions\n> {\n  type: 'videoedit'\n  value: VideoEditValue\n}\n\nexport interface IWidgetResolutionPreviewOptions extends IWidgetOptions {\n  ratio_widget?: string\n  megapixels_widget?: string\n  multiple_widget?: string\n}\n\nexport interface IResolutionPreviewWidget extends IBaseWidget<\n  null,\n  'resolutionpreview',\n  IWidgetResolutionPreviewOptions\n> {\n  type: 'resolutionpreview'\n  value: null\n}\n\n/**\n * Valid widget types.  TS cannot provide easily extensible type safety for this at present.\n * Override linkedWidgets[]\n * Values not in this list will not result in litegraph errors, however they will be treated the same as \"custom\".\n */\nexport type TWidgetType = IWidget['type']\nexport type TWidgetValue = WidgetValue\n\nexport function isWidgetValue(value: unknown): value is TWidgetValue {\n  if (value == null) return true\n  if (typeof value === 'string') return true\n  if (typeof value === 'number') return true\n  if (typeof value === 'boolean') return true\n  return typeof value === 'object'\n}\n\n/**\n * The base type for all widgets.  Should not be implemented directly.\n * @template TValue The type of value this widget holds.\n * @template TType A string designating the type of widget, e.g. \"toggle\" or \"string\".\n * @template TOptions The options for this widget.\n * @see IWidget\n */\nexport interface IBaseWidget<\n  TValue = WidgetValue,\n  TType extends string = string,\n  TOptions extends IWidgetOptions = IWidgetOptions\n> {\n  [symbol: symbol]: boolean\n\n  linkedWidgets?: IBaseWidget[]\n\n  readonly widgetId?: WidgetId\n\n  name: string\n  options: TOptions\n  syncLiveVisibilityOptions?(): void\n  syncLiveDisabled?(): void\n\n  label?: string\n  /** Widget type (see {@link TWidgetType}) */\n  type: TType\n  value?: TValue\n\n  /**\n   * Whether the widget value is persisted in the workflow JSON\n   * (`widgets_values`). Checked by {@link LGraphNode.serialize} and\n   * {@link LGraphNode.configure}.\n   *\n   * This is distinct from {@link IWidgetOptions.serialize}, which controls\n   * whether the value is included in the API prompt sent for execution.\n   *\n   * @default true\n   * @see IWidgetOptions.serialize — API prompt inclusion\n   */\n  serialize?: boolean\n\n  /**\n   * The computed height of the widget. Used by customized node resize logic.\n   * See scripts/domWidget.ts for more details.\n   * @readonly [Computed] This property is computed by the node.\n   */\n  computedHeight?: number\n\n  /**\n   * The starting y position of the widget after layout.\n   * @readonly [Computed] This property is computed by the node.\n   */\n  y: number\n\n  /**\n   * The y position of the widget after drawing (rendering).\n   * @readonly [Computed] This property is computed by the node.\n   * @deprecated There is no longer dynamic y adjustment on rendering anymore.\n   * Use {@link IBaseWidget.y} instead.\n   */\n  last_y?: number\n\n  width?: number\n  /**\n   * Whether the widget is disabled. Disabled widgets are rendered at half opacity.\n   * See also {@link IBaseWidget.computedDisabled}.\n   */\n  disabled?: boolean\n\n  /**\n   * The disabled state used for rendering based on various conditions including\n   * {@link IBaseWidget.disabled}.\n   * @readonly [Computed] This property is computed by the node.\n   */\n  computedDisabled?: boolean\n\n  /**\n   * Whether the widget's input is satisfied by an upstream link, suppressing\n   * the widget on every rendering surface (the slot still renders).\n   * @readonly [Computed] This property is computed by the node on\n   * connection changes.\n   */\n  connectionSuppressed?: boolean\n\n  hidden?: boolean\n  advanced?: boolean\n\n  /**\n   * Canonical visibility component backing the `hidden` / `advanced` /\n   * `options.hideInPanel` facades. Present on concrete widgets; absent on\n   * legacy POJO widgets that have not been adopted yet.\n   */\n  readonly visibility?: WidgetVisibilityComponent\n\n  tooltip?: string\n\n  // TODO: Confirm this format\n  callback?(\n    value: WidgetValue,\n    canvas?: LGraphCanvas,\n    node?: LGraphNode,\n    pos?: Point,\n    e?: CanvasPointerEvent\n  ): void\n\n  /**\n   * Simple callback for pointer events, allowing custom widgets to events relevant to them.\n   * @param event The pointer event that triggered this callback\n   * @param pointerOffset Offset of the pointer relative to {@link node.pos}\n   * @param node The node this widget belongs to\n   * @todo Expose CanvasPointer API to custom widgets\n   */\n  mouse?(\n    event: CanvasPointerEvent,\n    pointerOffset: Point,\n    node: LGraphNode\n  ): boolean\n  /**\n   * Draw the widget.\n   * @param ctx The canvas context to draw on.\n   * @param node The node this widget belongs to.\n   * @param widget_width The width of the widget.\n   * @param y The y position of the widget.\n   * @param H The height of the widget.\n   * @param lowQuality Whether to draw the widget in low quality.\n   */\n  draw?(\n    ctx: CanvasRenderingContext2D,\n    node: LGraphNode,\n    widget_width: number,\n    y: number,\n    H: number,\n    lowQuality?: boolean\n  ): void\n\n  /**\n   * Compatibility method for widgets implementing the draw\n   * method when displayed in non-canvas renderers.\n   * Set by the current renderer implementation.\n   * When called, performs a draw operation.\n   */\n  triggerDraw?: () => void\n\n  /**\n   * Compute the size of the widget. Overrides {@link IBaseWidget.computeSize}.\n   * @param width The width of the widget.\n   * @deprecated Use {@link IBaseWidget.computeLayoutSize} instead.\n   * @returns The size of the widget.\n   */\n  computeSize?(width?: number): Size\n\n  /**\n   * Compute the layout size of the widget.\n   * @param node The node this widget belongs to.\n   * @returns The layout size of the widget.\n   */\n  computeLayoutSize?(\n    this: IBaseWidget,\n    node: LGraphNode\n  ): {\n    minHeight: number\n    maxHeight?: number\n    minWidth: number\n    maxWidth?: number\n  }\n\n  /**\n   * Callback for pointerdown events, allowing custom widgets to register callbacks to occur\n   * for all {@link CanvasPointer} events.\n   *\n   * This callback is operated early in the pointerdown logic; actions that prevent it from firing are:\n   * - `Ctrl + Drag` Multi-select\n   * - `Alt + Click/Drag` Clone node\n   * @param pointer The CanvasPointer handling this event\n   * @param node The node this widget belongs to\n   * @param canvas The LGraphCanvas where this event originated\n   * @returns Returning `true` from this callback forces Litegraph to ignore the event and\n   * not process it any further.\n   */\n  onPointerDown?(\n    pointer: CanvasPointer,\n    node: LGraphNode,\n    canvas: LGraphCanvas\n  ): boolean\n}\n","export type LinkId = number & { readonly __brand: 'LinkId' }\n\nexport function toLinkId(value: number): LinkId {\n  return value as LinkId\n}\n\nexport function parseLinkId(value: string): LinkId | undefined {\n  const id = Number(value)\n  return Number.isSafeInteger(id) && String(id) === value\n    ? toLinkId(id)\n    : undefined\n}\n","export type RerouteId = number & { readonly __brand: 'RerouteId' }\n\nexport function toRerouteId(value: number): RerouteId {\n  return value as RerouteId\n}\n","import { z } from 'zod'\nimport { fromZodError } from 'zod-validation-error'\nimport type { RendererType } from '@/lib/litegraph/src/LGraph'\nimport type {\n  ClipboardItems,\n  ExportedSubgraph\n} from '@/lib/litegraph/src/types/serialisation'\nimport { isWidgetValue } from '@/lib/litegraph/src/types/widgets'\nimport type { TWidgetValue } from '@/lib/litegraph/src/types/widgets'\nimport { parseLinkId, toLinkId } from '@/types/linkId'\nimport type { LinkPresentation } from '@/types/linkPresentation'\nimport type { NodeProperty } from '@/types/nodeState'\nimport { toRerouteId } from '@/types/rerouteId'\n\nconst zRendererType = z.enum([\n  'LG',\n  'Vue',\n  'Vue-corrected'\n]) satisfies z.ZodType<RendererType>\n\n// GroupNode is hacking node id to be a string, so we need to allow that.\n// innerNode.id = `${this.node.id}:${i}`\n// Remove it after GroupNode is redesigned.\nexport const zNodeId = z.union([z.number().int(), z.string()])\nconst zNodeInputName = z.string()\n\n/**\n * UUID identifier for a saved workflow.\n *\n * Workflow files persist their identity as `id: z.guid()` on the\n * graph schema. This alias names that primitive at use sites (services,\n * stores, share types) without changing structural typing.\n */\nexport type WorkflowId = string\nconst zSlotIndex = z.union([\n  z.number().int(),\n  z\n    .string()\n    .transform((val) => parseInt(val))\n    .refine((val) => !isNaN(val), {\n      message: 'Invalid number'\n    })\n])\n\n// TODO: Investigate usage of array and number as data type usage in custom nodes.\n// Known usage:\n// - https://github.com/rgthree/rgthree-comfy Context Big node is using array as type.\nconst zDataType = z.union([z.string(), z.array(z.string()), z.number()])\n\nconst zVector2 = z.union([\n  z\n    .object({ 0: z.number(), 1: z.number() })\n    .passthrough()\n    .transform((v) => [v[0], v[1]] as [number, number]),\n  z.tuple([z.number(), z.number()])\n])\n\n// Definition of an AI model file used in the workflow.\nexport const zModelFile = z.object({\n  name: z.string(),\n  url: z.string().url(),\n  hash: z.string().optional(),\n  hash_type: z.string().optional(),\n  directory: z.string()\n})\n\n/**\n * A node's declared model entry. Only `name` is required - the shape a\n * workflow must declare to pass validation is `zModelFile`, and a workflow\n * that failed it still loads.\n */\nexport const zDeclaredModelFile = z.object({\n  name: z.string(),\n  url: z.string().optional(),\n  hash: z.string().optional(),\n  hash_type: z.string().optional(),\n  directory: z.string().optional()\n})\n\nconst zGraphState = z\n  .object({\n    lastGroupId: z.number(),\n    lastNodeId: z.number(),\n    lastLinkId: z.number(),\n    lastRerouteId: z.number()\n  })\n  .passthrough()\n\nconst zComfyLink = z.tuple([\n  z.number(), // Link id\n  zNodeId, // Node id of source node\n  zSlotIndex, // Output slot# of source node\n  zNodeId, // Node id of destination node\n  zSlotIndex, // Input slot# of destination node\n  zDataType // Data type\n])\n\n/** Extension to 0.4 schema (links as arrays): parent reroute ID */\nconst zComfyLinkExtension = z\n  .object({\n    id: z.number(),\n    parentId: z.number()\n  })\n  .passthrough()\n\nconst zLinkPresentationFields = {\n  hidden: z.boolean().optional(),\n  label: z.string().optional()\n} satisfies { [K in keyof LinkPresentation]-?: z.ZodType<LinkPresentation[K]> }\n\nconst zComfyLinkPresentation = z.object(zLinkPresentationFields).passthrough()\n\nconst zComfyLinkObject = z\n  .object({\n    id: z.number(),\n    origin_id: zNodeId,\n    origin_slot: zSlotIndex,\n    target_id: zNodeId,\n    target_slot: zSlotIndex,\n    type: zDataType,\n    parentId: z.number().optional(),\n    ...zLinkPresentationFields\n  })\n  .passthrough()\n\nconst zReroute = z\n  .object({\n    id: z.number(),\n    parentId: z.number().optional(),\n    pos: zVector2,\n    linkIds: z.array(z.number()).nullish(),\n    floating: z\n      .object({\n        slotType: z.enum(['input', 'output'])\n      })\n      .optional()\n  })\n  .passthrough()\n\nconst zNodeOutput = z\n  .object({\n    name: z.string(),\n    type: zDataType,\n    links: z.array(z.number()).nullable().optional(),\n    slot_index: zSlotIndex.optional()\n  })\n  .passthrough()\n\nconst zNodeInput = z\n  .object({\n    name: zNodeInputName,\n    type: zDataType,\n    link: z.number().nullable().optional(),\n    slot_index: zSlotIndex.optional()\n  })\n  .passthrough()\n\nconst zFlags = z\n  .object({\n    collapsed: z.boolean().optional(),\n    pinned: z.boolean().optional(),\n    allow_interaction: z.boolean().optional(),\n    horizontal: z.boolean().optional(),\n    skip_repeated_outputs: z.boolean().optional()\n  })\n  .passthrough()\n\nconst repoLikeIdPattern = /^[a-zA-Z0-9](?:[a-zA-Z0-9._-]*[a-zA-Z0-9])?$/\nconst githubUsernamePattern = /^(?!-)(?!.*--)[a-zA-Z0-9-]+(?<!-)$/\nconst gitHashPattern = /^[0-9a-f]{4,40}$/i\nconst semverPattern =\n  /^(0|[1-9]\\d*)\\.(0|[1-9]\\d*)\\.(0|[1-9]\\d*)(?:-([\\da-z-]+(?:\\.[\\da-z-]+)*))?(?:\\+([\\da-z-]+(?:\\.[\\da-z-]+)*))?$/\n\n// Shared schema for Comfy Node Registry IDs and GitHub repo names\nconst zRepoLikeId = z\n  .string()\n  .min(1)\n  .max(100)\n  .regex(repoLikeIdPattern, {\n    message: \"ID can only contain ASCII letters, digits, '_', '-', and '.'\"\n  })\n  .refine((id) => !/^[_\\-.]|[_\\-.]$/.test(id), {\n    message: \"ID must not start or end with '_', '-', or '.'\"\n  })\n\nconst zCnrId = zRepoLikeId\nconst zGithubRepoName = zRepoLikeId\n\n// GitHub username/organization schema\nconst zGithubUsername = z\n  .string()\n  .min(1)\n  .max(39)\n  .regex(githubUsernamePattern, 'Invalid GitHub username/org')\n\n// Auxiliary ID identifies node packs not installed via the Comfy Node Registry\nconst zAuxId = z\n  .string()\n  .regex(/^[^/]+\\/[^/]+$/, \"Invalid format. Must be 'github-user/repo-name'\")\n  .transform((id) => id.split('/'))\n  .refine(\n    ([username, repo]) =>\n      zGithubUsername.safeParse(username).success &&\n      zGithubRepoName.safeParse(repo).success,\n    \"Invalid aux_id: Must be valid 'github-username/github-repo-name'\"\n  )\n  .transform(([username, repo]) => `${username}/${repo}`)\n\nconst zGitHash = z.string().superRefine((val: string, ctx) => {\n  if (!gitHashPattern.test(val)) {\n    ctx.addIssue({\n      code: z.ZodIssueCode.custom,\n      message: `Node pack version has invalid Git commit hash: \"${val}\"`\n    })\n  }\n})\nconst zSemVer = z.string().superRefine((val: string, ctx) => {\n  if (!semverPattern.test(val)) {\n    ctx.addIssue({\n      code: z.ZodIssueCode.custom,\n      message: `Node pack version has invalid semantic version: \"${val}\"`\n    })\n  }\n})\nconst zVersion = z.union([\n  z\n    .string()\n    .transform((ver) => ver.replace(/^v/, '')) // Strip leading 'v'\n    .pipe(z.union([zSemVer, zGitHash])),\n  z.literal('unknown')\n])\n\nconst zNodeProperty = z.union([\n  z.string(),\n  z.number(),\n  z.boolean(),\n  z.null(),\n  z.record(z.string(), z.unknown()),\n  z.array(z.unknown())\n]) satisfies z.ZodType<NodeProperty>\n\nconst zProperties = z\n  .object({\n    ['Node name for S&R']: z.string().optional(),\n    cnr_id: zCnrId.optional(),\n    aux_id: zAuxId.optional(),\n    ver: zVersion.optional(),\n    models: z.array(zModelFile).optional()\n  })\n  .catchall(zNodeProperty.optional())\n\nconst zWidgetValue = z.custom<TWidgetValue>(isWidgetValue)\nconst zWidgetValues: z.ZodType<TWidgetValue[] | Record<string, TWidgetValue>> =\n  z.union([z.array(zWidgetValue), z.record(z.string(), zWidgetValue)])\nconst MAX_CLIPBOARD_WIDGET_VALUES = 10_000\n\nfunction hasSupportedClipboardWidgetValuesLength(\n  values: z.output<typeof zWidgetValues> | undefined\n): boolean {\n  if (!values || Array.isArray(values)) return true\n  return (\n    typeof values.length !== 'number' ||\n    values.length <= MAX_CLIPBOARD_WIDGET_VALUES\n  )\n}\n\nfunction isArrayLikeLength(value: TWidgetValue): value is number {\n  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0\n}\n\nfunction normalizeClipboardWidgetValues(\n  values: z.output<typeof zWidgetValues> | undefined\n): TWidgetValue[] | undefined {\n  if (!values || Array.isArray(values)) return values\n  const length = values.length\n  if (!isArrayLikeLength(length)) return []\n  const normalized: TWidgetValue[] = []\n  normalized.length = length\n  for (const [key, value] of Object.entries(values)) {\n    const index = Number(key)\n    if (Number.isInteger(index) && index >= 0 && index < length)\n      normalized[index] = value\n  }\n  return normalized\n}\n\nfunction normalizeClipboardNodeWidgets<\n  T extends { widgets_values?: z.output<typeof zWidgetValues> }\n>(node: T) {\n  const values = node.widgets_values\n  if (values && !Array.isArray(values) && typeof values.length !== 'number') {\n    return {\n      ...node,\n      widgets_values: undefined,\n      widgets_values_named: { ...values }\n    }\n  }\n  return { ...node, widgets_values: normalizeClipboardWidgetValues(values) }\n}\n\nexport const zComfyNode = z\n  .object({\n    id: zNodeId,\n    type: z.string(),\n    pos: zVector2,\n    size: zVector2,\n    flags: zFlags,\n    order: z.number(),\n    mode: z.number(),\n    inputs: z.array(zNodeInput).optional(),\n    outputs: z.array(zNodeOutput).optional(),\n    properties: zProperties,\n    widgets_values: zWidgetValues.optional(),\n    color: z.string().optional(),\n    bgcolor: z.string().optional()\n  })\n  .passthrough()\n\nconst zSubgraphIO = zNodeInput.extend({\n  /** Slot ID (internal; never changes once instantiated). */\n  id: z.guid(),\n  /** The data type this slot uses. Unlike nodes, this does not support legacy numeric types. */\n  type: z.string(),\n  /** Links connected to this slot, or `undefined` if not connected. An output slot should only ever have one link. */\n  linkIds: z.array(z.number()).optional()\n})\n\nconst zSubgraphInstance = z\n  .object({\n    id: zNodeId,\n    type: z.guid(),\n    pos: zVector2,\n    size: zVector2,\n    flags: zFlags,\n    order: z.number(),\n    mode: z.number(),\n    inputs: z.array(zSubgraphIO).optional(),\n    outputs: z.array(zSubgraphIO).optional(),\n    widgets_values: zWidgetValues.optional(),\n    color: z.string().optional(),\n    bgcolor: z.string().optional()\n  })\n  .passthrough()\n\nconst zGroup = z\n  .object({\n    id: z.number().optional(),\n    title: z.string(),\n    bounding: z.tuple([z.number(), z.number(), z.number(), z.number()]),\n    color: z.string().optional(),\n    font_size: z.number().optional(),\n    locked: z.boolean().optional()\n  })\n  .passthrough()\n\nconst zDS = z\n  .object({\n    scale: z.number(),\n    offset: zVector2\n  })\n  .passthrough()\n\nconst zConfig = z\n  .object({\n    links_ontop: z.boolean().optional(),\n    align_to_grid: z.boolean().optional()\n  })\n  .passthrough()\n\nconst zExtra = z\n  .object({\n    ds: zDS.optional(),\n    frontendVersion: z.string().optional(),\n    linkExtensions: z.array(zComfyLinkExtension).optional(),\n    linkPresentation: z\n      .record(\n        z.string().refine((value) => parseLinkId(value) !== undefined, {\n          message: 'Expected a canonical integer link ID'\n        }),\n        zComfyLinkPresentation\n      )\n      .optional(),\n    reroutes: z.array(zReroute).optional(),\n    workflowRendererVersion: zRendererType.optional(),\n    BlueprintDescription: z.string().optional(),\n    BlueprintSearchAliases: z.array(z.string()).optional(),\n    linearMode: z.boolean().optional(),\n    linearData: z\n      .object({\n        inputs: z\n          .array(\n            z.union([\n              z.tuple([\n                zNodeId,\n                z.string(),\n                z.object({ height: z.number().optional() }).passthrough()\n              ]),\n              z.tuple([zNodeId, z.string()])\n            ])\n          )\n          .optional(),\n        outputs: z.array(zNodeId).optional()\n      })\n      .optional()\n  })\n  .passthrough()\n\nconst zGraphDefinitions = z.object({\n  subgraphs: z.lazy(() => z.array(zSubgraphDefinition))\n})\n\nconst zBaseExportableGraph = z.object({\n  /** Unique graph ID.  Automatically generated if not provided. */\n  id: z.guid().optional(),\n  revision: z.number().optional(),\n  config: zConfig.optional().nullable(),\n  /** Details of the appearance and location of subgraphs shown in this graph. Similar to */\n  subgraphs: z.array(zSubgraphInstance).optional()\n})\n\n/** Schema version 0.4 */\nexport const zComfyWorkflow = zBaseExportableGraph\n  .extend({\n    id: z.guid().optional(),\n    revision: z.number().optional(),\n    last_node_id: zNodeId,\n    last_link_id: z.number(),\n    nodes: z.array(zComfyNode),\n    links: z.array(zComfyLink),\n    floatingLinks: z.array(zComfyLinkObject).optional(),\n    groups: z.array(zGroup).optional(),\n    config: zConfig.optional().nullable(),\n    extra: zExtra.optional().nullable(),\n    version: z.number(),\n    models: z.array(zModelFile).optional(),\n    definitions: zGraphDefinitions.optional()\n  })\n  .passthrough()\n\n/** Required for recursive definition of subgraphs. */\ninterface ComfyWorkflow1BaseType {\n  id?: string\n  revision?: number\n  version: 1\n  models?: z.infer<typeof zModelFile>[]\n  state: z.infer<typeof zGraphState>\n}\n\n/** Required for recursive definition of subgraphs w/ZodEffects. */\ninterface ComfyWorkflow1BaseInput extends ComfyWorkflow1BaseType {\n  groups?: z.input<typeof zGroup>[]\n  nodes: z.input<typeof zComfyNode>[]\n  links?: z.input<typeof zComfyLinkObject>[]\n  floatingLinks?: z.input<typeof zComfyLinkObject>[]\n  reroutes?: z.input<typeof zReroute>[]\n  definitions?: {\n    subgraphs: SubgraphDefinitionBase<ComfyWorkflow1BaseInput>[]\n  }\n}\n\n/** Required for recursive definition of subgraphs w/ZodEffects. */\ninterface ComfyWorkflow1BaseOutput extends ComfyWorkflow1BaseType {\n  groups?: z.output<typeof zGroup>[]\n  nodes: z.output<typeof zComfyNode>[]\n  links?: z.output<typeof zComfyLinkObject>[]\n  floatingLinks?: z.output<typeof zComfyLinkObject>[]\n  reroutes?: z.output<typeof zReroute>[]\n  definitions?: {\n    subgraphs: SubgraphDefinitionBase<ComfyWorkflow1BaseOutput>[]\n  }\n}\n\n/** Schema version 1 */\nexport const zComfyWorkflow1 = zBaseExportableGraph\n  .extend({\n    id: z.guid().optional(),\n    revision: z.number().optional(),\n    version: z.literal(1),\n    config: zConfig.optional().nullable(),\n    state: zGraphState,\n    groups: z.array(zGroup).optional(),\n    nodes: z.array(zComfyNode),\n    links: z.array(zComfyLinkObject).optional(),\n    floatingLinks: z.array(zComfyLinkObject).optional(),\n    reroutes: z.array(zReroute).optional(),\n    extra: zExtra.optional().nullable(),\n    models: z.array(zModelFile).optional(),\n    definitions: z\n      .object({\n        subgraphs: z.lazy(\n          (): z.ZodArray<\n            z.ZodType<\n              SubgraphDefinitionBase<ComfyWorkflow1BaseOutput>,\n              SubgraphDefinitionBase<ComfyWorkflow1BaseInput>\n            >\n          > => z.array(zSubgraphDefinition)\n        )\n      })\n      .optional()\n  })\n  .passthrough()\n\nconst zExportedSubgraphIONode = z.object({\n  id: zNodeId,\n  bounding: z.tuple([z.number(), z.number(), z.number(), z.number()]),\n  pinned: z.boolean().optional()\n})\n\nconst zExposedWidget = z.object({\n  id: z.string(),\n  name: z.string()\n})\n\ninterface SubgraphDefinitionBase<\n  T extends ComfyWorkflow1BaseInput | ComfyWorkflow1BaseOutput\n> {\n  /** Unique graph ID.  Automatically generated if not provided. */\n  id: string\n  revision: number\n  name: string\n  /** Optional description shown as tooltip when hovering over the subgraph node. */\n  description?: string\n  category?: string\n  essentials_category?: string\n  /** Custom metadata for the subgraph (description, searchAliases, etc.) */\n  extra?: T extends ComfyWorkflow1BaseInput\n    ? z.input<typeof zExtra> | null\n    : z.output<typeof zExtra> | null\n\n  inputNode: T extends ComfyWorkflow1BaseInput\n    ? z.input<typeof zExportedSubgraphIONode>\n    : z.output<typeof zExportedSubgraphIONode>\n  outputNode: T extends ComfyWorkflow1BaseInput\n    ? z.input<typeof zExportedSubgraphIONode>\n    : z.output<typeof zExportedSubgraphIONode>\n  /** Ordered list of inputs to the subgraph itself. Similar to a reroute, with the input side in the graph, and the output side in the subgraph. */\n  inputs?: T extends ComfyWorkflow1BaseInput\n    ? z.input<typeof zSubgraphIO>[]\n    : z.output<typeof zSubgraphIO>[]\n  /** Ordered list of outputs from the subgraph itself. Similar to a reroute, with the input side in the subgraph, and the output side in the graph. */\n  outputs?: T extends ComfyWorkflow1BaseInput\n    ? z.input<typeof zSubgraphIO>[]\n    : z.output<typeof zSubgraphIO>[]\n  /** A list of node widgets displayed in the parent graph, on the subgraph object. */\n  widgets?: T extends ComfyWorkflow1BaseInput\n    ? z.input<typeof zExposedWidget>[]\n    : z.output<typeof zExposedWidget>[]\n  definitions?: {\n    subgraphs: SubgraphDefinitionBase<T>[]\n  }\n}\n\n/** A subgraph definition `worfklow.definitions.subgraphs` */\nconst zSubgraphDefinition = zComfyWorkflow1\n  .extend({\n    /** Unique graph ID.  Automatically generated if not provided. */\n    id: z.guid(),\n    revision: z.number(),\n    name: z.string(),\n    /** Optional description shown as tooltip when hovering over the subgraph node. */\n    description: z.string().optional(),\n    category: z.string().optional(),\n    essentials_category: z.string().optional(),\n    inputNode: zExportedSubgraphIONode,\n    outputNode: zExportedSubgraphIONode,\n\n    /** Ordered list of inputs to the subgraph itself. Similar to a reroute, with the input side in the graph, and the output side in the subgraph. */\n    inputs: z.array(zSubgraphIO).optional(),\n    /** Ordered list of outputs from the subgraph itself. Similar to a reroute, with the input side in the subgraph, and the output side in the graph. */\n    outputs: z.array(zSubgraphIO).optional(),\n    /** A list of node widgets displayed in the parent graph, on the subgraph object. */\n    widgets: z.array(zExposedWidget).optional(),\n    definitions: z\n      .object({\n        subgraphs: z.lazy(\n          (): z.ZodArray<\n            z.ZodType<\n              SubgraphDefinitionBase<ComfyWorkflow1BaseInput>,\n              SubgraphDefinitionBase<ComfyWorkflow1BaseInput>\n            >\n          > => zSubgraphDefinition.array()\n        )\n      })\n      .optional()\n  })\n  .passthrough()\n\nconst zClipboardNode = zComfyNode\n  .refine(\n    (node) => hasSupportedClipboardWidgetValuesLength(node.widgets_values),\n    {\n      path: ['widgets_values'],\n      message: 'Clipboard widget values length is too large'\n    }\n  )\n  .transform(normalizeClipboardNodeWidgets)\n\nconst zClipboardSubgraphInstance = zSubgraphInstance\n  .refine(\n    (node) => hasSupportedClipboardWidgetValuesLength(node.widgets_values),\n    {\n      path: ['widgets_values'],\n      message: 'Clipboard widget values length is too large'\n    }\n  )\n  .transform(normalizeClipboardNodeWidgets)\n\nconst zClipboardGroup = zGroup.transform((group) => ({\n  ...group,\n  id: group.id ?? -1\n}))\nconst zClipboardReroute = zReroute.transform((reroute) => ({\n  ...reroute,\n  linkIds: reroute.linkIds ?? []\n}))\n\ninterface ClipboardSubgraphInput extends Omit<\n  z.input<typeof zSubgraphDefinition>,\n  'groups' | 'nodes' | 'reroutes' | 'subgraphs' | 'definitions'\n> {\n  groups?: z.input<typeof zClipboardGroup>[]\n  nodes: z.input<typeof zClipboardNode>[]\n  reroutes?: z.input<typeof zClipboardReroute>[]\n  subgraphs?: z.input<typeof zClipboardSubgraphInstance>[]\n  definitions?: { subgraphs: ClipboardSubgraphInput[] }\n}\n\nconst zClipboardSubgraphDefinition: z.ZodType<\n  ExportedSubgraph,\n  ClipboardSubgraphInput\n> = zSubgraphDefinition\n  .extend({\n    groups: z.array(zClipboardGroup).optional(),\n    nodes: z.array(zClipboardNode),\n    reroutes: z.array(zClipboardReroute).optional(),\n    subgraphs: z.array(zClipboardSubgraphInstance).optional(),\n    definitions: z\n      .object({\n        subgraphs: z.lazy(() => z.array(zClipboardSubgraphDefinition))\n      })\n      .optional()\n  })\n  .transform(({ config, extra, ...subgraph }) => {\n    const normalizedExtra = extra\n      ? {\n          ...extra,\n          reroutes: extra.reroutes?.map((reroute) => ({\n            ...reroute,\n            linkIds: reroute.linkIds ?? []\n          })),\n          linkExtensions: extra.linkExtensions?.map((link) => ({\n            ...link,\n            id: toLinkId(link.id),\n            parentId: toRerouteId(link.parentId)\n          }))\n        }\n      : undefined\n    return {\n      ...subgraph,\n      config: config ?? undefined,\n      extra: normalizedExtra\n    }\n  })\n\nconst zClipboardItemsSchema = z\n  .object({\n    nodes: z.array(zClipboardNode).optional(),\n    groups: z.array(zClipboardGroup).optional(),\n    reroutes: z.array(zClipboardReroute).optional(),\n    links: z.array(zComfyLinkObject).optional(),\n    subgraphs: z.array(zClipboardSubgraphDefinition).optional()\n  })\n  .refine(\n    (items) =>\n      items.nodes !== undefined ||\n      items.groups !== undefined ||\n      items.reroutes !== undefined ||\n      items.links !== undefined ||\n      items.subgraphs !== undefined\n  )\n\nexport const zClipboardItems: z.ZodType<\n  ClipboardItems,\n  z.input<typeof zClipboardItemsSchema>\n> = zClipboardItemsSchema\n\nexport type ModelFile = z.infer<typeof zModelFile>\nexport type DeclaredModelFile = z.infer<typeof zDeclaredModelFile>\nexport type ComfyLinkObject = z.infer<typeof zComfyLinkObject>\nexport type ComfyNode = z.infer<typeof zComfyNode>\nexport type Reroute = z.infer<typeof zReroute>\nexport type WorkflowJSON04 = z.infer<typeof zComfyWorkflow>\nexport type ComfyWorkflowJSON = z.infer<\n  typeof zComfyWorkflow | typeof zComfyWorkflow1\n>\n\n/**\n * The minimum a node must carry for `LGraph.configure` to instantiate it:\n * it calls `LiteGraph.createNode(type)` and assigns `id`.\n */\nconst zLegacyLoadableNode = z\n  .object({\n    id: zNodeId,\n    type: z.string()\n  })\n  .passthrough()\n\nexport const zLegacyLoadableWorkflow = z\n  .object({\n    version: z.number(),\n    nodes: z.array(zLegacyLoadableNode),\n    links: z.array(z.unknown()).optional(),\n    last_node_id: zNodeId.optional(),\n    last_link_id: z.number().optional()\n  })\n  .passthrough()\nexport type LegacyLoadableWorkflow = z.infer<typeof zLegacyLoadableWorkflow>\n\nconst zWorkflowVersion = z.object({\n  version: z.number()\n})\n\nexport async function validateComfyWorkflow(\n  data: unknown,\n  onError: (error: string) => void = console.warn\n): Promise<ComfyWorkflowJSON | null> {\n  const versionResult = zWorkflowVersion.safeParse(data)\n\n  let result: z.ZodSafeParseResult<ComfyWorkflowJSON>\n  if (!versionResult.success) {\n    // Invalid workflow\n    const error = fromZodError(versionResult.error)\n    onError(`Workflow does not contain a valid version.  Zod error:\\n${error}`)\n    return null\n  } else if (versionResult.data.version === 1) {\n    // Schema version 1\n    result = await zComfyWorkflow1.safeParseAsync(data)\n  } else {\n    // Unknown or old version: 0.4\n    result = await zComfyWorkflow.safeParseAsync(data)\n  }\n  if (result.success) return result.data\n\n  const error = fromZodError(result.error)\n  onError(`Invalid workflow against zod schema:\\n${error}`)\n  return null\n}\n\n/**\n * API format workflow for direct API usage.\n */\nconst zNodeInputValue = z.union([\n  // For widget values (can be any type)\n\n  z.any(),\n  // For node links [nodeId, slotIndex]\n  z.tuple([zNodeId, zSlotIndex])\n])\n\nexport const zNodePackMetadata = zProperties\n  .pick({ cnr_id: true, aux_id: true, ver: true })\n  .strip()\n\nconst zNodeData = z.object({\n  inputs: z.record(zNodeInputName, zNodeInputValue),\n  class_type: z.string(),\n  _meta: zNodePackMetadata.extend({ title: z.string() }).optional()\n})\n\nexport const zComfyApiWorkflow = z.record(zNodeId, zNodeData)\nexport type ComfyApiWorkflow = z.infer<typeof zComfyApiWorkflow>\n","import { z } from 'zod'\n\nexport const resultItemType = z.enum(['input', 'output', 'temp'])\nexport type ResultItemType = z.infer<typeof resultItemType>\n","import type { PromptInfo } from '@comfyorg/ingest-types'\nimport { z } from 'zod'\nimport { zNodeId } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { TaskStatus } from '@/platform/tasks/services/taskService'\nimport { resultItemType } from '@/schemas/resultItemTypeSchema'\n\nexport type JobId = string\n\nexport const zResultItem = z.object({\n  filename: z.string().optional(),\n  subfolder: z.string().optional(),\n  type: resultItemType.optional(),\n  display_name: z.string().optional(),\n  id: z.string().optional(),\n  preview_id: z.string().optional()\n})\nexport type ResultItem = z.infer<typeof zResultItem>\n// Uses .passthrough() because custom nodes can output arbitrary keys.\n// See docs/adr/NODE-OUTPUTS-0007-output-passthrough-for-extensible-nodes.md\nconst zOutputs = z\n  .object({\n    audio: z.array(zResultItem).optional(),\n    images: z.array(zResultItem).optional(),\n    video: z.array(zResultItem).optional(),\n    animated: z.array(z.boolean()).optional(),\n    text: z.union([z.string(), z.array(z.string())]).optional()\n  })\n  .passthrough()\n\nexport type NodeExecutionOutput = z.infer<typeof zOutputs>\n\nexport type NodeOutputWith<T extends Record<string, unknown>> =\n  NodeExecutionOutput & T\n\ntype NodeId = z.infer<typeof zNodeId>\n\nexport type StatusWsMessageStatus = PromptInfo\nexport interface StatusWsMessage {\n  status?: StatusWsMessageStatus | null\n  sid?: string | null\n}\nexport interface ProgressWsMessage {\n  value: number\n  max: number\n  prompt_id: JobId\n  node: NodeId\n}\nexport interface NodeProgressState {\n  value: number\n  max: number\n  state: 'pending' | 'running' | 'finished' | 'error'\n  node_id: NodeId\n  prompt_id: JobId\n  display_node_id?: NodeId\n  parent_node_id?: NodeId\n  real_node_id?: NodeId\n}\nexport interface ProgressStateWsMessage {\n  prompt_id: JobId\n  nodes: Record<NodeId, NodeProgressState>\n}\nexport interface ExecutingWsMessage {\n  node: NodeId | null\n  display_node?: NodeId\n  prompt_id: JobId\n}\nexport interface ExecutedWsMessage extends ExecutingWsMessage {\n  node: NodeId\n  display_node: NodeId\n  output: NodeExecutionOutput\n  merge?: boolean\n}\ninterface ExecutionWsMessageBase {\n  prompt_id: JobId\n  timestamp: number\n}\nexport type ExecutionStartWsMessage = ExecutionWsMessageBase\nexport type ExecutionSuccessWsMessage = ExecutionWsMessageBase\nexport interface ExecutionCachedWsMessage extends ExecutionWsMessageBase {\n  nodes: NodeId[]\n}\nexport interface ExecutionInterruptedWsMessage extends ExecutionWsMessageBase {\n  node_id: NodeId\n  node_type: string\n  executed: NodeId[]\n}\nexport interface ExecutionErrorWsMessage extends ExecutionWsMessageBase {\n  node_id?: NodeId | null\n  node_type: string\n  executed: NodeId[]\n  exception_message: string\n  exception_type: string\n  traceback: string[]\n  current_inputs?: unknown\n  current_outputs?: unknown\n}\nexport interface ProgressTextWsMessage {\n  nodeId: NodeId\n  text: string\n  prompt_id?: string\n}\nexport interface NotificationWsMessage {\n  value: string\n  id?: string\n}\nexport interface TerminalSize {\n  cols: number\n  row: number\n}\nexport interface LogEntry {\n  t: string\n  m: string\n}\nexport interface LogsWsMessage {\n  size?: TerminalSize\n  entries: LogEntry[]\n}\nexport interface LogsRawResponse {\n  size: TerminalSize\n  entries: LogEntry[]\n}\nexport type FeatureFlagsWsMessage = Record<string, unknown>\nexport interface AssetDownloadWsMessage {\n  task_id: string\n  asset_name: string\n  bytes_total: number\n  bytes_downloaded: number\n  progress: number\n  status: TaskStatus\n  asset_id?: string\n  error?: string\n}\nexport interface AssetExportWsMessage {\n  task_id: string\n  export_name?: string\n  assets_total: number\n  assets_attempted: number\n  assets_failed: number\n  bytes_total: number\n  bytes_processed: number\n  progress: number\n  status: TaskStatus\n  error?: string\n}\n\nexport const zTaskOutput = z.record(zNodeId, zOutputs)\nexport type TaskOutput = z.infer<typeof zTaskOutput>\n","/**\n * @fileoverview Jobs API types - Backend job API format\n * @module platform/remote/comfyui/jobs/jobTypes\n *\n * These types represent the jobs API format returned by the backend.\n * Jobs API provides a memory-optimized alternative to history API.\n */\n\nimport { zJobEntry } from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nimport { resultItemType } from '@/schemas/resultItemTypeSchema'\nimport { zTaskOutput } from '@/platform/remote/comfyui/execution/types'\n\nconst zJobStatus = z.enum([\n  'pending',\n  'in_progress',\n  'completed',\n  'failed',\n  'cancelled'\n])\n\nconst zPreviewOutput = z\n  .object({\n    filename: z.string().optional(),\n    subfolder: z.string().optional(),\n    type: resultItemType.optional(),\n    nodeId: z.string(),\n    mediaType: z.string(),\n    content: z.string().optional(),\n    display_name: z.string().optional()\n  })\n  .passthrough()\n\n/**\n * Execution error from Jobs API.\n * Similar to ExecutionErrorWsMessage but with optional prompt_id/timestamp/executed\n * since these may not be present in stored errors or infrastructure-generated errors.\n */\nconst zExecutionError = z\n  .object({\n    prompt_id: z.string().optional(),\n    timestamp: z.number().optional(),\n    node_id: z.string(),\n    node_type: z.string(),\n    executed: z.array(z.string()).optional(),\n    exception_message: z.string(),\n    exception_type: z.string(),\n    traceback: z.array(z.string()),\n    current_inputs: z.unknown().optional(),\n    current_outputs: z.unknown().optional()\n  })\n  .passthrough()\n\nexport type ExecutionError = z.infer<typeof zExecutionError>\n\n/**\n * Raw job from API - uses passthrough to allow extra fields\n */\nconst zRawJobListItem = z\n  .object({\n    id: z.string(),\n    status: zJobStatus,\n    create_time: z.number(),\n    execution_start_time: z.number().nullable().optional(),\n    execution_end_time: z.number().nullable().optional(),\n    preview_output: zPreviewOutput.nullable().optional(),\n    // Sourced from the generated `@comfyorg/ingest-types` JobEntry schema\n    // (outputs_count/previewable_outputs_count), widened to nullable since\n    // local ComfyUI's /api/jobs sends explicit nulls where Cloud omits.\n    // .int() inherited from zJobEntry; intentionally stricter than the previous z.number()\n    outputs_count: zJobEntry.shape.outputs_count.nullable(),\n    previewable_outputs_count:\n      zJobEntry.shape.previewable_outputs_count.nullable(),\n    execution_error: zExecutionError.nullable().optional(),\n    workflow_id: z.string().nullable().optional(),\n    priority: z.number().optional()\n  })\n  .passthrough()\n\n/**\n * Job detail - returned by GET /api/jobs/{job_id} (detail endpoint)\n * Includes full workflow and outputs for re-execution and downloads\n */\nexport const zJobDetail = zRawJobListItem\n  .extend({\n    workflow: z.unknown().optional(),\n    outputs: zTaskOutput.optional(),\n    update_time: z.number().optional(),\n    execution_status: z.unknown().optional(),\n    execution_meta: z.unknown().optional()\n  })\n  .passthrough()\n\nconst zPaginationInfo = z.object({\n  offset: z.number(),\n  limit: z.number(),\n  total: z.number(),\n  has_more: z.boolean()\n})\n\nexport const zJobsListResponse = z.object({\n  jobs: z.array(zRawJobListItem),\n  pagination: zPaginationInfo\n})\n\n/**\n * A single output asset produced by a job, enriched with per-output node\n * context (`node_id`, `output_key`, `output_index`) correlated from the job's\n * execution outputs by content hash. Node-context fields are null when the\n * asset cannot be matched to an output entry.\n * Returned by GET /api/jobs/{job_id}/assets.\n */\nconst zJobOutputAsset = z\n  .object({\n    id: z.string(),\n    name: z.string(),\n    hash: z.string().nullable().optional(),\n    preview_url: z.string().nullable().optional(),\n    mime_type: z.string().nullable().optional(),\n    size: z.number().nullable().optional(),\n    node_id: z.string().nullable().optional(),\n    output_key: z.string().nullable().optional(),\n    output_index: z.number().nullable().optional(),\n    created_at: z.string().nullable().optional()\n  })\n  .passthrough()\n\n/**\n * Paginated list of a single job's output assets. The envelope is lenient\n * where `zJobsListResponse` is strict: the cloud serialiser drops null fields\n * (`exclude_none=True`) and this endpoint's pagination convention is\n * unconfirmed, so a missing bookkeeping field must degrade to \"no more pages\"\n * rather than reject the payload and silently disable enrichment.\n */\nexport const zJobAssetsResponse = z.object({\n  job_id: z.string().optional(),\n  assets: z.array(zJobOutputAsset),\n  pagination: z\n    .object({\n      offset: z.number().nullable().optional(),\n      limit: z.number().nullable().optional(),\n      total: z.number().nullable().optional(),\n      has_more: z.boolean().nullable().optional()\n    })\n    .optional()\n})\n\n/** Schema for workflow container structure in job detail responses */\nexport const zWorkflowContainer = z.object({\n  prompt: z.unknown().optional(),\n  extra_data: z\n    .object({\n      extra_pnginfo: z\n        .object({\n          workflow: z.unknown().optional()\n        })\n        .nullish()\n    })\n    .nullish()\n})\n\nexport type JobStatus = z.infer<typeof zJobStatus>\nexport type RawJobListItem = z.infer<typeof zRawJobListItem>\n/** Job list item with priority always set (server-provided or synthetic) */\nexport type JobListItem = RawJobListItem & { priority: number }\nexport type JobDetail = z.infer<typeof zJobDetail>\nexport type JobOutputAsset = z.infer<typeof zJobOutputAsset>\n\n/**\n * A job's output assets plus whether the list is known to be exhaustive.\n * `complete` is false when a page failed, the server reported more pages it\n * did not deliver, or the page cap was hit — callers use it to avoid caching a\n * truncated list as if it were the whole set.\n */\nexport interface JobAssetsResult {\n  assets: JobOutputAsset[]\n  complete: boolean\n}\n\n/** Task type used in the API (queue vs history endpoints) */\nexport type APITaskType = 'queue' | 'history'\n\n/** Internal task type derived from job status for UI display */\nexport type TaskType = 'Running' | 'Pending' | 'History'\n","/**\n * @fileoverview Jobs API Fetchers\n * @module platform/remote/comfyui/jobs/fetchJobs\n *\n * Unified jobs API fetcher for history, queue, and job details.\n * All distributions use the /jobs endpoint.\n */\n\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { validateComfyWorkflow } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { JobId } from '@/platform/remote/comfyui/execution/types'\n\nimport type {\n  JobAssetsResult,\n  JobDetail,\n  JobListItem,\n  JobOutputAsset,\n  JobStatus,\n  RawJobListItem\n} from './jobTypes'\nimport {\n  zJobAssetsResponse,\n  zJobDetail,\n  zJobsListResponse,\n  zWorkflowContainer\n} from './jobTypes'\n\ninterface FetchJobsRawResult {\n  jobs: RawJobListItem[]\n  total: number\n  offset: number\n  limit: number\n  hasMore: boolean\n}\n\nclass JobsApiError extends Error {}\n\ninterface FetchJobsOptions {\n  throwOnError?: boolean\n}\n\nexport interface FetchHistoryPageResult {\n  jobs: JobListItem[]\n  total: number\n  offset: number\n  limit: number\n  hasMore: boolean\n}\n\n/**\n * Fetches raw jobs from /jobs endpoint\n * @internal\n */\nasync function fetchJobsRaw(\n  fetchApi: (url: string) => Promise<Response>,\n  statuses: JobStatus[],\n  maxItems: number = 200,\n  offset: number = 0,\n  options?: FetchJobsOptions\n): Promise<FetchJobsRawResult> {\n  const statusParam = statuses.join(',')\n  const url = `/jobs?status=${statusParam}&limit=${maxItems}&offset=${offset}`\n  try {\n    const res = await fetchApi(url)\n    if (!res.ok) {\n      throw new JobsApiError(`Failed to fetch jobs: ${res.status}`)\n    }\n    const data = zJobsListResponse.parse(await res.json())\n    return {\n      jobs: data.jobs,\n      total: data.pagination.total,\n      offset: data.pagination.offset,\n      limit: data.pagination.limit,\n      hasMore: data.pagination.has_more\n    }\n  } catch (error) {\n    if (options?.throwOnError) throw error\n    console.error('[Jobs API] Error fetching jobs:', error)\n    return { jobs: [], total: 0, offset, limit: maxItems, hasMore: false }\n  }\n}\n\n// Large offset to ensure running/pending jobs sort above history\nconst QUEUE_PRIORITY_BASE = 1_000_000\n\n/**\n * Assigns synthetic priority to jobs.\n * Only assigns if job doesn't already have a server-provided priority.\n */\nfunction assignPriority(\n  jobs: RawJobListItem[],\n  basePriority: number\n): JobListItem[] {\n  return jobs.map((job, index) => ({\n    ...job,\n    priority: job.priority ?? basePriority - index\n  }))\n}\n\n/**\n * Fetches history (terminal state jobs: completed, failed, cancelled)\n * Assigns synthetic priority starting from total (lower than queue jobs).\n */\nexport async function fetchHistory(\n  fetchApi: (url: string) => Promise<Response>,\n  maxItems: number = 200,\n  offset: number = 0\n): Promise<JobListItem[]> {\n  const { jobs } = await fetchHistoryPage(fetchApi, maxItems, offset)\n  return jobs\n}\n\n/**\n * Fetches one page of history with server-provided pagination metadata.\n */\nexport async function fetchHistoryPage(\n  fetchApi: (url: string) => Promise<Response>,\n  maxItems: number = 200,\n  offset: number = 0\n): Promise<FetchHistoryPageResult> {\n  const result = await fetchJobsRaw(\n    fetchApi,\n    ['completed', 'failed', 'cancelled'],\n    maxItems,\n    offset\n  )\n\n  // History gets priority based on total count (lower than queue)\n  return {\n    jobs: assignPriority(result.jobs, result.total - result.offset),\n    total: result.total,\n    offset: result.offset,\n    limit: result.limit,\n    hasMore: result.hasMore\n  }\n}\n\n/**\n * Fetches queue (in_progress + pending jobs)\n * Pending jobs get highest priority, then running jobs.\n */\nexport async function fetchQueue(\n  fetchApi: (url: string) => Promise<Response>,\n  options?: FetchJobsOptions\n): Promise<{ Running: JobListItem[]; Pending: JobListItem[] }> {\n  const { jobs } = await fetchJobsRaw(\n    fetchApi,\n    ['in_progress', 'pending'],\n    200,\n    0,\n    options\n  )\n\n  const running = jobs.filter((j) => j.status === 'in_progress')\n  const pending = jobs.filter((j) => j.status === 'pending')\n\n  // Pending gets highest priority, then running\n  // Both are above any history job due to QUEUE_PRIORITY_BASE\n  return {\n    Running: assignPriority(running, QUEUE_PRIORITY_BASE + running.length),\n    Pending: assignPriority(\n      pending,\n      QUEUE_PRIORITY_BASE + running.length + pending.length\n    )\n  }\n}\n\n/**\n * Fetches full job details from /jobs/{job_id}\n */\nexport async function fetchJobDetail(\n  fetchApi: (url: string) => Promise<Response>,\n  jobId: JobId\n): Promise<JobDetail | undefined> {\n  try {\n    const res = await fetchApi(`/jobs/${encodeURIComponent(jobId)}`)\n\n    if (!res.ok) {\n      console.warn(`Job not found for job ${jobId}`)\n      return undefined\n    }\n\n    return zJobDetail.parse(await res.json())\n  } catch (error) {\n    console.error(`Failed to fetch job detail for job ${jobId}:`, error)\n    return undefined\n  }\n}\n\n// Server caps the page size at 500; a single job's outputs fit well within a\n// few pages, so this bound also guards against a runaway pagination loop.\nconst JOB_ASSETS_PAGE_SIZE = 500\nconst JOB_ASSETS_MAX_PAGES = 20\n\n/**\n * Fetches all output assets for a job from GET /api/jobs/{job_id}/assets,\n * paginating internally. Each asset carries a real asset id plus per-output\n * node context (node_id, output_key, output_index) resolved server-side by\n * content hash. Degrades to whatever was accumulated on any failure (e.g. the\n * endpoint is unavailable on non-cloud distributions) so callers can still\n * render; `complete` is false whenever pages are known to be missing, so a\n * truncated list is distinguishable from a full one and callers can decline to\n * cache it.\n */\nexport async function fetchJobAssets(\n  fetchApi: (url: string) => Promise<Response>,\n  jobId: JobId\n): Promise<JobAssetsResult> {\n  const assets: JobOutputAsset[] = []\n  let offset = 0\n\n  try {\n    for (let page = 0; page < JOB_ASSETS_MAX_PAGES; page++) {\n      const url = `/jobs/${encodeURIComponent(jobId)}/assets?limit=${JOB_ASSETS_PAGE_SIZE}&offset=${offset}`\n      const res = await fetchApi(url)\n      if (!res.ok) {\n        console.warn(\n          `[Jobs API] Failed to fetch assets for job ${jobId}: ${res.status}`\n        )\n        return { assets, complete: false }\n      }\n\n      const data = zJobAssetsResponse.parse(await res.json())\n      assets.push(...data.assets)\n\n      const hasMore = data.pagination?.has_more ?? false\n      if (!hasMore) return { assets, complete: true }\n\n      if (data.assets.length === 0) {\n        console.warn(\n          `[Jobs API] Job ${jobId} assets page reported has_more with an empty page; stopping pagination`\n        )\n        return { assets, complete: false }\n      }\n\n      offset += data.assets.length\n    }\n  } catch (error) {\n    console.error(`Failed to fetch assets for job ${jobId}:`, error)\n    return { assets, complete: false }\n  }\n\n  console.warn(\n    `[Jobs API] Job ${jobId} assets pagination hit the ${JOB_ASSETS_MAX_PAGES}-page cap; returning a truncated list`\n  )\n  return { assets, complete: false }\n}\n\n/**\n * Extracts and validates workflow from job detail response.\n * The workflow is nested at: workflow.extra_data.extra_pnginfo.workflow\n *\n * Uses Zod validation via validateComfyWorkflow to ensure the workflow\n * conforms to the expected schema. Logs validation failures for debugging\n * but still returns undefined to allow graceful degradation.\n */\nexport async function extractWorkflow(\n  job: JobDetail | undefined\n): Promise<ComfyWorkflowJSON | undefined> {\n  const parsed = zWorkflowContainer.safeParse(job?.workflow)\n  if (!parsed.success) return undefined\n\n  const rawWorkflow = parsed.data.extra_data?.extra_pnginfo?.workflow\n  if (!rawWorkflow) return undefined\n\n  const validated = await validateComfyWorkflow(rawWorkflow, (error) => {\n    console.warn('[extractWorkflow] Workflow validation failed:', error)\n  })\n\n  return validated ?? undefined\n}\n\n/**\n * Extracts the API-format graph a job stores at: workflow.prompt\n *\n * Jobs submitted through the API embed no editor workflow, leaving the\n * API-format prompt as the only graph they store. Returns undefined whenever\n * an embedded workflow exists so those submissions are always used as-is,\n * never re-derived. The prompt itself is returned unvalidated — callers gate\n * it with `app.isApiJson` before loading it.\n */\nexport function extractApiPrompt(job: JobDetail | undefined): unknown {\n  const parsed = zWorkflowContainer.safeParse(job?.workflow)\n  if (!parsed.success) return undefined\n\n  const embeddedWorkflow = parsed.data.extra_data?.extra_pnginfo?.workflow\n  if (embeddedWorkflow !== undefined && embeddedWorkflow !== null) {\n    return undefined\n  }\n\n  return parsed.data.prompt\n}\n","import type {\n  GetEmbeddingsResponse,\n  GetExtensionsResponse,\n  GetI18nResponse,\n  PostAssetsFromWorkflowResponse\n} from '@comfyorg/ingest-types'\nimport {\n  zGetEmbeddingsResponse,\n  zGetExtensionsResponse,\n  zPostAssetsFromWorkflowResponse\n} from '@comfyorg/ingest-types/zod'\nimport axios from 'axios'\nimport { get } from 'es-toolkit/compat'\nimport { trimEnd } from 'es-toolkit'\nimport { ref } from 'vue'\n\nimport defaultClientFeatureFlags from '@/config/clientFeatureFlags.json' with { type: 'json' }\nimport type { ApiAuthProvider } from '@/platform/auth/apiAuthProvider'\nimport { anonymousApiAuthProvider } from '@/platform/auth/apiAuthProvider'\nimport {\n  authCredentialOf,\n  notifyAuthCredential\n} from '@/platform/auth/authCredential'\nimport { scopeMediaRoute } from '@/platform/auth/session/sessionMediaUrl'\nimport { webSessionRequests } from '@/platform/auth/session/webSessionFetch'\nimport { FETCH_RESPONSE_HEADERS_TIMEOUT_MS } from '@/scripts/apiTimeouts'\nimport { getDevOverride } from '@/utils/devFeatureFlagOverride'\nimport { getSessionOverride } from '@/utils/sessionFeatureFlagOverride'\nimport type {\n  ModelFile,\n  ModelFolderInfo\n} from '@/platform/assets/schemas/assetSchema'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { t } from '@/i18n'\nimport { isCloud } from '@/platform/distribution/types'\nimport { addBreadcrumb } from '@sentry/vue'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { components as ManagerComponents } from '@/workbench/extensions/manager/types/generatedManagerTypes'\nimport type {\n  AssetDownloadWsMessage,\n  AssetExportWsMessage,\n  ExecutedWsMessage,\n  ExecutingWsMessage,\n  ExecutionCachedWsMessage,\n  ExecutionErrorWsMessage,\n  ExecutionInterruptedWsMessage,\n  ExecutionStartWsMessage,\n  ExecutionSuccessWsMessage,\n  FeatureFlagsWsMessage,\n  LogsRawResponse,\n  LogsWsMessage,\n  NotificationWsMessage,\n  ProgressStateWsMessage,\n  ProgressTextWsMessage,\n  ProgressWsMessage,\n  StatusWsMessage,\n  StatusWsMessageStatus\n} from '@/platform/remote/comfyui/execution/types'\nimport type {\n  PromptFailureResponse,\n  PromptResponse,\n  SystemStats,\n  UserConfigResponse,\n  UserDataFullInfo\n} from '@/platform/remote/comfyui/types'\nimport type { PreviewMethod, Settings } from '@/platform/settings/types'\nimport type {\n  TemplateIncludeOnDistributionEnum,\n  WorkflowTemplates\n} from '@/platform/workflow/templates/types/template'\nimport type {\n  ComfyApiWorkflow,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport type {\n  JobAssetsResult,\n  JobDetail,\n  JobListItem\n} from '@/platform/remote/comfyui/jobs/jobTypes'\nimport type { ComfyNodeDef } from '@/schemas/nodeDefSchema'\nimport type { AuthCredential, AuthScheme } from '@/types/authTypes'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\nimport {\n  fetchHistory,\n  fetchJobAssets,\n  fetchJobDetail,\n  fetchQueue\n} from '@/platform/remote/comfyui/jobs/fetchJobs'\n\nconst SERVER_FEATURE_FLAGS_TIMEOUT_MS = 5_000\n\ninterface QueuePromptRequestBody {\n  client_id: string\n  prompt: ComfyApiWorkflow\n  partial_execution_targets?: NodeExecutionId[]\n  extra_data: {\n    extra_pnginfo: {\n      workflow: ComfyWorkflowJSON\n    }\n    /**\n     * The auth token for the comfy org account if the user is logged in.\n     *\n     * Backend node can access this token by specifying following input:\n     * ```python\n      @classmethod\n      def INPUT_TYPES(s):\n        return {\n          \"hidden\": { \"auth_token\": \"AUTH_TOKEN_COMFY_ORG\"}\n        }\n\n      def execute(self, auth_token: str):\n        print(f\"Auth token: {auth_token}\")\n     * ```\n     */\n    auth_token_comfy_org?: string\n    /**\n     * The auth token for the comfy org account if the user is logged in.\n     *\n     * Backend node can access this token by specifying following input:\n     * ```python\n     * def INPUT_TYPES(s):\n     *   return {\n     *     \"hidden\": { \"api_key\": \"API_KEY_COMFY_ORG\" }\n     *   }\n     *\n     * def execute(self, api_key: str):\n     *   print(f\"API Key: {api_key}\")\n     * ```\n     */\n    api_key_comfy_org?: string\n    /**\n     * Identifies the client submitting the prompt. Forwarded by the backend\n     * to API nodes' upstream requests via the Comfy-Usage-Source header.\n     */\n    comfy_usage_source?: string\n    /**\n     * Override the preview method for this prompt execution.\n     * 'default' uses the server's CLI setting.\n     */\n    preview_method?: PreviewMethod\n  }\n  front?: boolean\n  number?: number\n}\n\ninterface FetchApiOptions extends RequestInit {\n  timeoutMs?: number | null\n  onAuthHeader?: (attached: boolean) => void\n  /** Reports which auth path was taken, independent of onAuthHeader's attached/not boolean. */\n  onAuthScheme?: (scheme: AuthScheme) => void\n  /** Reports the kind of credential sent, to tell a missing token from a wrong one. */\n  onAuthCredential?: (credential: AuthCredential) => void\n}\n\nconst FETCH_ROUTE_GROUPS = new Set([\n  'assets',\n  'embeddings',\n  'experiment',\n  'extensions',\n  'features',\n  'files',\n  'folder_paths',\n  'free',\n  'global_subgraphs',\n  'history',\n  'hub',\n  'internal',\n  'interrupt',\n  'jobs',\n  'logs',\n  'models',\n  'node_replacements',\n  'object_info',\n  'prompt',\n  'providers',\n  'queue',\n  'secrets',\n  'settings',\n  'system_stats',\n  'upload',\n  'user',\n  'userdata',\n  'users',\n  'video_metadata',\n  'view',\n  'view_metadata',\n  'workflow_templates',\n  'workflows',\n  'workspace'\n])\n\nfunction getFetchRouteTemplate(route: string): string {\n  const segments = (route.split(/[?#]/)[0] ?? '').split('/').filter(Boolean)\n  const routeSegments = segments[0] === 'api' ? segments.slice(1) : segments\n  const [routeGroup, ...resources] = routeSegments\n\n  if (!routeGroup || !FETCH_ROUTE_GROUPS.has(routeGroup)) return '/other'\n  return `/${routeGroup}${resources.length ? '/:resource' : ''}`\n}\n\n/**\n * Options for queuePrompt method\n */\ninterface QueuePromptOptions {\n  /**\n   * Optional list of node execution IDs to execute (partial execution).\n   * Each ID represents a node's position in nested subgraphs.\n   * Format: Colon-separated path of node IDs (e.g., \"123:456:789\")\n   */\n  partialExecutionTargets?: NodeExecutionId[]\n  /**\n   * Override the preview method for this prompt execution.\n   * 'default' uses the server's CLI setting and is not sent to backend.\n   */\n  previewMethod?: PreviewMethod\n}\n\n/** Dictionary of Frontend-generated API calls */\ninterface FrontendApiCalls {\n  graphChanged: ComfyWorkflowJSON\n  /**\n   * Signals that auto-queue should treat the active workflow as changed.\n   * Local change-tracker edits are filtered through the prompt-relevant\n   * projection and evaluated only while Run (on change) is active. For those\n   * edits, position, size, title, collapse, group, viewport, and slot-label\n   * changes do not trigger this signal.\n   * Server-pushed `graphChanged` messages are forwarded unfiltered.\n   * Third-party presentation-only nodes are treated as prompt-relevant.\n   */\n  autoQueueGraphChanged: never\n  promptQueueing: { requestId: number; batchCount: number; number?: number }\n  promptQueued: { number: number; batchCount: number; requestId?: number }\n  graphCleared: never\n  reconnecting: never\n  reconnected: never\n}\n\nexport type PromptQueueingEventPayload = FrontendApiCalls['promptQueueing']\nexport type PromptQueuedEventPayload = FrontendApiCalls['promptQueued']\n\n/** Dictionary of calls originating from ComfyUI core */\ninterface BackendApiCalls {\n  progress: ProgressWsMessage\n  executing: ExecutingWsMessage\n  executed: ExecutedWsMessage\n  status: StatusWsMessage\n  notification: NotificationWsMessage\n  execution_start: ExecutionStartWsMessage\n  execution_success: ExecutionSuccessWsMessage\n  execution_error: ExecutionErrorWsMessage\n  execution_interrupted: ExecutionInterruptedWsMessage\n  execution_cached: ExecutionCachedWsMessage\n  logs: LogsWsMessage\n  /** Binary preview/progress data */\n  b_preview: Blob\n  /** Binary preview with metadata (node_id, job_id) */\n  b_preview_with_metadata: {\n    blob: Blob\n    nodeId: string\n    parentNodeId: string\n    displayNodeId: string\n    realNodeId: string\n    jobId: string\n  }\n  progress_text: ProgressTextWsMessage\n  progress_state: ProgressStateWsMessage\n  feature_flags: FeatureFlagsWsMessage\n  asset_download: AssetDownloadWsMessage\n  asset_export: AssetExportWsMessage\n}\n\n/** Dictionary of all api calls */\ninterface ApiCalls extends BackendApiCalls, FrontendApiCalls {\n  'cm-task-started': ManagerComponents['schemas']['MessageTaskStarted']\n  'cm-task-completed': ManagerComponents['schemas']['MessageTaskDone']\n}\n\n/** Used to create a discriminating union on type value. */\ninterface ApiMessage<T extends keyof ApiCalls> {\n  type: T\n  data: ApiCalls[T]\n}\n\nexport class UnauthorizedError extends Error {}\n\n/** Ensures workers get a fair shake. */\ntype Unionize<T> = T[keyof T]\n\n/**\n *  Discriminated union of generic, i.e.:\n * ```ts\n * // Convert\n * type ApiMessageUnion = ApiMessage<'status' | 'executing' | ...>\n * // To\n * type ApiMessageUnion = ApiMessage<'status'> | ApiMessage<'executing'> | ...\n * ```\n */\ntype ApiMessageUnion = Unionize<{\n  [Key in keyof ApiCalls]: ApiMessage<Key>\n}>\n\n/** Wraps all properties in {@link CustomEvent}. */\ntype AsCustomEvents<T> = {\n  readonly [K in keyof T]: CustomEvent<T[K]>\n}\n\n/** Handles differing event and API signatures. */\ntype ApiToEventType<T = ApiCalls> = {\n  [K in keyof T]: K extends 'status'\n    ? StatusWsMessageStatus\n    : K extends 'executing'\n      ? SerializedNodeId\n      : T[K]\n}\n\n/** Dictionary of types used in the detail for a custom event */\ntype ApiEventTypes = ApiToEventType\n\n/** Dictionary of API events: `[name]: CustomEvent<Type>` */\ntype ApiEvents = AsCustomEvents<ApiEventTypes>\n\n/** {@link Omit} all properties that evaluate to `never`. */\ntype NeverNever<T> = {\n  [K in keyof T as T[K] extends never ? never : K]: T[K]\n}\n\n/** {@link Pick} only properties that evaluate to `never`. */\ntype PickNevers<T> = {\n  [K in keyof T as T[K] extends never ? K : never]: T[K]\n}\n\n/** Keys (names) of API events that _do not_ pass a {@link CustomEvent} `detail` object. */\ntype SimpleApiEvents = keyof PickNevers<ApiEventTypes>\n/** Keys (names) of API events that pass a {@link CustomEvent} `detail` object. */\ntype ComplexApiEvents = keyof NeverNever<ApiEventTypes>\n\nexport type GlobalSubgraphData = {\n  name: string\n  info: {\n    node_pack: string\n    category?: string\n    search_aliases?: string[]\n    requiresCustomNodes?: string[]\n    includeOnDistributions?: TemplateIncludeOnDistributionEnum[]\n  }\n  data: string | Promise<string>\n  essentials_category?: string\n}\n\ntype WebSessionSend = (url: string, init: RequestInit) => Promise<Response>\n\nfunction addHeaderEntry(headers: HeadersInit, key: string, value: string) {\n  if (Array.isArray(headers)) {\n    headers.push([key, value])\n  } else if (headers instanceof Headers) {\n    headers.set(key, value)\n  } else {\n    headers[key] = value\n  }\n}\n\n/** EventTarget typing has no generic capability. */\nexport interface ComfyApi extends EventTarget {\n  addEventListener<TEvent extends keyof ApiEvents>(\n    type: TEvent,\n    callback: ((event: ApiEvents[TEvent]) => void) | null,\n    options?: AddEventListenerOptions | boolean\n  ): void\n\n  removeEventListener<TEvent extends keyof ApiEvents>(\n    type: TEvent,\n    callback: ((event: ApiEvents[TEvent]) => void) | null,\n    options?: EventListenerOptions | boolean\n  ): void\n}\n\nexport class PromptExecutionError extends Error {\n  response: PromptFailureResponse\n  status?: number\n\n  constructor(response: PromptFailureResponse, status?: number) {\n    super('Prompt execution failed')\n    this.response = response\n    this.status = status\n  }\n\n  override toString() {\n    let message = ''\n    const error = this.response.error\n    if (typeof error === 'string') {\n      message += error\n    } else if (typeof error === 'object' && error !== null) {\n      const errorMessage = 'message' in error ? error.message : undefined\n      const errorDetails = 'details' in error ? error.details : undefined\n      if (typeof errorMessage === 'string') {\n        message += errorMessage\n        if (typeof errorDetails === 'string') {\n          message += ': ' + errorDetails\n        }\n      }\n    }\n    if (!message && typeof this.response.message === 'string') {\n      message += this.response.message\n    }\n\n    for (const [_, nodeError] of Object.entries(\n      this.response.node_errors ?? []\n    )) {\n      message += '\\n' + nodeError.class_type + ':'\n      for (const errorReason of nodeError.errors) {\n        message += '\\n    - ' + errorReason.message\n        if (errorReason.details) message += ': ' + errorReason.details\n      }\n    }\n\n    return message\n  }\n}\n\nexport class ComfyApi extends EventTarget {\n  private _registered = new Set()\n  /**\n   * Maps an original event listener to its error-guarded wrapper, so that\n   * {@link removeEventListener} can match the wrapper installed by\n   * {@link addEventListener}. Keyed weakly so wrappers are GC'd with listeners.\n   */\n  private _listenerWrappers = new WeakMap<\n    EventListenerOrEventListenerObject,\n    EventListener\n  >()\n  api_host: string\n  api_base: string\n  /**\n   * The client id from the initial session storage.\n   */\n  initialClientId: string | null\n  /**\n   * The current client id from websocket status updates.\n   */\n  clientId?: string\n  /**\n   * The current user id.\n   */\n  user: string\n  socket: WebSocket | null = null\n\n  /**\n   * Monotonic id bumped by every createSocket() attempt. Because createSocket()\n   * holds `this.socket === null` across its async token fetch, two attempts can\n   * overlap (an identity reset racing the close-handler's reconnect, or two\n   * resets in quick succession). Each attempt captures its generation and, once\n   * its awaits settle, only proceeds if it is still the latest — so the newest\n   * identity always wins and superseded attempts never open a leaked socket.\n   */\n  private socketGeneration = 0\n\n  private authProvider: ApiAuthProvider = anonymousApiAuthProvider\n\n  reportedUnknownMessageTypes = new Set<string>()\n\n  /**\n   * Get feature flags supported by this frontend client.\n   * Returns a copy to prevent external modification.\n   */\n  getClientFeatureFlags(): Record<string, unknown> {\n    return { ...defaultClientFeatureFlags }\n  }\n\n  /**\n   * Feature flags received from the backend server.\n   */\n  serverFeatureFlags = ref<Record<string, unknown>>({})\n\n  /**\n   * Whether feature-flag negotiation for the current socket has settled: the\n   * server delivered a map, or delivery was abandoned (5s timeout, or the\n   * socket closed first). Not monotonic: each replacement socket resets it to\n   * false, so it can flip repeatedly while a connection is reconnecting. True\n   * does not imply the map is non-empty, and after {@link resetSocket}\n   * {@link serverFeatureFlags} still holds the previous identity's map until\n   * the next `feature_flags` message replaces it.\n   */\n  serverFeatureFlagsSettled = ref(false)\n\n  /**\n   * The auth token for the comfy org account if the user is logged in.\n   * This is only used for {@link queuePrompt} now. It is not directly\n   * passed as parameter to the function because some custom nodes are hijacking\n   * {@link queuePrompt} improperly, which causes extra parameters to be lost\n   * in the function call chain.\n   *\n   * Ref: https://cs.comfy.org/search?q=context:global+%22api.queuePrompt+%3D%22&patternType=keyword&sm=0\n   *\n   * TODO: Move this field to parameter of {@link queuePrompt} once all\n   * custom nodes are patched.\n   */\n  authToken?: string\n  /**\n   * The API key for the comfy org account if the user logged in via API key.\n   */\n  apiKey?: string\n\n  constructor() {\n    super()\n    this.user = ''\n    this.api_host = location.host\n    this.api_base = isCloud\n      ? ''\n      : location.pathname.split('/').slice(0, -1).join('/')\n    this.initialClientId = sessionStorage.getItem('clientId')\n  }\n\n  internalURL(route: string): string {\n    return this.api_base + '/internal' + route\n  }\n\n  apiURL(route: string): string {\n    const requests = webSessionRequests()\n    return this.unscopedApiURL(\n      requests ? scopeMediaRoute(route, requests.workspaceId()) : route\n    )\n  }\n\n  /** For requests whose headers already name the workspace. */\n  private unscopedApiURL(route: string): string {\n    if (route.startsWith('/api')) return this.api_base + route\n    return this.api_base + '/api' + route\n  }\n\n  fileURL(route: string): string {\n    return this.api_base + route\n  }\n\n  /**\n   * Installs the credentials source for every request and socket connection.\n   * Called once by the composition root; requests made before that are\n   * anonymous.\n   */\n  setAuthProvider(provider: ApiAuthProvider): void {\n    this.authProvider = provider\n  }\n\n  private async getWebSessionSend(): Promise<WebSessionSend | undefined> {\n    const requests = webSessionRequests()\n    if (!requests) return undefined\n    const scope = await requests.scope()\n    return scope && ((url, init) => requests.send(url, init, scope))\n  }\n\n  /** Sends a same-origin request on the web session; undefined when this tab is not on it. */\n  async fetchOnWebSession(\n    url: string,\n    init: RequestInit\n  ): Promise<Response | undefined> {\n    const send = await this.getWebSessionSend()\n    return send?.(url, init)\n  }\n\n  /**\n   * Adds today's token header, reporting the scheme that was actually used and\n   * whether a 401 may be re-minted.\n   *\n   * The scheme is returned rather than assumed by the caller because this helper\n   * is the only place that knows whether a header was obtained: it reports\n   * `authHeader !== null` through `onAuthHeader` and attaches nothing when auth\n   * is unavailable. A caller that announced `cloud-auth-header` on entry to this\n   * path would misreport exactly the unauthenticated case PM-1802 is about.\n   */\n  private async addCloudAuthHeader(\n    headers: HeadersInit,\n    onAuthHeader: FetchApiOptions['onAuthHeader']\n  ): Promise<{\n    scheme: AuthScheme\n    credential: AuthCredential\n    unifiedRetryOn401: boolean\n  }> {\n    const authHeader = await this.authProvider.getAuthHeader()\n    onAuthHeader?.(authHeader !== null)\n    if (!authHeader) {\n      return { scheme: 'none', credential: 'none', unifiedRetryOn401: false }\n    }\n\n    for (const [key, value] of Object.entries(authHeader)) {\n      addHeaderEntry(headers, key, value)\n    }\n    return {\n      scheme: 'cloud-auth-header',\n      credential: authCredentialOf(authHeader),\n      unifiedRetryOn401: await this.authProvider.shouldRetryOn401()\n    }\n  }\n\n  async fetchApi(route: string, options?: FetchApiOptions) {\n    const {\n      timeoutMs = FETCH_RESPONSE_HEADERS_TIMEOUT_MS,\n      onAuthHeader,\n      onAuthScheme,\n      onAuthCredential,\n      ...requestOptions\n    } = options ?? {}\n    const headers: HeadersInit = requestOptions.headers ?? {}\n    let unifiedRetryOn401 = false\n    let sendOnWebSession: WebSessionSend | undefined\n\n    if (isCloud) {\n      await this.authProvider.waitForInitialization()\n      sendOnWebSession = await this.getWebSessionSend()\n      if (sendOnWebSession) {\n        onAuthHeader?.(true)\n        onAuthScheme?.('web-session')\n        notifyAuthCredential(onAuthCredential, 'session-cookie')\n      } else {\n        const cloudAuth = await this.addCloudAuthHeader(headers, onAuthHeader)\n        unifiedRetryOn401 = cloudAuth.unifiedRetryOn401\n        onAuthScheme?.(cloudAuth.scheme)\n        notifyAuthCredential(onAuthCredential, cloudAuth.credential)\n      }\n    } else {\n      onAuthHeader?.(false)\n      onAuthScheme?.('none')\n      notifyAuthCredential(onAuthCredential, 'none')\n    }\n\n    addHeaderEntry(headers, 'Comfy-User', this.user)\n\n    const timeout =\n      timeoutMs === null\n        ? null\n        : { controller: new AbortController(), duration: timeoutMs }\n    const timeoutId = timeout\n      ? setTimeout(() => {\n          const method = (requestOptions.method ?? 'GET').toUpperCase()\n          const routeTemplate = getFetchRouteTemplate(route)\n\n          addBreadcrumb({\n            category: 'fetch',\n            message: `Timeout on ${method} ${routeTemplate}`,\n            level: 'warning',\n            data: { timeout_ms: timeout.duration }\n          })\n\n          useTelemetry()?.trackFetchTimeout({\n            route: routeTemplate,\n            method,\n            timeout_ms: timeout.duration\n          })\n\n          timeout.controller.abort(\n            new DOMException('Fetch timeout', 'TimeoutError')\n          )\n        }, timeout.duration)\n      : undefined\n    const signal =\n      requestOptions.signal && timeout\n        ? AbortSignal.any([requestOptions.signal, timeout.controller.signal])\n        : (requestOptions.signal ?? timeout?.controller.signal)\n\n    let retryTimeoutId: ReturnType<typeof setTimeout> | undefined\n    const retrySignalLifecycle = timeout\n      ? {\n          clearInitialTimeout: () => {\n            if (timeoutId !== undefined) clearTimeout(timeoutId)\n          },\n          createSignal: () => {\n            const retryController = new AbortController()\n            retryTimeoutId = setTimeout(() => {\n              const method = (requestOptions.method ?? 'GET').toUpperCase()\n              const routeTemplate = getFetchRouteTemplate(route)\n\n              addBreadcrumb({\n                category: 'fetch',\n                message: `Timeout on ${method} ${routeTemplate}`,\n                level: 'warning',\n                data: { timeout_ms: timeout.duration }\n              })\n\n              useTelemetry()?.trackFetchTimeout({\n                route: routeTemplate,\n                method,\n                timeout_ms: timeout.duration\n              })\n\n              retryController.abort(\n                new DOMException('Fetch timeout', 'TimeoutError')\n              )\n            }, timeout.duration)\n\n            return requestOptions.signal\n              ? AbortSignal.any([requestOptions.signal, retryController.signal])\n              : retryController.signal\n          }\n        }\n      : undefined\n\n    const init: RequestInit = {\n      cache: 'no-cache',\n      ...requestOptions,\n      headers,\n      signal\n    }\n    const response = sendOnWebSession\n      ? sendOnWebSession(this.unscopedApiURL(route), init)\n      : this.authProvider.fetch(\n          this.apiURL(route),\n          init,\n          unifiedRetryOn401,\n          retrySignalLifecycle\n        )\n    return response.finally(() => {\n      if (timeoutId !== undefined) clearTimeout(timeoutId)\n      if (retryTimeoutId !== undefined) clearTimeout(retryTimeoutId)\n    })\n  }\n\n  /**\n   * Wraps an event listener so an exception thrown by it — most often from a\n   * third-party custom node — is caught and logged instead of surfacing as an\n   * unhandled error in global telemetry (which RUM captures as a high-volume,\n   * non-actionable error). Native EventTarget already isolates listeners from\n   * one another; this only changes where the error goes.\n   *\n   * The same original listener always maps to the same wrapper, so\n   * {@link removeEventListener} still matches. Logged at `warn` level on\n   * purpose: RUM collects `console.error` by default, which would re-introduce\n   * the noise this guard removes.\n   */\n  private wrapListener(\n    callback: EventListenerOrEventListenerObject | null\n  ): EventListenerOrEventListenerObject | null {\n    if (!callback) return callback\n    let wrapped = this._listenerWrappers.get(callback)\n    if (!wrapped) {\n      const logError = (event: Event, error: unknown) =>\n        console.warn(\n          `[ComfyApi] Uncaught error in \"${event.type}\" event listener:`,\n          error\n        )\n      // Regular function (not arrow) so the listener keeps the native\n      // `this === currentTarget` binding that EventTarget provides.\n      wrapped = function (this: unknown, event: Event) {\n        try {\n          const result: unknown =\n            typeof callback === 'function'\n              ? callback.call(this, event)\n              : callback.handleEvent(event)\n          // Async listeners: route a rejected promise through the same guard so\n          // it does not escape as an unhandled rejection (which RUM also logs).\n          if (\n            result != null &&\n            typeof (result as PromiseLike<unknown>).then === 'function'\n          ) {\n            void Promise.resolve(result).catch((error: unknown) =>\n              logError(event, error)\n            )\n          }\n        } catch (error) {\n          logError(event, error)\n        }\n      }\n      this._listenerWrappers.set(callback, wrapped)\n    }\n    return wrapped\n  }\n\n  /**\n   * Looks up the guarded wrapper for a listener without creating one — used on\n   * the remove path so a never-registered callback does not leave a stray\n   * WeakMap entry. Falls back to the original callback (a harmless no-op).\n   */\n  private getWrappedListener(\n    callback: EventListenerOrEventListenerObject | null\n  ): EventListenerOrEventListenerObject | null {\n    if (!callback) return callback\n    return this._listenerWrappers.get(callback) ?? callback\n  }\n\n  override addEventListener<TEvent extends keyof ApiEvents>(\n    type: TEvent,\n    callback: ((event: ApiEvents[TEvent]) => void) | null,\n    options?: AddEventListenerOptions | boolean\n  ) {\n    // Type assertion: strictFunctionTypes.  So long as we emit events in a type-safe fashion, this is safe.\n    super.addEventListener(\n      type,\n      this.wrapListener(callback as EventListener),\n      options\n    )\n    this._registered.add(type)\n  }\n\n  override removeEventListener<TEvent extends keyof ApiEvents>(\n    type: TEvent,\n    callback: ((event: ApiEvents[TEvent]) => void) | null,\n    options?: EventListenerOptions | boolean\n  ): void {\n    super.removeEventListener(\n      type,\n      this.getWrappedListener(callback as EventListener),\n      options\n    )\n  }\n\n  addCustomEventListener(\n    type: string,\n    callback: ((event: CustomEvent<unknown>) => void) | null,\n    options?: AddEventListenerOptions | boolean\n  ) {\n    super.addEventListener(\n      type,\n      this.wrapListener(callback as EventListener),\n      options\n    )\n    this._registered.add(type)\n  }\n\n  removeCustomEventListener(\n    type: string,\n    callback: ((event: CustomEvent<unknown>) => void) | null,\n    options?: EventListenerOptions | boolean\n  ) {\n    super.removeEventListener(\n      type,\n      this.getWrappedListener(callback as EventListener),\n      options\n    )\n  }\n\n  /**\n   * Dispatches a custom event.\n   * Provides type safety for the contravariance issue with EventTarget (last checked TS 5.6).\n   * @param type The type of event to emit\n   * @param detail The detail property used for a custom event ({@link CustomEventInit.detail})\n   */\n  dispatchCustomEvent(type: SimpleApiEvents): boolean\n  dispatchCustomEvent<T extends ComplexApiEvents>(\n    type: T,\n    detail: ApiEventTypes[T] | null\n  ): boolean\n  dispatchCustomEvent<T extends keyof ApiEventTypes>(\n    type: T,\n    detail?: ApiEventTypes[T]\n  ): boolean {\n    const event =\n      detail === undefined\n        ? new CustomEvent(type)\n        : new CustomEvent(type, { detail })\n    return super.dispatchEvent(event)\n  }\n\n  /** @deprecated Use {@link dispatchCustomEvent}. */\n  override dispatchEvent(event: never): boolean {\n    return super.dispatchEvent(event)\n  }\n\n  /**\n   * Poll status  for colab and other things that don't support websockets.\n   */\n  private _pollQueue() {\n    setInterval(async () => {\n      try {\n        const resp = await this.fetchApi('/prompt')\n        const status = (await resp.json()) as StatusWsMessageStatus\n        this.dispatchCustomEvent('status', status)\n      } catch {\n        this.dispatchCustomEvent('status', null)\n      }\n    }, 1000)\n  }\n\n  /** False when the web session is on and no one is signed in to open it. */\n  private async addSocketAuth(params: URLSearchParams): Promise<boolean> {\n    const requests = webSessionRequests()\n    const sessionScope = requests && (await requests.scope())\n    if (sessionScope?.workspaceId) {\n      params.set('workspace_id', sessionScope.workspaceId)\n    }\n    if (sessionScope) return true\n\n    const authToken = await this.authProvider.getAuthToken()\n    if (authToken) {\n      params.set('token', authToken)\n    }\n    return !requests || params.has('token')\n  }\n\n  /**\n   * Creates and connects a WebSocket for realtime updates\n   * @param {boolean} isReconnect If the socket is connection is a reconnect attempt\n   */\n  private async createSocket(isReconnect?: boolean) {\n    if (this.socket) {\n      return\n    }\n    const generation = ++this.socketGeneration\n\n    let opened = false\n    const existingSession = window.name\n\n    // Build WebSocket URL with query parameters\n    const params = new URLSearchParams()\n\n    if (existingSession) {\n      params.set('clientId', existingSession)\n    }\n\n    if (isCloud && !(await this.addSocketAuth(params))) return\n\n    const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws'\n    const baseUrl = `${protocol}://${this.api_host}${this.api_base}/ws`\n    const query = params.toString()\n    const wsUrl = query ? `${baseUrl}?${query}` : baseUrl\n\n    // A newer connect attempt (an identity reset, or a later reconnect) began\n    // while this one awaited its token. Abandon this attempt so only the latest\n    // generation owns this.socket and no superseded socket is opened.\n    if (generation !== this.socketGeneration) return\n\n    const socket = new WebSocket(wsUrl)\n    this.socket = socket\n    this.serverFeatureFlagsSettled.value = false\n    socket.binaryType = 'arraybuffer'\n\n    // Armed before `open` so a socket that never opens still settles.\n    const settleTimer = setTimeout(() => {\n      if (this.socket === socket && !this.serverFeatureFlagsSettled.value) {\n        this.serverFeatureFlagsSettled.value = true\n      }\n    }, SERVER_FEATURE_FLAGS_TIMEOUT_MS)\n\n    socket.addEventListener('open', () => {\n      opened = true\n\n      // Send feature flags as the first message\n      socket.send(\n        JSON.stringify({\n          type: 'feature_flags',\n          data: this.getClientFeatureFlags()\n        })\n      )\n\n      if (isReconnect) {\n        this.dispatchCustomEvent('reconnected')\n      }\n    })\n\n    socket.addEventListener('error', () => {\n      // A replaced socket (e.g. after resetSocket on an account switch) is\n      // already being torn down; ignore its late errors so it cannot start an\n      // unnecessary permanent polling loop for the previous identity.\n      if (this.socket !== socket) return\n      socket.close()\n      if (!isReconnect && !opened) {\n        this._pollQueue()\n      }\n    })\n\n    socket.addEventListener('close', () => {\n      // A replaced socket (e.g. after resetSocket on an account switch) must\n      // not reconnect; only the active socket owns the reconnect lifecycle.\n      if (this.socket !== socket) return\n      this.serverFeatureFlagsSettled.value = true\n      clearTimeout(settleTimer)\n      setTimeout(async () => {\n        if (this.socket !== socket) return\n        this.socket = null\n        await this.createSocket(true)\n      }, 300)\n      if (opened) {\n        this.dispatchCustomEvent('status', null)\n        this.dispatchCustomEvent('reconnecting')\n      }\n    })\n\n    socket.addEventListener('message', (event) => {\n      // Ignore late messages from a replaced socket so previous-account\n      // realtime data is not dispatched after an identity switch.\n      if (this.socket !== socket) return\n      try {\n        if (event.data instanceof ArrayBuffer) {\n          const view = new DataView(event.data)\n          const eventType = view.getUint32(0)\n\n          switch (eventType) {\n            case 3: {\n              try {\n                const decoder3 = new TextDecoder()\n                const rawData = event.data.slice(4)\n                const rawView = new DataView(rawData)\n\n                let offset = 0\n                let promptId: string | undefined\n\n                if (\n                  this.serverSupportsFeature('supports_progress_text_metadata')\n                ) {\n                  const promptIdLength = rawView.getUint32(offset)\n                  offset += 4\n                  promptId = decoder3.decode(\n                    rawData.slice(offset, offset + promptIdLength)\n                  )\n                  offset += promptIdLength\n                }\n\n                const nodeIdLength = rawView.getUint32(offset)\n                offset += 4\n                const nodeId = decoder3.decode(\n                  rawData.slice(offset, offset + nodeIdLength)\n                )\n                offset += nodeIdLength\n                const text = decoder3.decode(rawData.slice(offset))\n\n                this.dispatchCustomEvent('progress_text', {\n                  nodeId,\n                  text,\n                  ...(promptId !== undefined && { prompt_id: promptId })\n                })\n              } catch (e) {\n                console.warn('Failed to parse progress_text binary message', e)\n              }\n              break\n            }\n            case 1: {\n              const imageType = view.getUint32(4)\n              const imageData = event.data.slice(8)\n              const imageMime = imageType === 2 ? 'image/png' : 'image/jpeg'\n              const imageBlob = new Blob([imageData], {\n                type: imageMime\n              })\n              this.dispatchCustomEvent('b_preview', imageBlob)\n              break\n            }\n            case 4: {\n              // PREVIEW_IMAGE_WITH_METADATA\n              const decoder4 = new TextDecoder()\n              const metadataLength = view.getUint32(4)\n              const metadataBytes = event.data.slice(8, 8 + metadataLength)\n              const metadata = JSON.parse(decoder4.decode(metadataBytes))\n              const imageData4 = event.data.slice(8 + metadataLength)\n\n              const imageMime4 = metadata.image_type\n\n              const imageBlob4 = new Blob([imageData4], {\n                type: imageMime4\n              })\n\n              // Dispatch enhanced preview event with metadata\n              this.dispatchCustomEvent('b_preview_with_metadata', {\n                blob: imageBlob4,\n                nodeId: metadata.node_id,\n                displayNodeId: metadata.display_node_id,\n                parentNodeId: metadata.parent_node_id,\n                realNodeId: metadata.real_node_id,\n                jobId: metadata.prompt_id\n              })\n\n              // Also dispatch legacy b_preview for backward compatibility\n              this.dispatchCustomEvent('b_preview', imageBlob4)\n              break\n            }\n            default:\n              console.error(\n                `Unknown binary websocket message of type ${eventType}`\n              )\n              break\n          }\n        } else {\n          const msg = JSON.parse(event.data) as ApiMessageUnion\n          switch (msg.type) {\n            case 'status':\n              if (msg.data.sid) {\n                const clientId = msg.data.sid\n                this.clientId = clientId\n                window.name = clientId // use window name so it isn't reused when duplicating tabs\n                sessionStorage.setItem('clientId', clientId) // store in session storage so duplicate tab can load correct workflow\n              }\n              this.dispatchCustomEvent('status', msg.data.status ?? null)\n              break\n            case 'executing':\n              this.dispatchCustomEvent(\n                'executing',\n                msg.data.display_node || msg.data.node\n              )\n              break\n            case 'execution_start':\n            case 'execution_error':\n            case 'execution_interrupted':\n            case 'execution_cached':\n            case 'execution_success':\n            case 'progress':\n            case 'progress_state':\n            case 'executed':\n            case 'promptQueued':\n            case 'logs':\n            case 'b_preview':\n            case 'notification':\n              this.dispatchCustomEvent(msg.type, msg.data)\n              break\n            case 'graphChanged':\n              this.dispatchCustomEvent('graphChanged', msg.data)\n              this.dispatchCustomEvent('autoQueueGraphChanged')\n              break\n            case 'autoQueueGraphChanged':\n              this.dispatchCustomEvent('autoQueueGraphChanged')\n              break\n            case 'feature_flags':\n              this.serverFeatureFlags.value = msg.data\n              this.serverFeatureFlagsSettled.value = true\n              this.dispatchCustomEvent('feature_flags', msg.data)\n              break\n            default:\n              if (this._registered.has(msg.type)) {\n                // Fallback for custom types - calls super direct.\n                super.dispatchEvent(\n                  new CustomEvent(msg.type, { detail: msg.data })\n                )\n              } else if (!this.reportedUnknownMessageTypes.has(msg.type)) {\n                this.reportedUnknownMessageTypes.add(msg.type)\n                console.error(`Unknown message type ${msg.type}`)\n              }\n          }\n        }\n      } catch (error) {\n        console.warn('Unhandled message:', event.data, error)\n      }\n    })\n  }\n\n  /**\n   * Initialises sockets and realtime updates\n   */\n  async init() {\n    await this.createSocket()\n  }\n\n  /**\n   * Tears down the active realtime socket and reconnects, re-authenticating\n   * with the currently active account's token. Invoked on a direct identity\n   * change so a tab cannot keep receiving the previous account's realtime\n   * events over a handshake that was authenticated as that account.\n   */\n  async resetSocket(): Promise<void> {\n    // Clear every handshake identity source: createSocket() reads the client id\n    // from window.name (mirrored in session storage), not this.clientId, so the\n    // next connect must not inherit the prior account's id.\n    this.clientId = undefined\n    window.name = ''\n    sessionStorage.removeItem('clientId')\n    await this.replaceSocket()\n  }\n\n  /**\n   * Re-handshakes the socket for the same account, keeping its client id, so\n   * a new web session workspace takes effect. Does nothing before init().\n   */\n  async reconnectSocket(): Promise<void> {\n    if (this.socketGeneration === 0) return\n    await this.replaceSocket()\n  }\n\n  private async replaceSocket(): Promise<void> {\n    const previous = this.socket\n    // serverFeatureFlags deliberately keeps the previous map: clearing it would\n    // downgrade every serverSupportsFeature() caller until the next delivery.\n    this.serverFeatureFlagsSettled.value = false\n    // Detach before closing so the previous socket's close handler sees it is\n    // no longer the active socket and does not start a competing reconnect.\n    this.socket = null\n    if (previous && previous.readyState !== WebSocket.CLOSED) {\n      try {\n        previous.close()\n      } catch {\n        // Already-terminating socket; nothing to clean up.\n      }\n    }\n    // createSocket() bumps the generation; any overlapping reset or reconnect\n    // that is still awaiting its token will see it lost the race and bail,\n    // leaving this the sole owner of the reconnected socket.\n    await this.createSocket()\n  }\n\n  /**\n   * Gets a list of extension urls\n   */\n  async getExtensions(): Promise<GetExtensionsResponse> {\n    const resp = await this.fetchApi('/extensions', { cache: 'no-store' })\n    return zGetExtensionsResponse.parse(await resp.json())\n  }\n\n  /**\n   * Gets the available workflow templates from custom nodes.\n   * @returns A map of custom_node names and associated template workflow names.\n   */\n  async getWorkflowTemplates(): Promise<{\n    [customNodesName: string]: string[]\n  }> {\n    const res = await this.fetchApi('/workflow_templates')\n    return await res.json()\n  }\n\n  /**\n   * Gets the index of core workflow templates.\n   * @param locale Optional locale code (e.g., 'en', 'fr', 'zh') to load localized templates\n   */\n  async getCoreWorkflowTemplates(\n    locale?: string\n  ): Promise<WorkflowTemplates[]> {\n    const fileName =\n      locale && locale !== 'en' ? `index.${locale}.json` : 'index.json'\n    try {\n      const res = await axios.get(this.fileURL(`/templates/${fileName}`))\n      const contentType = String(res.headers['content-type'] ?? '')\n      return contentType.includes('application/json') ? res.data : []\n    } catch (error) {\n      // Fallback to default English version if localized version doesn't exist\n      if (locale && locale !== 'en') {\n        console.warn(\n          `Localized templates for '${locale}' not found, falling back to English`\n        )\n        return this.getCoreWorkflowTemplates()\n      }\n      console.error('Error loading core workflow templates:', error)\n      return []\n    }\n  }\n\n  /**\n   * Gets a list of embedding names\n   * @throws When the request fails or the response does not match the schema\n   */\n  async getEmbeddings(): Promise<GetEmbeddingsResponse> {\n    const resp = await this.fetchApi('/embeddings', { cache: 'no-store' })\n    if (!resp.ok) {\n      throw new Error(`Failed to fetch /embeddings: ${resp.status}`)\n    }\n    return zGetEmbeddingsResponse.parse(await resp.json())\n  }\n\n  /**\n   * Loads node object definitions for the graph\n   * @returns The node definitions\n   */\n  async getNodeDefs(): Promise<Record<string, ComfyNodeDef>> {\n    const resp = await this.fetchApi('/object_info', { cache: 'no-store' })\n    return await resp.json()\n  }\n\n  /**\n   * Queues a prompt to be executed\n   * @param {number} number The index at which to queue the prompt, passing -1 will insert the prompt at the front of the queue\n   * @param {object} data The prompt data to queue\n   * @param {QueuePromptOptions} options Optional execution options\n   * @throws {PromptExecutionError} If the prompt fails to execute\n   */\n  async queuePrompt(\n    number: number,\n    data: { output: ComfyApiWorkflow; workflow: ComfyWorkflowJSON },\n    options?: QueuePromptOptions\n  ): Promise<PromptResponse> {\n    const { output: prompt, workflow } = data\n\n    const body: QueuePromptRequestBody = {\n      client_id: this.clientId ?? '', // TODO: Unify clientId access\n      prompt,\n      ...(options?.partialExecutionTargets && {\n        partial_execution_targets: options.partialExecutionTargets\n      }),\n      extra_data: {\n        auth_token_comfy_org: this.authToken,\n        api_key_comfy_org: this.apiKey,\n        comfy_usage_source: 'comfyui-frontend',\n        extra_pnginfo: { workflow },\n        ...(options?.previewMethod &&\n          options.previewMethod !== 'default' && {\n            preview_method: options.previewMethod\n          })\n      }\n    }\n\n    if (number === -1) {\n      body.front = true\n    } else if (number != 0) {\n      body.number = number\n    }\n\n    const res = await this.fetchApi('/prompt', {\n      method: 'POST',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify(body)\n    })\n\n    if (res.status !== 200) {\n      const text = await res.text()\n      let errorResponse\n      try {\n        errorResponse = JSON.parse(text)\n      } catch {\n        errorResponse = {\n          error: {\n            type: 'server_error',\n            message: `${res.status} ${res.statusText}`,\n            details: text\n          }\n        }\n      }\n      throw new PromptExecutionError(errorResponse, res.status)\n    }\n\n    return await res.json()\n  }\n\n  /**\n   * Gets the list of assets and models referenced by a prompt that would\n   * need user consent before sharing.\n   */\n  async getShareableAssets(\n    prompt: ComfyApiWorkflow,\n    options?: { owned?: boolean }\n  ): Promise<PostAssetsFromWorkflowResponse> {\n    const body: Record<string, unknown> = { workflow_api_json: prompt }\n    if (options?.owned !== undefined) {\n      body.owned = options.owned\n    }\n    const res = await this.fetchApi('/assets/from-workflow', {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(body)\n    })\n    if (res.status !== 200) {\n      throw new Error(`Failed to fetch shareable assets: ${res.status}`)\n    }\n    const data = await res.json()\n    return zPostAssetsFromWorkflowResponse.parse(data)\n  }\n\n  /**\n   * Gets a list of model folder keys (eg ['checkpoints', 'loras', ...])\n   * @returns The list of model folder keys\n   */\n  async getModelFolders(): Promise<ModelFolderInfo[]> {\n    const res = await this.fetchApi(`/experiment/models`)\n    if (res.status === 404) {\n      return []\n    }\n    const folderBlacklist = ['configs', 'custom_nodes']\n    return (await res.json()).filter(\n      (folder: ModelFolderInfo) => !folderBlacklist.includes(folder.name)\n    )\n  }\n\n  /**\n   * Gets a list of models in the specified folder\n   * @param {string} folder The folder to list models from, such as 'checkpoints'\n   * @returns The list of model filenames within the specified folder\n   */\n  async getModels(folder: string): Promise<ModelFile[]> {\n    const res = await this.fetchApi(`/experiment/models/${folder}`)\n    if (res.status === 404) {\n      return []\n    }\n    return await res.json()\n  }\n\n  /**\n   * Gets the metadata for a model\n   * @param {string} folder The folder containing the model\n   * @param {string} model The model to get metadata for\n   * @returns The metadata for the model\n   */\n  async viewMetadata(folder: string, model: string) {\n    const res = await this.fetchApi(\n      `/view_metadata/${folder}?filename=${encodeURIComponent(model)}`\n    )\n    const rawResponse = await res.text()\n    if (!rawResponse) {\n      return null\n    }\n    try {\n      return JSON.parse(rawResponse)\n    } catch (error) {\n      console.error(\n        'Error viewing metadata',\n        res.status,\n        res.statusText,\n        rawResponse,\n        error\n      )\n      return null\n    }\n  }\n\n  /**\n   * Loads a list of items (queue or history)\n   * @param {string} type The type of items to load, queue or history\n   * @returns The items of the specified type grouped by their status\n   */\n  async getItems(type: 'queue' | 'history') {\n    if (type === 'queue') {\n      return this.getQueue()\n    }\n    return this.getHistory()\n  }\n\n  /**\n   * Gets the current state of the queue\n   * @returns The currently running and queued items\n   */\n  async getQueue(options?: { throwOnError?: boolean }): Promise<{\n    Running: JobListItem[]\n    Pending: JobListItem[]\n  }> {\n    try {\n      return await fetchQueue(this.fetchApi.bind(this), options)\n    } catch (error) {\n      if (options?.throwOnError) throw error\n      console.error('Failed to fetch queue:', error)\n      return { Running: [], Pending: [] }\n    }\n  }\n\n  /**\n   * Gets the prompt execution history\n   * @returns Prompt history including node outputs\n   */\n  async getHistory(\n    max_items: number = 200,\n    options?: { offset?: number }\n  ): Promise<JobListItem[]> {\n    try {\n      return await fetchHistory(\n        this.fetchApi.bind(this),\n        max_items,\n        options?.offset\n      )\n    } catch (error) {\n      console.error(error)\n      return []\n    }\n  }\n\n  /**\n   * Gets detailed job info including outputs and workflow\n   * @param jobId The job ID\n   * @returns Full job details or undefined if not found\n   */\n  async getJobDetail(jobId: string): Promise<JobDetail | undefined> {\n    return fetchJobDetail(this.fetchApi.bind(this), jobId)\n  }\n\n  /**\n   * Gets a job's output assets, each resolved to a real asset entity with\n   * per-output node context. Returns an empty list when the endpoint is\n   * unavailable (e.g. non-cloud distributions).\n   * @param jobId The job ID\n   * @returns The job's output assets and whether the list is exhaustive\n   */\n  async getJobAssets(jobId: string): Promise<JobAssetsResult> {\n    return fetchJobAssets(this.fetchApi.bind(this), jobId)\n  }\n\n  /**\n   * Gets system & device stats\n   * @returns System stats such as python version, OS, per device info\n   */\n  async getSystemStats(): Promise<SystemStats> {\n    const res = await this.fetchApi('/system_stats')\n    return await res.json()\n  }\n\n  /**\n   * Sends a POST request to the API\n   * @param {*} type The endpoint to post to\n   * @param {*} body Optional POST data\n   */\n  private async _postItem(type: string, body?: Record<string, unknown>) {\n    try {\n      await this.fetchApi('/' + type, {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json'\n        },\n        body: body ? JSON.stringify(body) : undefined\n      })\n    } catch (error) {\n      console.error(error)\n    }\n  }\n\n  /**\n   * Deletes an item from the specified list\n   * @param {string} type The type of item to delete, queue or history\n   * @param {number} id The id of the item to delete\n   */\n  async deleteItem(type: string, id: string) {\n    await this._postItem(type, { delete: [id] })\n  }\n\n  /**\n   * Clears the specified list\n   * @param {string} type The type of list to clear, queue or history\n   */\n  async clearItems(type: string) {\n    await this._postItem(type, { clear: true })\n  }\n\n  /**\n   * Interrupts the execution of the running job. If runningJobId is provided,\n   * it is included in the payload as a helpful hint to the backend.\n   * @param {string | null} [runningJobId] Optional Running Job ID to interrupt\n   */\n  async interrupt(runningJobId: string | null) {\n    await this._postItem(\n      'interrupt',\n      runningJobId ? { prompt_id: runningJobId } : undefined\n    )\n  }\n\n  /**\n   * Cancels a single job by id via `POST /api/jobs/{job_id}/cancel` (idempotent:\n   * already-terminal jobs are a no-op). Requires runtime parity — not every\n   * runtime exposes this endpoint yet; do not merge callers before parity lands.\n   *\n   * @param {string} jobId The id of the job to cancel\n   */\n  async cancelJob(jobId: string) {\n    const res = await this.fetchApi(\n      `/jobs/${encodeURIComponent(jobId)}/cancel`,\n      {\n        method: 'POST'\n      }\n    )\n    if (!res.ok) {\n      const body = await res.text().catch(() => '')\n      throw new Error(\n        `Failed to cancel job ${jobId}: ${res.status}${body ? ` — ${body}` : ''}`\n      )\n    }\n  }\n\n  /**\n   * Cancels multiple jobs in a single request via `POST /api/jobs/cancel` with\n   * body `{ job_ids: [...] }`. Already-terminal jobs are no-ops. Same runtime\n   * parity requirement as {@link cancelJob}.\n   *\n   * @param {string[]} jobIds The ids of the jobs to cancel\n   */\n  async cancelJobs(jobIds: string[]) {\n    if (!jobIds.length) return\n    const res = await this.fetchApi('/jobs/cancel', {\n      method: 'POST',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify({ job_ids: jobIds })\n    })\n    if (!res.ok) {\n      const body = await res.text().catch(() => '')\n      throw new Error(\n        `Failed to cancel jobs: ${res.status}${body ? ` — ${body}` : ''}`\n      )\n    }\n  }\n\n  /**\n   * Gets user configuration data and where data should be stored\n   */\n  async getUserConfig(): Promise<UserConfigResponse> {\n    return (await this.fetchApi('/users')).json()\n  }\n\n  /**\n   * Creates a new user\n   * @param { string } username\n   * @returns The fetch response\n   */\n  createUser(username: string) {\n    return this.fetchApi('/users', {\n      method: 'POST',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify({ username })\n    })\n  }\n\n  /**\n   * Gets all setting values for the current user\n   * @returns { Promise<string, unknown> } A dictionary of id -> value\n   */\n  async getSettings(): Promise<Settings> {\n    const resp = await this.fetchApi('/settings')\n\n    if (resp.status == 401) {\n      // `statusText` is ALWAYS empty over HTTP/2 — the protocol carries no\n      // reason phrase — and cloud.comfy.org is HTTP/2. Passing it straight\n      // through produced `new UnauthorizedError('')`, which the global\n      // onerror handler reported to Sentry as the untitled group\n      // \"Error: No error message\": 165,890 events in 14 days across 25,417\n      // users, all of them unactionable because nothing in the event said\n      // which request had failed.\n      throw new UnauthorizedError(\n        `Failed to load settings: 401 ${resp.statusText || 'Unauthorized'}`\n      )\n    }\n    return await resp.json()\n  }\n\n  /**\n   * Gets a setting for the current user\n   * @param { string } id The id of the setting to fetch\n   * @returns { Promise<unknown> } The setting value\n   */\n  async getSetting(id: keyof Settings): Promise<Settings[keyof Settings]> {\n    return (await this.fetchApi(`/settings/${encodeURIComponent(id)}`)).json()\n  }\n\n  /**\n   * Stores a dictionary of settings for the current user\n   */\n  async storeSettings(settings: Partial<Settings>) {\n    return this.fetchApi(`/settings`, {\n      method: 'POST',\n      body: JSON.stringify(settings)\n    })\n  }\n\n  /**\n   * Stores a setting for the current user\n   */\n  async storeSetting(id: keyof Settings, value: Settings[keyof Settings]) {\n    return this.fetchApi(`/settings/${encodeURIComponent(id)}`, {\n      method: 'POST',\n      body: JSON.stringify(value)\n    })\n  }\n\n  /**\n   * Gets a user data file for the current user\n   */\n  async getUserData(file: string, options?: RequestInit) {\n    return this.fetchApi(`/userdata/${encodeURIComponent(file)}`, options)\n  }\n\n  /**\n   * Stores a user data file for the current user\n   * @param { string } file The name of the userdata file to save\n   * @param { unknown } data The data to save to the file\n   * @param { RequestInit & { stringify?: boolean, throwOnError?: boolean } } [options]\n   * @returns { Promise<Response> }\n   */\n  async storeUserData(\n    file: string,\n    data: unknown,\n    options: RequestInit & {\n      overwrite?: boolean\n      stringify?: boolean\n      throwOnError?: boolean\n      full_info?: boolean\n    } = {\n      overwrite: true,\n      stringify: true,\n      throwOnError: true,\n      full_info: false\n    }\n  ): Promise<Response> {\n    const overwrite = options.overwrite ?? true\n    const fullInfo = options.full_info ?? false\n    const route = `/userdata/${encodeURIComponent(file)}?overwrite=${overwrite}&full_info=${fullInfo}`\n    const resp = await this.fetchApi(route, {\n      method: 'POST',\n      body: options.stringify ? JSON.stringify(data) : (data as BodyInit),\n      ...options\n    })\n    if (resp.status !== 200) {\n      const message = `Error storing user data file '${file}': ${resp.status} ${resp.statusText}`\n      // The reported message and route are file-independent: the literal file\n      // name (and `route`, which embeds it) is unbounded cardinality and\n      // would fragment Sentry grouping into one bucket per file instead of\n      // one for this failure mode — exactly what buried PM-1906's alerts.\n      reportError(\n        new Error(\n          `Error storing user data file: ${resp.status} ${resp.statusText}`\n        ),\n        {\n          errorType: 'userdata_store_failure',\n          surface: 'platform',\n          tags: {\n            status: resp.status,\n            overwrite,\n            full_info: fullInfo\n          },\n          context: {\n            file,\n            route: `/userdata/{file}?overwrite=${overwrite}&full_info=${fullInfo}`\n          }\n        }\n      )\n      if (options.throwOnError !== false) {\n        throw new Error(message)\n      }\n    }\n\n    return resp\n  }\n\n  /**\n   * Deletes a user data file for the current user\n   * @param { string } file The name of the userdata file to delete\n   */\n  async deleteUserData(file: string) {\n    const resp = await this.fetchApi(`/userdata/${encodeURIComponent(file)}`, {\n      method: 'DELETE'\n    })\n    return resp\n  }\n\n  /**\n   * Move a user data file for the current user\n   * @param { string } source The userdata file to move\n   * @param { string } dest The destination for the file\n   */\n  async moveUserData(\n    source: string,\n    dest: string,\n    options = { overwrite: false }\n  ) {\n    const resp = await this.fetchApi(\n      `/userdata/${encodeURIComponent(source)}/move/${encodeURIComponent(dest)}?overwrite=${options.overwrite}`,\n      {\n        method: 'POST'\n      }\n    )\n    return resp\n  }\n\n  async listUserDataFullInfo(dir: string): Promise<UserDataFullInfo[]> {\n    const trimmedDir = trimEnd(dir, '/')\n    const resp = await this.fetchApi(\n      `/userdata?dir=${encodeURIComponent(trimmedDir)}&recurse=true&split=false&full_info=true`\n    )\n    if (resp.status === 404) return []\n    if (resp.status !== 200) {